--cleaned by кровь из носа и бутылка водки
--discord: nnnnnonononothavingaseizure
pcall(function() game.Players.LocalPlayer.PlayerScripts.CharacterAndBeamMove.Enabled = false end)
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local CoreGui = game:GetService("CoreGui")
pcall(function() loadstring(game:HttpGet('https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source'))() end) -- HttpGet/loadstring only exist in executor environments
-- [UI] XOCU library removed — fluxy now renders through the Zyrix interface,
-- using the same pattern as the Example script: skip the default demo hub and
-- build our own window directly on the Zyrix library (StarterGui.ZYRIXUI).
-- Studio compatibility: executors provide getgenv(); define it if missing so all
-- getgenv() calls throughout this script resolve to the shared _G environment.
if typeof(getgenv) ~= "function" then
	getgenv = function() return _G end
end
local genv = (getgenv and getgenv()) or _G
genv.ZyrixSkipDefaultHub = true

-- ========== ALL-DEVICE COMPAT ==========
-- PC / Mobile / Tablet / Console
do
	local UIS = game:GetService("UserInputService")
	local GuiService = game:GetService("GuiService")
	local touch = UIS.TouchEnabled
	local keyboard = UIS.KeyboardEnabled
	local gamepad = UIS.GamepadEnabled
	local device = "PC"
	if gamepad and not keyboard and not touch then
		device = "Console"
	elseif touch and not keyboard then
		device = "Mobile"
	elseif touch and keyboard then
		device = "Tablet"
	elseif keyboard then
		device = "PC"
	else
		device = "Unknown"
	end
	genv.FluxyDevice = device
	-- Treat pure touch + tablets as mobile UI scale
	genv.ZyrixMobile = (device == "Mobile" or device == "Tablet" or (touch and not keyboard))
	genv.FluxyIsMobile = genv.ZyrixMobile
	genv.FluxyIsTouch = touch
	genv.FluxyIsGamepad = gamepad

	-- Prefer MoveDirection on touch devices (WASD not available)
	function genv.FluxyGetMoveDir(cam, root)
		local hum = root and root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
		if genv.FluxyIsTouch or genv.FluxyIsMobile then
			if hum and hum.MoveDirection.Magnitude > 0.05 then
				return hum.MoveDirection
			end
		end
		local moveDir = Vector3.zero
		pcall(function()
			if UIS:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + cam.CFrame.LookVector end
			if UIS:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - cam.CFrame.LookVector end
			if UIS:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - cam.CFrame.RightVector end
			if UIS:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + cam.CFrame.RightVector end
			if UIS:IsKeyDown(Enum.KeyCode.Space) or UIS:IsKeyDown(Enum.KeyCode.ButtonA) then
				moveDir = moveDir + Vector3.new(0, 1, 0)
			end
			if UIS:IsKeyDown(Enum.KeyCode.LeftShift) or UIS:IsKeyDown(Enum.KeyCode.ButtonB) then
				moveDir = moveDir - Vector3.new(0, 1, 0)
			end
			-- Gamepad left stick
			local ok, state = pcall(function()
				return UIS:GetGamepadState(Enum.UserInputType.Gamepad1)
			end)
			-- Fallback: thumbstick via GetPropertyChanged - use MoveDirection
			if hum and hum.MoveDirection.Magnitude > 0.05 then
				local md = hum.MoveDirection
				moveDir = Vector3.new(md.X, moveDir.Y, md.Z)
			end
		end)
		if moveDir.Magnitude > 0.01 then
			return moveDir.Unit
		end
		return Vector3.zero
	end

	-- Mobile: ensure GuiService doesn't block UI; touch insets
	pcall(function()
		if genv.FluxyIsMobile then
			GuiService.TouchControlsEnabled = true
		end
	end)
end

-- Mobile: slightly larger UI scale when touch device
pcall(function()
	local UIS = game:GetService("UserInputService")
	if UIS.TouchEnabled and not UIS.KeyboardEnabled then
		genv.ZyrixMobile = true
	end
end)

genv._FluxyLaunched = nil -- allow re-execute to show UI again
genv.ZyrixForceReload = true -- skip the default demo hub
if game:GetService("RunService"):IsStudio() then
	genv.SCRIPT_KEY = "FluxVI4T" -- Studio playtest: pre-verify the key so Zyrix:Launch()
	-- skips the key window and opens the hub immediately instead of waiting for
	-- manual key entry on every playtest.
else
	-- Always pre-set key so Launch never sits on key screen
	genv.SCRIPT_KEY = genv.SCRIPT_KEY or "FluxVI4T"
end

-- Load the Zyrix library exactly like the Example LocalScript: one direct
-- loadstring(game:HttpGet(...)) call, with ZyrixSkipDefaultHub already set
-- above so the library's demo/example hub never builds. In Studio (no
-- loadstring/HttpGet), wait for the StarterGui.ZYRIXUI LocalScript to expose
-- the library instead.
local Zyrix
if loadstring and game.HttpGet and not game:GetService("RunService"):IsStudio() then
	-- Fresh run: tear down any hub left over from a previous execution in
	-- this session so fluxy always builds on a clean slate.
	local g = (getgenv and getgenv()) or _G
	if g.Zyrix and g.Zyrix.Reset then
		pcall(function() g.Zyrix:Reset() end)
	end
	Zyrix = loadstring(game:HttpGet("https://raw.githubusercontent.com/VYZ3N-scripts/Zyrix/main/Zyrix.lua"))()
else
	local deadline = os.clock() + 15
	while not (genv.Zyrix and genv.ZyrixUI) do
		if os.clock() > deadline then break end
		task.wait(0.1)
	end
	Zyrix = genv.Zyrix
end

local Library = (function()
	-- Zyrix was loaded directly above (Example-script pattern), so there is
	-- nothing to wait for here. Just brand the key UI so it's obvious the
	-- fluxy hub loaded (the library default is "B4TMAN // Interface", which
	-- is exactly what its demo/example hub shows).
	if Zyrix and Zyrix.Appearance then
		Zyrix.Appearance.Title = "FLUXY"
		Zyrix.Appearance.Subtitle = "script hub"
		-- Cleaner Fluxy palette
		if Zyrix.BatmanTheme then
			Zyrix.BatmanTheme.Accent = Color3.fromRGB(200, 200, 210)
			Zyrix.BatmanTheme.AccentHover = Color3.fromRGB(160, 160, 175)
			Zyrix.BatmanTheme.Background = Color3.fromRGB(10, 10, 12)
			Zyrix.BatmanTheme.TabBar = Color3.fromRGB(14, 14, 16)
			Zyrix.BatmanTheme.TabIdle = Color3.fromRGB(12, 12, 14)
			Zyrix.BatmanTheme.TabActive = Color3.fromRGB(24, 24, 28)
			Zyrix.BatmanTheme.Panel = Color3.fromRGB(14, 14, 16)
			Zyrix.BatmanTheme.Element = Color3.fromRGB(16, 16, 18)
			Zyrix.BatmanTheme.Inner = Color3.fromRGB(22, 22, 26)
			Zyrix.BatmanTheme.Progress = Color3.fromRGB(200, 200, 210)
			Zyrix.BatmanTheme.KnobOn = Color3.fromRGB(220, 220, 230)
			Zyrix.BatmanTheme.Stroke = Color3.fromRGB(40, 40, 48)
			Zyrix.BatmanTheme.StrokeIn = Color3.fromRGB(50, 50, 58)
			Zyrix.BatmanTheme.Divider = Color3.fromRGB(32, 32, 38)
			Zyrix.BatmanTheme.Text = Color3.fromRGB(240, 240, 245)
			Zyrix.BatmanTheme.TextDim = Color3.fromRGB(140, 140, 150)
			Zyrix.BatmanTheme.Hover = Color3.fromRGB(28, 28, 32)
		end
		if Zyrix.Theme then
			Zyrix.Theme.Accent = Color3.fromRGB(200, 200, 210)
			Zyrix.Theme.Background = Color3.fromRGB(10, 10, 12)
			Zyrix.Theme.Header = Color3.fromRGB(14, 14, 16)
			Zyrix.Theme.Input = Color3.fromRGB(22, 22, 26)
			Zyrix.Theme.Text = Color3.fromRGB(240, 240, 245)
			Zyrix.Theme.TextDim = Color3.fromRGB(140, 140, 150)
		end
	end

	-- Fallback: Zyrix never showed up — return a no-op UI stub so the rest of
	-- the script (and its features) still initialize safely.
	if not Zyrix then
		local function noop() end
		local function mkEl() return { Set = noop, SetOptions = noop, SetDisplay = noop, Refresh = noop } end
		local elementNames = { "CreateToggle", "CreateSlider", "CreateDropdown", "CreateInput", "CreateKeybind", "CreateButton" }
		local Block = {}
		for _, m in ipairs(elementNames) do Block[m] = function() return mkEl() end end
		local Tab = { CreateBlock = function() return Block end }
		for _, m in ipairs(elementNames) do Tab[m] = function() return mkEl() end end
		local Window = { CreateTab = function() return Tab end }
		return { Items = {}, Flags = {}, Notify = noop, CreateWindow = function() return Window end }
	end

	local Library = { Items = {}, Flags = {} }
	Library._Zyrix = Zyrix -- exposed so the end of this script can call Zyrix:Launch()

	function Library:Notify(a, b)
		if type(a) == "table" then
			pcall(function() Zyrix:Notify(a.Title or "Notification", a.Content or a.Description or "", a.Duration or 5) end)
		else
			pcall(function() Zyrix:Notify("Notification", tostring(a), b or 5) end)
		end
	end

	function Library:CreateWindow(config)
		config = config or {}
		local toggleBind = config.ToggleKey
		if typeof(toggleBind) == "EnumItem" then toggleBind = toggleBind.Name end
		local window = Zyrix:CreateWindow({
			Name = "FLUXY",
			ToggleUIKeybind = toggleBind,
			-- Keep the key system exactly as the Zyrix hub configured it
			KeySystem = false,
			KeySettings = {
				Title = "Key System",
				Subtitle = "Enter your key",
				Key = "FluxVI4T",
				SaveKey = false,
			},
		})

		-- Registration counter (diagnostics only). The hub itself is launched by
		-- Zyrix:Launch() at the very end of this script, exactly like the Example
		-- script: the key window appears first, and the hub with all the fluxy
		-- tabs builds automatically once the key is verified.
		local regCount = 0

		local function makeBlock(ztab, blockSide)
			local Block = {}
			function Block:CreateToggle(o)
				o = o or {}
				local g = (getgenv and getgenv()) or _G
				local key = tostring(o.Flag or o.Name or "toggle")
				local startVal = o.Default
				if g.FluxySaved then
					local sv = g.FluxySaved[key] or g.FluxySaved["toggle:" .. key]
					if sv ~= nil then startVal = sv and true or false end
				end
				local ret = ztab:CreateToggle({
					Name = o.Name,
					CurrentValue = startVal,
					Callback = function(v)
						local on = v and true or false
						if g.FluxyRememberValue then
							g.FluxyRememberValue(key, on)
							g.FluxyRememberValue("toggle:" .. key, on)
						end
						if o.Callback then o.Callback(on) end
					end,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
				if g.FluxyRegisterSetter then
					g.FluxyRegisterSetter(key, function(val)
						local on = val and true or false
						pcall(function() if ret and ret.Set then ret:Set(on, false) end end)
						if o.Callback then pcall(o.Callback, on) end
					end)
				end
				return ret
			end
			function Block:CreateSlider(o)
				o = o or {}
				local g = (getgenv and getgenv()) or _G
				local key = tostring(o.Flag or o.Name or "slider")
				local minV = o.Min or 0
				local maxV = o.Max or 100
				local startVal = o.Default or minV
				if g.FluxySaved and g.FluxySaved[key] ~= nil then
					startVal = tonumber(g.FluxySaved[key]) or startVal
				end
				local ret = ztab:CreateSlider({
					Name = o.Name,
					Range = { minV, maxV },
					CurrentValue = startVal,
					Suffix = o.Suffix,
					Callback = function(v)
						if g.FluxyRememberValue then g.FluxyRememberValue(key, tonumber(v) or v) end
						if o.Callback then o.Callback(v) end
					end,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
				if g.FluxyRegisterSetter then
					g.FluxyRegisterSetter(key, function(val)
						local n = tonumber(val)
						if n and ret and ret.Set then pcall(function() ret:Set(n) end) end
						if o.Callback and n then pcall(o.Callback, n) end
					end)
				end
				return ret
			end
			function Block:CreateDropdown(o)
				o = o or {}
				local items = o.Items or o.List or o.Options or {}
				local stickyKey = tostring(o.Name or o.Flag or "dropdown")
				local g0 = (getgenv and getgenv()) or _G
				-- Prefer sticky saved selection as default
				local stickyWant = g0.FluxyStickyPlayers and (g0.FluxyStickyPlayers[stickyKey] or g0.FluxyStickyPlayers._last)
				local current = o.CurrentOption or o.Default
				if stickyWant then
					for _, entry in ipairs(items) do
						if tostring(entry):find(stickyWant, 1, true) then
							current = entry
							break
						end
					end
					if current == o.CurrentOption or current == o.Default then
						current = stickyWant
					end
				end
				if current ~= nil and type(current) ~= "table" then current = { current } end
				local isMulti = o.Multi == true
				local ret = ztab:CreateDropdown({
					Name = o.Name,
					Options = items,
					CurrentOption = current,
					Searchable = o.Searchable,
					Multi = isMulti,
					Callback = function(v)
						if isMulti then
							local picks = type(v) == "table" and v or {v}
							if o.Callback then o.Callback(picks) end
						else
							local pick = type(v) == "table" and v[1] or v
							if g0.FluxyRememberPlayer then
								g0.FluxyRememberPlayer(stickyKey, pick)
							end
							if o.Callback then o.Callback(pick) end
						end
					end,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
				if type(ret) == "table" then
					ret._stickyKey = stickyKey
					if not ret.SetOptions then
						ret.SetOptions = function(_, newOptions)
							if type(newOptions) ~= "table" then return end
							pcall(function()
								if ret.Refresh then ret:Refresh(newOptions, true) end
							end)
						end
					end
					ret.Refresh = function(_, newList, keepSelection)
						if type(newList) ~= "table" then return end
						local g = (getgenv and getgenv()) or _G
						local sticky = g.FluxyStickyPlayers or {}
						local want = sticky[stickyKey] or sticky._last
						pcall(function() ret:SetOptions(newList) end)
						if keepSelection == false and not want then return end
						if want then
							local pick = nil
							for _, entry in ipairs(newList) do
								local s = tostring(entry)
								if s == want or s:find(want, 1, true) then
									pick = entry
									break
								end
							end
							if pick then
								pcall(function() ret:Set(pick) end)
							else
								pcall(function()
									if ret.SetDisplay then ret:SetDisplay(want)
									else ret:Set(want) end
								end)
							end
						end
					end
				end
				return ret
			end
			function Block:CreateMultiDropdown(o)
				o = o or {}
				o.Multi = true
				return Block:CreateDropdown(o)
			end
			function Block:CreateInput(o)
				o = o or {}
				return ztab:CreateInput({
					Name = o.Name,
					PlaceholderText = o.PlaceholderText or (o.TextDisappear and o.Default) or "",
					Callback = o.Callback,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
			end
			function Block:CreateKeybind(o)
				o = o or {}
				local kb = o.CurrentKeybind or o.Default or "Q"
				if typeof(kb) == "EnumItem" then kb = kb.Name end
				return ztab:CreateKeybind({
					Name = o.Name,
					CurrentKeybind = kb,
					Callback = o.Callback,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
			end
			function Block:CreateButton(o)
				o = o or {}
				return ztab:CreateButton({
					Name = o.Name,
					Callback = o.Callback,
					Side = (type(o.Side) == "string" and string.lower(o.Side)) or blockSide,
				})
			end
			-- Track registration activity so the watcher above can tell when
			-- fluxy's UI is fully registered.
			for _, m in ipairs({ "CreateToggle", "CreateSlider", "CreateDropdown", "CreateInput", "CreateKeybind", "CreateButton" }) do
				local orig = Block[m]
				Block[m] = function(self, o)
					regCount += 1
					return orig(self, o)
				end
			end
			return Block
		end

		local Window = {}
		function Window:CreateTab(name, _, icon)
			regCount += 1
			local ztab = window:CreateTab(name, icon)
			local Tab = {}
			function Tab:CreateBlock(opts)
				opts = opts or {}
				regCount += 1
				-- SECTION FIX (not tabs): Zyrix CreateSection(title, side) places the
				-- header on left or right. Passing only the title forced every
				-- header onto the left column.
				local side = opts.Side
				if type(side) == "string" then
					side = string.lower(side)
					if side ~= "left" and side ~= "right" then side = nil end
				else
					side = nil
				end
				local secName = opts.Name
				if type(secName) == "string" and secName ~= "" and secName ~= "true" then
					pcall(function() ztab:CreateSection(secName, side) end)
				end
				return makeBlock(ztab, side)
			end
			-- Direct element creation on a tab (rare) also works
			for _, m in ipairs({ "CreateToggle", "CreateSlider", "CreateDropdown", "CreateInput", "CreateKeybind", "CreateButton", "CreateSection", "CreateLabel", "CreateDivider" }) do
				Tab[m] = function(_, ...)
					regCount += 1
					local res = ztab[m](ztab, ...)
					if m == "CreateDropdown" and type(res) == "table" and res.SetOptions and not res.Refresh then
						res.Refresh = function(_, newList, keepSelection)
							if type(newList) ~= "table" then return end
							local g = (getgenv and getgenv()) or _G
							local want = g.FluxyStickyPlayers and g.FluxyStickyPlayers._last
							pcall(function() res:SetOptions(newList) end)
							if want and res.Set then
								for _, entry in ipairs(newList) do
									if tostring(entry):find(want, 1, true) then
										pcall(function() res:Set(entry) end)
										return
									end
								end
								pcall(function() res:Set(want) end)
							end
						end
					end
					return res
				end
			end
			return Tab
		end
		return Window
	end

	return Library
end)()

Players = game:GetService('Players')
TweenService = game:GetService('TweenService')
-- Executor-style service globals this script relies on (UserInputService was
-- nil at load, crashing the script before the UI could be built; R is used as
-- RunService by many callbacks via R.Heartbeat)
UserInputService = game:GetService('UserInputService')
R = game:GetService('RunService')
Workspace = game:GetService('Workspace')
plr = Players.LocalPlayer
-- MenuGui does not exist in this game. Resolve the coin HUD without blocking:
-- if it is missing, fall back to inert stand-in instances so the rest of the
-- script (and the Zyrix UI) still loads instead of hanging on WaitForChild.
local playerGui = plr:FindFirstChild('PlayerGui') or plr:WaitForChild('PlayerGui', 10)
gui = playerGui and playerGui:FindFirstChild('MenuGui')
TopRight = gui and gui:FindFirstChild('TopRight')
CoinsFrame = TopRight and TopRight:FindFirstChild('CoinsFrame')
CoinsDisplay = CoinsFrame and CoinsFrame:FindFirstChild('CoinsDisplay')
CoinImage = CoinsDisplay and CoinsDisplay:FindFirstChild('CoinImage')
Coins = CoinsDisplay and CoinsDisplay:FindFirstChild('Coins')
CoinsButton = CoinsFrame and CoinsFrame:FindFirstChild('CoinsButton')
if not (gui and TopRight and CoinsFrame and CoinsDisplay and CoinImage and Coins and CoinsButton) then
	warn('[fluxy] MenuGui coin HUD not found in this game — skipping coin HUD customization')
	gui = gui or Instance.new('ScreenGui')
	TopRight = TopRight or Instance.new('Frame')
	CoinsFrame = CoinsFrame or Instance.new('Frame')
	CoinsDisplay = CoinsDisplay or Instance.new('Frame')
	CoinImage = CoinImage or Instance.new('ImageLabel')
	Coins = Coins or Instance.new('TextLabel')
	CoinsButton = CoinsButton or Instance.new('TextButton')
end

for _, v in ipairs(CoinsFrame:GetChildren())do
    if v:IsA('UICorner') or v:IsA('UIStroke') or v:IsA('UIPadding') or v:IsA('UIGradient') then
        v:Destroy()
    end
end
for _, v in ipairs(CoinsDisplay:GetChildren())do
    if v:IsA('UIListLayout') then
        v:Destroy()
    end
end

blur = Instance.new('ImageLabel')
blur.Name = 'GlassBlur'
blur.BackgroundTransparency = 1
blur.Size = UDim2.new(1, 0, 1, 0)
blur.Position = UDim2.new(0, 0, 0, 0)
blur.Image = 'rbxassetid://8992230677'
blur.ImageTransparency = 0.88
blur.ScaleType = Enum.ScaleType.Stretch
blur.ZIndex = CoinsFrame.ZIndex - 1
blur.Parent = CoinsFrame
CoinsFrame.BackgroundColor3 = Color3.fromRGB(12, 14, 18)
CoinsFrame.BackgroundTransparency = 0.35
CoinsFrame.AutomaticSize = Enum.AutomaticSize.X
CoinsFrame.Size = UDim2.new(0, 0, 0, 74)
corner = Instance.new('UICorner')
corner.CornerRadius = UDim.new(1, 0)
corner.Parent = CoinsFrame
padding = Instance.new('UIPadding')
padding.PaddingLeft = UDim.new(0, 10)
padding.PaddingRight = UDim.new(0, 10)
padding.Parent = CoinsFrame
stroke = Instance.new('UIStroke')
stroke.Thickness = 1
stroke.Transparency = 0.6
stroke.Color = Color3.fromRGB(135, 206, 235)
stroke.Parent = CoinsFrame
borderGrad = Instance.new('UIGradient')
borderGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(135, 206, 235)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(135, 206, 235)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(135, 206, 235)),
})
