    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
    local targetHRP = spinTarget.Character and spinTarget.Character:FindFirstChild('HumanoidRootPart')

    if hrp and targetHRP then
        local a = tick() * 2

        hrp.CFrame = targetHRP.CFrame * CFrame.new(math.cos(a) * 8, 2, math.sin(a) * 8)
    end
end)

-- Global state storage
local ToggleStates = {}
function SetToggleState(flag, value)
	ToggleStates[flag] = value
	local g = (getgenv and getgenv()) or _G
	if g.FluxyApplying then return end
	if g.FluxySaveDebounce then g.FluxySaveDebounce() end
end
function GetToggleState(flag) return ToggleStates[flag] or false end

-- AUTO-SAVE / LOAD
do
	local g = (getgenv and getgenv()) or _G
	local HttpService = game:GetService("HttpService")
	local FILE = "Fluxy/autosave.json"
	g.FluxySaved = g.FluxySaved or {}
	g.FluxyUISetters = g.FluxyUISetters or {}

	local function canFS()
		return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
	end
	local function ensureFolder()
		pcall(function()
			if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder("Fluxy") then
				makefolder("Fluxy")
			end
		end)
	end

	function g.FluxyRegisterSetter(key, fn)
		if key and type(fn) == "function" then g.FluxyUISetters[tostring(key)] = fn end
	end

	function g.FluxyRememberValue(key, value)
		if key == nil then return end
		if g.FluxyApplying then return end -- don't save while restoring (stops lag storm)
		local k = tostring(key)
		local tv = type(value)
		if tv == "boolean" or tv == "number" or tv == "string" then
			g.FluxySaved[k] = value
		elseif tv == "table" then
			local copy = {}
			for a, b in pairs(value) do
				if type(b) == "string" or type(b) == "number" or type(b) == "boolean" then
					copy[a] = b
				end
			end
			g.FluxySaved[k] = copy
		end
		g.FluxySaveDebounce()
	end

	local saveScheduled = false
	function g.FluxySaveDebounce()
		-- save quickly after any setting change
		if saveScheduled then return end
		saveScheduled = true
		task.delay(0.6, function()
			saveScheduled = false
			g.FluxySaveNow()
		end)
	end

	function g.FluxySaveNow()
		if not canFS() then return end
		ensureFolder()
		for k, v in pairs(ToggleStates) do
			g.FluxySaved["toggle:" .. tostring(k)] = v and true or false
		end
		if g.FluxyStickyPlayers then g.FluxySaved.sticky = g.FluxyStickyPlayers end
		if g.FluxyCoconutAmount ~= nil then g.FluxySaved.cocoAmount = g.FluxyCoconutAmount end
		if g.FluxyCoconutDick ~= nil then g.FluxySaved.cocoDick = g.FluxyCoconutDick end
		pcall(function()
			writefile(FILE, HttpService:JSONEncode(g.FluxySaved))
		end)
	end

	function g.FluxyLoadNow()
		if not canFS() then return end
		local ok, data = pcall(function()
			if isfile(FILE) then return HttpService:JSONDecode(readfile(FILE)) end
		end)
		if not ok or type(data) ~= "table" then return end
		g.FluxySaved = data
		if type(data.sticky) == "table" then g.FluxyStickyPlayers = data.sticky end
		if data.cocoAmount ~= nil then g.FluxyCoconutAmount = data.cocoAmount end
		if data.cocoDick ~= nil then g.FluxyCoconutDick = data.cocoDick end
		for k, v in pairs(data) do
			if type(k) == "string" and k:sub(1, 7) == "toggle:" then
				ToggleStates[k:sub(8)] = v and true or false
			end
		end
	end

	function g.FluxyApplySaved()
		local data = g.FluxySaved
		if type(data) ~= "table" then return 0 end
		if g.FluxyApplyBusy then return 0 end
		g.FluxyApplyBusy = true
		g.FluxyApplying = true
		local n = 0
		-- Only registered UI setters (no full getgenv scan — that lags hard)
		for key, fn in pairs(g.FluxyUISetters) do
			local val = data[key]
			if val == nil then val = data["toggle:" .. tostring(key)] end
			if val ~= nil then
				if pcall(fn, val) then n = n + 1 end
			end
		end
		-- FTAP library if registered
		pcall(function()
			local lib = g.FluxyFTAPLibrary
			if type(lib) == "table" and type(lib._flagSetters) == "table" then
				for flag, setter in pairs(lib._flagSetters) do
					local val = data[flag] or data["toggle:" .. tostring(flag)]
					if val ~= nil and type(setter) == "function" then
						if pcall(setter, val) then n = n + 1 end
					end
				end
			end
		end)
		g.FluxyApplying = false
		g.FluxyApplyBusy = false
		return n
	end

	-- Load config file ASAP so CreateToggle/Slider can use saved defaults
	pcall(g.FluxyLoadNow)
end

-- Sticky player helpers (used by dropdowns + autosave)
do
	local g = (getgenv and getgenv()) or _G
	g.FluxyStickyPlayers = g.FluxyStickyPlayers or {}
	function g.FluxyRememberPlayer(key, sel)
		if type(sel) == "table" then sel = sel[1] or sel.Name end
		if not sel or sel == "" or sel == "None" then return end
		local s = tostring(sel)
		local user = s:match("%(@%s*(.-)%)") or s:match("@(%S+)") or s
		user = user:gsub("^%s+", ""):gsub("%s+$", "")
		if user == "" then return end
		if key then g.FluxyStickyPlayers[tostring(key)] = user end
		g.FluxyStickyPlayers._last = user
		if g.FluxySaveDebounce then g.FluxySaveDebounce() end
	end
	function g.FluxyResolvePlayer(sel)
		if type(sel) == "table" then sel = sel[1] end
		if not sel or sel == "" or sel == "None" then return nil end
		local s = tostring(sel)
		local user = s:match("%(@%s*(.-)%)") or s:match("@(%S+)") or s
		user = user:gsub("^%s+", ""):gsub("%s+$", "")
		local Players = game:GetService("Players")
		local p = Players:FindFirstChild(user)
		if p then return p end
		for _, pl in ipairs(Players:GetPlayers()) do
			if pl.Name == user or pl.DisplayName == user then return pl end
		end
		return nil
	end
	function g.FluxyBuildPlayerList(style)
		style = style or "at"
		local Players = game:GetService("Players")
		local LP = Players.LocalPlayer
		local list, seen = {}, {}
		for _, pl in ipairs(Players:GetPlayers()) do
			if pl ~= LP then
				seen[pl.Name] = true
				if style == "name" then
					table.insert(list, pl.Name)
				else
					table.insert(list, pl.DisplayName .. " (@" .. pl.Name .. ")")
				end
			end
		end
		for k, user in pairs(g.FluxyStickyPlayers or {}) do
			if k ~= "_last" and type(user) == "string" and user ~= "" and not seen[user] then
				seen[user] = true
				if style == "name" then
					table.insert(list, user)
				else
					table.insert(list, user .. " (@" .. user .. ")")
				end
			end
		end
		local last = g.FluxyStickyPlayers and g.FluxyStickyPlayers._last
		table.sort(list)
		if last then
			for i, entry in ipairs(list) do
				if tostring(entry):find(last, 1, true) then
					local pin = table.remove(list, i)
					table.insert(list, 1, pin)
					break
				end
			end
		end
		if #list == 0 then table.insert(list, "None") end
		return list
	end
end


-- Auto-save on change + auto-load on rejoin / new server
task.spawn(function()
	local g = (getgenv and getgenv()) or _G
	pcall(function()
		if g.FluxyLoadNow then g.FluxyLoadNow() end
	end)
	for _ = 1, 100 do
		if g._FluxyLaunched then break end
		task.wait(0.15)
	end
	-- Apply after UI exists so toggles actually RUN (not only look on)
	task.wait(2)
	pcall(function()
		if g.FluxyApplySaved then g.FluxyApplySaved() end
	end)
	task.wait(3)
	pcall(function()
		if g.FluxyApplySaved then g.FluxyApplySaved() end
	end)
	pcall(function()
		if g.Zyrix and g.Zyrix.Notify then
			g.Zyrix:Notify("Config", "Loaded — toggles/sliders restore on rejoin", 3, "success")
		end
	end)
end)

task.spawn(function()
	local g = (getgenv and getgenv()) or _G
	while true do
		task.wait(45)
		pcall(function()
			if g.FluxySaveNow then g.FluxySaveNow() end
		end)
	end
end)

