local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")
local PS = game:GetService("Players")
local RS = game:GetService("ReplicatedStorage")
local R = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = workspace
local Player = PS.LocalPlayer
local Camera = Workspace.CurrentCamera
local CE = RS:WaitForChild("CharacterEvents", 10)
local BeingHeld = Player:WaitForChild("IsHeld", 10)
local StruggleEvent = CE and CE:WaitForChild("Struggle")
function notify(title, content, duration)
	Library:Notify({ Title = title or "Notification", Content = content or "", Duration = duration or 5,
	 })
end
function sendHubLoadedMessage()
	local message = " Owner Version | XOCU loaded. "
	local sent = false
	pcall(function()
		local chatEvents = ReplicatedStorage:FindFirstChild("DefaultChatSystemChatEvents")
		if chatEvents then
			local say = chatEvents:FindFirstChild("SayMessageRequest")
			if say and typeof(say.FireServer) == "function" then
				say:FireServer(message, "All")
				sent = true
			end
		end
	end)
	if not sent then
		pcall(function()
			StarterGui:SetCore("ChatMakeSystemMessage", {
				Name = message;
				Color = Color3.fromRGB(255, 170, 0);
				Font = Enum.Font.SourceSansBold;
				FontSize = Enum.FontSize.Size18;
			})
		end)
	end
end
task.spawn(function()
	task.wait(1)
	sendHubLoadedMessage()
	pcall(function()
		sendToChat("│╭─🦇Fluxy FTAP Loaded🦇─╮│")
	end)
end)
local paintPartsBackup = {}
local paintConnections = {}
function deleteAllPaintParts()
	for _, obj in ipairs(Workspace:GetDescendants()) do
		if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
			local clone = obj:Clone()
			clone.Archivable = true
			paintPartsBackup[obj:GetDebugId()] = {
				clone = clone,
				parent = obj.Parent
			}
			obj:Destroy()
		end
	end
end
local function restorePaintParts()
	for _, data in pairs(paintPartsBackup) do
		if data.clone and data.parent then
			data.clone.Parent = data.parent
		end
	end
	paintPartsBackup = {}
end
local function watchNewPaintParts()
	table.insert(paintConnections, Workspace.DescendantAdded:Connect(function(obj)
		if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
			task.defer(function()
				if obj and obj.Parent then
					local clone = obj:Clone()
					clone.Archivable = true
					paintPartsBackup[obj:GetDebugId()] = {
						clone = clone,
						parent = obj.Parent
					}
					obj:Destroy()
				end
			end)
		end
	end))
end
local function disconnectWatchers()
	for _, conn in ipairs(paintConnections) do
		if conn.Connected then
			conn:Disconnect()
		end
	end
	paintConnections = {}
end
local function setTouchQuery(state)
	local char = Workspace:FindFirstChild(Player.Name)
	if not char then
		return
	end
	for _, v in ipairs(char:GetChildren()) do
		if v:IsA("Part") or v:IsA("BasePart") then
			v.CanTouch = state
			v.CanQuery = state
		end
	end
end
local antiGucciConnection
local safePosition
local restoreFrames = 0
local function spawnBlobman()
	local args = {
		[1] = "CreatureBlobman",
		[2] = CFrame.new(0, 5000000, 0),
		[3] = Vector3.new(0, 60, 0)
	}
	pcall(function()
		ReplicatedStorage.MenuToys.SpawnToyRemoteFunction:InvokeServer(unpack(args))
	end)
	local folder = Workspace:WaitForChild(Player.Name .. "SpawnedInToys", 5)
	if folder and folder:FindFirstChild("CreatureBlobman") then
		local blob = folder.CreatureBlobman
		if blob:FindFirstChild("Head") then
			blob.Head.CFrame = CFrame.new(0, 50000, 0)
			blob.Head.Anchored = true
		end
		notify("Success", "Blobman Spawned!", 3)
	end
end
local function startAntiGucci()
	local character = Player.Character or Player.CharacterAdded:Wait()
	local humanoid = character:WaitForChild("Humanoid")
	local rootPart = character:WaitForChild("HumanoidRootPart")
	safePosition = rootPart.Position
	local folder = Workspace:FindFirstChild(Player.Name .. "SpawnedInToys")
	local blob = folder and folder:FindFirstChild("CreatureBlobman")
	local seat = blob and blob:FindFirstChild("VehicleSeat")
	if not blob then
		spawnBlobman()
		task.wait(0.3)
		folder = Workspace:FindFirstChild(Player.Name .. "SpawnedInToys")
		blob = folder and folder:FindFirstChild("CreatureBlobman")
		seat = blob and blob:FindFirstChild("VehicleSeat")
	end
	if seat and seat:IsA("VehicleSeat") then
		rootPart.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
		seat:Sit(humanoid)
	end
	humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
		if humanoid.Jump and humanoid.Sit then
			restoreFrames = 15
			safePosition = rootPart.Position
		end
	end)
	if antiGucciConnection then
		antiGucciConnection:Disconnect()
	end
	antiGucciConnection = R.Heartbeat:Connect(function()
		if not rootPart or not humanoid then
			return
		end
		ReplicatedStorage.CharacterEvents.RagdollRemote:FireServer(rootPart, 0)
		if restoreFrames > 0 then
			rootPart.CFrame = CFrame.new(safePosition)
			restoreFrames = restoreFrames - 1
		end
	end)
	task.spawn(function()
		while humanoid.Sit do
			task.wait(1)
		end
		task.wait(0.5)
		rootPart.CFrame = CFrame.new(safePosition)
	end)
end
local function stopAntiGucci()
	if antiGucciConnection then
		antiGucciConnection:Disconnect()
		antiGucciConnection = nil
	end
	-- Unsit humanoid first so the server releases the seat
	local char = Player.Character
	local hum = char and char:FindFirstChild("Humanoid")
	if hum then
		hum.Sit = false
		pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
	end
	local blobFolder = Workspace:FindFirstChild(Player.Name .. "SpawnedInToys")
	if blobFolder and blobFolder:FindFirstChild("CreatureBlobman") then
		local blob = blobFolder.CreatureBlobman
		-- Fire server-side destroy remote so it fully removes server-side
		pcall(function()
			ReplicatedStorage.MenuToys.DestroyToy:FireServer(blob)
		end)
		task.wait(0.1)
		-- Fallback local destroy in case remote didn't work
		if blob and blob.Parent then
			blob:Destroy()
		end
	end
end
local antiGucciConnectionTrain
local safePositionTrain
local restoreFramesTrain = 0
local function startAntiGucciTrain()
	local character = Player.Character or Player.CharacterAdded:Wait()
	local humanoid = character:WaitForChild("Humanoid")
	local rootPart = character:WaitForChild("HumanoidRootPart")
	safePositionTrain = rootPart.Position
	local folder = workspace.Map.AlwaysHereTweenedObjects
	local train = folder and folder:FindFirstChild("Train")
	local seat
	if train then
		for _, d in ipairs(train:GetDescendants()) do
			if d:IsA("Seat") then
				seat = d
				break
			end
		end
	end
	if seat then
		rootPart.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
		seat:Sit(humanoid)
	end
	humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
		if humanoid.Jump and humanoid.Sit then
			restoreFramesTrain = 15
			safePositionTrain = rootPart.Position
		end
	end)
	if antiGucciConnectionTrain then
		antiGucciConnectionTrain:Disconnect()
	end
	antiGucciConnectionTrain = R.Heartbeat:Connect(function()
		if not rootPart or not humanoid then
			return
		end
		ReplicatedStorage.CharacterEvents.RagdollRemote:FireServer(rootPart, 0)
		if restoreFramesTrain > 0 then
			rootPart.CFrame = CFrame.new(safePositionTrain)
			restoreFramesTrain = restoreFramesTrain - 1
		end
	end)
	task.spawn(function()
		while humanoid.Sit do
			task.wait(1)
		end
		task.wait(0.5)
		rootPart.CFrame = CFrame.new(safePositionTrain)
	end)
end
local function stopAntiGucciTrain()
	if antiGucciConnectionTrain then
		antiGucciConnectionTrain:Disconnect()
		antiGucciConnectionTrain = nil
	end
	local trainFolder = workspace.Map.AlwaysHereTweenedObjects
	if trainFolder and trainFolder:FindFirstChild("Train") then
		ResetPlayer(game.Players.LocalPlayer)
	end
end

local DefenseGroup = Tabs.Defense:CreateBlock({Name = "Anti Grab", Side = "Left"})
local DefenseExtra = Tabs.Defense:CreateBlock({Name = "Protections", Side = "Right"})

-- =====================================================================
-- 3RD PARTY DEFENSE
-- Anti-Grab = clean PartOwner manager ONLY (no shuriken)
-- Anti-Kick = shuriken STAYS on target (Defense Anti-Shuriken style)
-- =====================================================================
do
	local TP_Players = game:GetService("Players")
	local TP_RS = game:GetService("ReplicatedStorage")
	local TP_RunService = game:GetService("RunService")
	local TP_LP = TP_Players.LocalPlayer

	local GrabEventsFolder = TP_RS:FindFirstChild("GrabEvents") or TP_RS:WaitForChild("GrabEvents", 5)
	local RemoteEventHandler = {
		SetNetworkOwner = GrabEventsFolder and GrabEventsFolder:FindFirstChild("SetNetworkOwner"),
		DestroyGrabLine = GrabEventsFolder and GrabEventsFolder:FindFirstChild("DestroyGrabLine"),
	}

	local function AttemptNetworkShip(part)
		if not part or not part.Parent then return false end
		local partOwner = part:FindFirstChild("PartOwner")
		if partOwner and partOwner.Value == TP_LP.Name then
			return true
		end
		local root = TP_LP.Character and TP_LP.Character:FindFirstChild("HumanoidRootPart")
		if not root or not RemoteEventHandler.SetNetworkOwner then return false end
		pcall(function()
			RemoteEventHandler.SetNetworkOwner:FireServer(part, CFrame.lookAt(root.Position, part.Position))
		end)
		for _ = 1, 5 do
			task.wait(0.05)
			local po = part:FindFirstChild("PartOwner")
			if po and po.Value == TP_LP.Name then return true end
		end
		return false
	end

	-- ========== Anti-Grab Manager (NO shuriken) ==========
	local AntiGrabManager = {
		active_managers = setmetatable({}, { __mode = "k" }),
		default = { anti_grab = false, max_teleport_distance = 30 },
	}
	AntiGrabManager.__index = AntiGrabManager

	function AntiGrabManager:AntiGrabPlayer(character)
		if self.anti_grab_conn then pcall(function() self.anti_grab_conn:Disconnect() end) self.anti_grab_conn = nil end
		if self.po_hook then pcall(function() self.po_hook:Disconnect() end) self.po_hook = nil end
		if self.hb_conn then pcall(function() self.hb_conn:Disconnect() end) self.hb_conn = nil end
		local hrp = character:WaitForChild("HumanoidRootPart", 5)
		if not hrp then return end
		self.busy = false
		self.active_grab_part = nil

		-- Fire ownership + destroy line with ZERO wait (waiting was the lag/delay)
		local function instantClaim(part)
			if not part or not part.Parent then return end
			local root = TP_LP.Character and TP_LP.Character:FindFirstChild("HumanoidRootPart")
			if RemoteEventHandler.SetNetworkOwner and root then
				pcall(function()
					RemoteEventHandler.SetNetworkOwner:FireServer(part, CFrame.lookAt(root.Position, part.Position))
				end)
			end
			if RemoteEventHandler.DestroyGrabLine then
				pcall(function() RemoteEventHandler.DestroyGrabLine:FireServer(part) end)
			end
			pcall(function()
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
			end)
		end

		local function hardUngrab(part)
			-- Priority: grabbed part + HRP first (instant, no yields)
			instantClaim(part)
			instantClaim(hrp)
			for _, n in ipairs({"Torso", "UpperTorso", "LowerTorso", "Head"}) do
				local p = character:FindFirstChild(n)
				if p then instantClaim(p) end
			end
			-- Strip fling forces on HRP
			pcall(function()
				for _, c in ipairs(hrp:GetChildren()) do
					local cn = c.ClassName
					if cn == "BodyVelocity" or cn == "BodyPosition" or cn == "BodyAngularVelocity"
						or cn == "LinearVelocity" or cn == "AlignPosition" or cn == "VectorForce" then
						c:Destroy()
					end
				end
			end)
			local hum = character:FindFirstChildOfClass("Humanoid")
			if hum then
				pcall(function()
					hum.PlatformStand = false
					hum.Sit = false
				end)
			end
		end

		local function isForeign(part)
			if not part then return false end
			local po = part:FindFirstChild("PartOwner")
			if not po then return false end
			local o = po.Value
			return o and o ~= "" and o ~= TP_LP.Name
		end

		local function findForeignGrab()
			if isForeign(hrp) then return hrp end
			-- Only scan BaseParts with PartOwner (faster than full GetDescendants every time when cached)
			for _, child in ipairs(character:GetChildren()) do
				if child:IsA("BasePart") and isForeign(child) then return child end
			end
			for _, d in ipairs(character:GetDescendants()) do
				if d:IsA("StringValue") and d.Name == "PartOwner" then
					local o = d.Value
					if o and o ~= "" and o ~= TP_LP.Name then
						return d.Parent
					end
				end
			end
			return nil
		end

		local function startUngrabSession(grabbedPart)
			if not self.anti_grab then return end
			-- Always update part; if already busy, hardUngrab runs in loop
			self.active_grab_part = grabbedPart or self.active_grab_part
			-- FIRST pulse immediately on THIS thread (no task.spawn delay)
			hardUngrab(self.active_grab_part or hrp)
			if self.busy then return end
			self.busy = true
			task.spawn(function()
				local localChar = TP_LP.Character
				local localRoot = localChar and localChar:FindFirstChild("HumanoidRootPart")
				if localRoot and hrp.Parent then
					local maxDist = AntiGrabManager.default.max_teleport_distance or 30
					if (localRoot.Position - hrp.Position).Magnitude > maxDist then
						pcall(function() localChar:PivotTo(hrp.CFrame + Vector3.new(0, 5, 0)) end)
					end
				end
				-- Spam ungrab every frame while grabbed (no 0.03 wait)
				while self.anti_grab do
					local part = findForeignGrab()
					if not part then break end
					self.active_grab_part = part
					hardUngrab(part)
					TP_RunService.Heartbeat:Wait()
				end
				hardUngrab(hrp)
				self.busy = false
				self.active_grab_part = nil
			end)
		end

		-- Every Heartbeat (no throttle) when enabled
		self.hb_conn = TP_RunService.Heartbeat:Connect(function()
			if not self.anti_grab then return end
			if isForeign(hrp) then
				startUngrabSession(hrp)
				return
			end
			if not self.busy then
				local part = findForeignGrab()
				if part then startUngrabSession(part) end
			end
		end)
		table.insert(self.conns, self.hb_conn)

		-- Instant on PartOwner added / value change
		self.anti_grab_conn = character.DescendantAdded:Connect(function(child)
			if not self.anti_grab then return end
			if not child:IsA("StringValue") or child.Name ~= "PartOwner" then return end
			pcall(function()
				child:GetPropertyChangedSignal("Value"):Connect(function()
					if not self.anti_grab then return end
					local o = child.Value
					if o and o ~= "" and o ~= TP_LP.Name then
						startUngrabSession(child.Parent)
					end
				end)
			end)
			local o = child.Value
			if o and o ~= "" and o ~= TP_LP.Name then
				startUngrabSession(child.Parent)
			end
		end)
		table.insert(self.conns, self.anti_grab_conn)

		for _, d in ipairs(character:GetDescendants()) do
			if d:IsA("StringValue") and d.Name == "PartOwner" then
				pcall(function()
					d:GetPropertyChangedSignal("Value"):Connect(function()
						if not self.anti_grab then return end
						local o = d.Value
						if o and o ~= "" and o ~= TP_LP.Name then
							startUngrabSession(d.Parent)
						end
					end)
				end)
				local o = d.Value
				if o and o ~= "" and o ~= TP_LP.Name then
					startUngrabSession(d.Parent)
				end
			end
		end
	end

	function AntiGrabManager:OnDied(character)
		local humanoid = character and character:WaitForChild("Humanoid", 5)
		if not humanoid then return end
		self.died_conn = humanoid.Died:Once(function()
			if self.anti_grab_conn then pcall(function() self.anti_grab_conn:Disconnect() end) self.anti_grab_conn = nil end
		end)
		table.insert(self.conns, self.died_conn)
	end

	function AntiGrabManager:SetUp(character)
		if not character then return end
		self:OnDied(character)
		self:AntiGrabPlayer(character)
	end

	function AntiGrabManager:UnHookPlayer()
		if self.conns then
			for _, conn in ipairs(self.conns) do
				if conn then pcall(function() conn:Disconnect() end) end
			end
		end
		self.conns = {}
		self.anti_grab = false
		if self.anti_grab_conn then pcall(function() self.anti_grab_conn:Disconnect() end) self.anti_grab_conn = nil end
		if self.hb_conn then pcall(function() self.hb_conn:Disconnect() end) self.hb_conn = nil end
		if self.po_hook then pcall(function() self.po_hook:Disconnect() end) self.po_hook = nil end
		if self.reset_conn then pcall(function() self.reset_conn:Disconnect() end) self.reset_conn = nil end
		if self.root_conn then pcall(function() self.root_conn:Disconnect() end) self.root_conn = nil end
		if self.player_left then pcall(function() self.player_left:Disconnect() end) self.player_left = nil end
		if self.player then AntiGrabManager.active_managers[self.player] = nil end
		self.player = nil
	end

	function AntiGrabManager:HookPlayer()
		local targetPlayer = self.player
		if not targetPlayer then return end
		if not targetPlayer.Character then pcall(function() targetPlayer.CharacterAdded:Wait() end) end
		if targetPlayer.Character then self:SetUp(targetPlayer.Character) end
		self.root_conn = targetPlayer.CharacterAdded:Connect(function(newCharacter)
			self:SetUp(newCharacter)
		end)
		table.insert(self.conns, self.root_conn)
		self.player_left = TP_Players.PlayerRemoving:Connect(function(leavingPlayer)
			if leavingPlayer == targetPlayer then self:UnHookPlayer() end
		end)
		table.insert(self.conns, self.player_left)
	end

	function AntiGrabManager.new(targetPlayer)
		if not targetPlayer then return nil end
		if AntiGrabManager.active_managers[targetPlayer] then
			return AntiGrabManager.active_managers[targetPlayer]
		end
		local self = setmetatable({
			anti_grab = AntiGrabManager.default.anti_grab,
			player = targetPlayer,
			conns = {},
		}, AntiGrabManager)
		AntiGrabManager.active_managers[targetPlayer] = self
		self:HookPlayer()
		return self
	end

	-- ========== Anti-Kick multi-target (up to 6) ==========
	local antiKickTasks = {} -- [Player] = true while running
	local antiKickRunning = false

	local function clearAntiKick3PToys()
		local MenuToys = TP_RS:FindFirstChild("MenuToys")
		local destroyrem = MenuToys and MenuToys:FindFirstChild("DestroyToy")
		local inv = workspace:FindFirstChild(TP_LP.Name .. "SpawnedInToys")
		if inv and destroyrem then
			for _, v in pairs(inv:GetChildren()) do
				if v.Name == "AntiKick3P" then
					pcall(function() destroyrem:FireServer(v) end)
				end
			end
		end
	end

	local function stopAntiKickFor(targetPlayer)
		if targetPlayer then
			antiKickTasks[targetPlayer] = nil
		end
	end

	local function stopAllAntiKick()
		for plr in pairs(antiKickTasks) do
			antiKickTasks[plr] = nil
		end
		antiKickRunning = false
		task.spawn(clearAntiKick3PToys)
	end

	local function startAntiKickFor(targetPlayer)
		if not targetPlayer or antiKickTasks[targetPlayer] then return end
		antiKickTasks[targetPlayer] = true
		antiKickRunning = true

		task.spawn(function()
			local setOwner = TP_RS:FindFirstChild("GrabEvents") and TP_RS.GrabEvents:FindFirstChild("SetNetworkOwner")
			local stickyEvent = TP_RS:FindFirstChild("PlayerEvents") and TP_RS.PlayerEvents:FindFirstChild("StickyPartEvent")
			local spawnRemote = TP_RS:FindFirstChild("MenuToys") and TP_RS.MenuToys:FindFirstChild("SpawnToyRemoteFunction")
			local canSpawn = TP_LP:FindFirstChild("CanSpawnToy")
			local destroyrem = TP_RS:FindFirstChild("MenuToys") and TP_RS.MenuToys:FindFirstChild("DestroyToy")
			if not setOwner or not stickyEvent or not spawnRemote then
				antiKickTasks[targetPlayer] = nil
				return
			end

			local function getTargetHRP()
				local c = targetPlayer.Character
				if c and c:FindFirstChild("HumanoidRootPart") then
					return c.HumanoidRootPart, c
				end
				return nil, nil
			end

			local function StickKunai(kunai, targetChar)
				if not kunai or not kunai:FindFirstChild("StickyPart") then return end
				local currentHRP = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
				if not currentHRP then return end
				if kunai:FindFirstChild("SoundPart") then
					pcall(function() setOwner:FireServer(kunai.SoundPart, kunai.SoundPart.CFrame) end)
				end
				local firePart = currentHRP:FindFirstChild("FirePlayerPart")
				if not firePart then
					pcall(function() firePart = currentHRP:WaitForChild("FirePlayerPart", 3) end)
				end
				if firePart then
					pcall(function()
						stickyEvent:FireServer(
							kunai.StickyPart,
							firePart,
							CFrame.new(0.0490287527, -0.5, 0, 0, -0.00739139877, -0.999561906, 0.998452604, -0.0478846952, -0.0282763243, 0.0476547107, -0.99882561, 0.00739139877)
						)
					end)
				end
				pcall(function() kunai.Name = "AntiKick3P" end)
			end

			while antiKickTasks[targetPlayer] do
				if not targetPlayer.Parent then break end
				local hrp, tChar = getTargetHRP()
				if not hrp then
					task.wait(0.3)
					continue
				end
				-- find existing kunai stuck near them or spawn
				local inv = workspace:FindFirstChild(TP_LP.Name .. "SpawnedInToys")
				local kunai = nil
				if inv then
					for _, v in pairs(inv:GetChildren()) do
						if v.Name == "AntiKick3P" or v.Name == "NinjaShuriken" then
							kunai = v
							break
						end
					end
				end
				if not kunai then
					if canSpawn and canSpawn.Value then
						pcall(function()
							spawnRemote:InvokeServer("NinjaShuriken", hrp.CFrame * CFrame.new(0, 2, 0), Vector3.zero)
						end)
						task.wait(0.4)
						inv = workspace:FindFirstChild(TP_LP.Name .. "SpawnedInToys")
						if inv then
							for _, v in pairs(inv:GetChildren()) do
								if v.Name == "NinjaShuriken" or v.Name == "AntiKick3P" then
									kunai = v
									break
								end
							end
						end
					end
				end
				if kunai and tChar then
					StickKunai(kunai, tChar)
				end
				task.wait(0.5)
			end
			antiKickTasks[targetPlayer] = nil
		end)
	end

	-- Compat aliases used by older code
	local function stopAntiKickShuriken()
		stopAllAntiKick()
	end
	local function startAntiKickShuriken(targetPlayer)
		startAntiKickFor(targetPlayer)
	end
	local antiKickOn = false -- updated by toggles

	-- ========== Protect list: up to 6 players ==========
	local MAX_PROTECT = 6
	local protectSlots = {} -- { "User1", "User2", ... }
	local g0 = (getgenv and getgenv()) or _G
	g0.FluxyProtectSlots = g0.FluxyProtectSlots or {}
	if type(g0.FluxyProtectSlots) == "table" then
		for _, n in ipairs(g0.FluxyProtectSlots) do
			if type(n) == "string" and #protectSlots < MAX_PROTECT then
				table.insert(protectSlots, n)
			end
		end
	end

	local function saveSlots()
		g0.FluxyProtectSlots = { table.unpack(protectSlots) }
	end

	local function listProtectedPlayers()
		local out = {}
		for _, name in ipairs(protectSlots) do
			local p = TP_Players:FindFirstChild(name)
			if p then table.insert(out, p) end
		end
		return out
	end

	local function addProtectName(name)
		if not name or name == "" or name == "None" then return false, "invalid" end
		for _, n in ipairs(protectSlots) do
			if n == name then return true, "exists" end
		end
		if #protectSlots >= MAX_PROTECT then return false, "full" end
		table.insert(protectSlots, name)
		saveSlots()
		return true, "added"
	end

	local function removeProtectName(name)
		for i, n in ipairs(protectSlots) do
			if n == name then
				table.remove(protectSlots, i)
				saveSlots()
				local plr = TP_Players:FindFirstChild(name)
				if plr then
					stopAntiKickFor(plr)
					local mgr = AntiGrabManager.active_managers[plr]
					if mgr then pcall(function() mgr:UnHookPlayer() end) end
					if g0.FluxyAntiLagNames then g0.FluxyAntiLagNames[name] = nil end
				end
				return true
			end
		end
		return false
	end

	local function hookAllProtected()
		for _, plr in ipairs(listProtectedPlayers()) do
			local mgr = AntiGrabManager.new(plr)
			if mgr then
				mgr.anti_grab = AntiGrabManager.default.anti_grab
			end
		end
	end

	local function syncAntiLagNames()
		g0.FluxyAntiLagNames = g0.FluxyAntiLagNames or {}
		-- clear then re-add from slots when anti-lag mode on
		for k in pairs(g0.FluxyAntiLagNames) do
			g0.FluxyAntiLagNames[k] = nil
		end
		for _, name in ipairs(protectSlots) do
			g0.FluxyAntiLagNames[name] = true
		end
	end

	local ThirdGroup = Tabs.ThirdParty:CreateBlock({Name = "Protect 1-6", Side = "Left"})
	local ThirdProt = Tabs.ThirdParty:CreateBlock({Name = "Protections", Side = "Right"})

	local selectedPlayerName = "None"
	local function getPlayerList()
		local list = { "None" }
		for _, pl in ipairs(TP_Players:GetPlayers()) do
			if pl ~= TP_LP then
				table.insert(list, pl.DisplayName .. " (@" .. pl.Name .. ")")
			end
		end
		return list
	end

	local ThirdPlayerDropdown = ThirdGroup:CreateDropdown({
		Name = "Select Player",
		Items = getPlayerList(),
		Default = "None",
		Searchable = true,
		Callback = function(Option)
			if type(Option) == "table" then Option = Option[1] end
			selectedPlayerName = Option
			if g0.FluxyRememberPlayer then g0.FluxyRememberPlayer("ThirdParty", selectedPlayerName) end
		end
	})

	local _thirdListKey = nil
	local function refreshThirdPlayerDropdown()
		local newList = getPlayerList()
		local key = table.concat(newList, "\0")
		if key == _thirdListKey then return end
		_thirdListKey = key
		if not ThirdPlayerDropdown then return end
		pcall(function()
			if ThirdPlayerDropdown.SetOptions then
				ThirdPlayerDropdown:SetOptions(newList)
			end
		end)
		pcall(function()
			if ThirdPlayerDropdown.Refresh then
				ThirdPlayerDropdown:Refresh(newList, true)
			end
		end)
		pcall(function()
			if ThirdPlayerDropdown.Set then
				local keep = selectedPlayerName
				if keep and keep ~= "None" then
					for _, entry in ipairs(newList) do
						if tostring(entry) == tostring(keep) or tostring(entry):find(tostring(keep), 1, true) then
							ThirdPlayerDropdown:Set(entry)
							return
						end
					end
				end
			end
		end)
	end
	TP_Players.PlayerAdded:Connect(function(plr)
		task.defer(refreshThirdPlayerDropdown)
		task.delay(0.5, refreshThirdPlayerDropdown)
		task.delay(1.5, refreshThirdPlayerDropdown)
		pcall(function()
			plr:GetPropertyChangedSignal("DisplayName"):Connect(function()
				_thirdListKey = nil
				refreshThirdPlayerDropdown()
			end)
		end)
	end)
	TP_Players.PlayerRemoving:Connect(function()
		_thirdListKey = nil
		task.defer(refreshThirdPlayerDropdown)
		task.delay(0.3, refreshThirdPlayerDropdown)
	end)
	task.spawn(function()
		while task.wait(1.5) do
			_thirdListKey = nil
			refreshThirdPlayerDropdown()
		end
	end)
	task.defer(function()
		task.wait(1)
		_thirdListKey = nil
		refreshThirdPlayerDropdown()
	end)

	ThirdGroup:CreateButton({
		Name = "Add to Protect (max 6)",
		Callback = function()
			local user = nil
			if type(selectedPlayerName) == "string" then
				user = selectedPlayerName:match("%(@%s*(.-)%)") or selectedPlayerName:match("@(%S+)")
				if not user or user == selectedPlayerName then
					local p = TP_Players:FindFirstChild(selectedPlayerName)
					user = p and p.Name or selectedPlayerName
				end
			end
			if not user or user == "None" then
				warn("[Fluxy] Pick a player first")
				return
			end
			local ok, why = addProtectName(user)
			if not ok and why == "full" then
				warn("[Fluxy] Max 6 protected players")
				return
			end
			local plr = TP_Players:FindFirstChild(user)
			if plr then
				AntiGrabManager.new(plr)
				if AntiGrabManager.default.anti_grab then
					local mgr = AntiGrabManager.active_managers[plr]
					if mgr then mgr.anti_grab = true end
				end
				if antiKickOn then startAntiKickFor(plr) end
				if g0.FluxyAntiLagActive then
					g0.FluxyAntiLagNames = g0.FluxyAntiLagNames or {}
					g0.FluxyAntiLagNames[user] = true
				end
			end
			print("[Fluxy] Protected (" .. #protectSlots .. "/6):", table.concat(protectSlots, ", "))
		end
	})

	ThirdGroup:CreateButton({
		Name = "Remove Selected",
		Callback = function()
			local user = type(selectedPlayerName) == "string"
				and (selectedPlayerName:match("%(@%s*(.-)%)") or selectedPlayerName:match("@(%S+)") or selectedPlayerName)
			if user and user ~= "None" then
				removeProtectName(user)
				print("[Fluxy] Removed", user, "— now", #protectSlots .. "/6")
			end
		end
	})

	ThirdGroup:CreateButton({
		Name = "Clear All (0/6)",
		Callback = function()
			for _, name in ipairs({ table.unpack(protectSlots) }) do
				removeProtectName(name)
			end
			stopAllAntiKick()
			for _, manager in pairs(AntiGrabManager.active_managers) do
				pcall(function() manager:UnHookPlayer() end)
			end
			protectSlots = {}
			saveSlots()
			print("[Fluxy] Protect list cleared")
		end
	})

	ThirdGroup:CreateButton({
		Name = "Show List",
		Callback = function()
			print("[Fluxy] Protect list (" .. #protectSlots .. "/6):", #protectSlots > 0 and table.concat(protectSlots, ", ") or "(empty)")
		end
	})

	ThirdProt:CreateToggle({
		Name = "Anti Grab (all 1-6)",
		Default = false,
		Callback = function(Value)
			AntiGrabManager.default.anti_grab = Value and true or false
			hookAllProtected()
			for _, plr in ipairs(listProtectedPlayers()) do
				local mgr = AntiGrabManager.active_managers[plr] or AntiGrabManager.new(plr)
				if mgr then mgr.anti_grab = Value and true or false end
			end
		end
	})

	ThirdProt:CreateToggle({
		Name = "Anti Kick (all 1-6)",
		Default = false,
		Callback = function(Value)
			antiKickOn = Value and true or false
			if Value then
				for _, plr in ipairs(listProtectedPlayers()) do
					startAntiKickFor(plr)
				end
			else
				stopAllAntiKick()
			end
		end
	})

	ThirdProt:CreateToggle({
		Name = "Anti Lag (all 1-6)",
		Default = false,
		Callback = function(Value)
			g0.FluxyAntiLagActive = Value and true or false
			syncAntiLagNames()
			if Value and #protectSlots == 0 then
				warn("[Fluxy] Add 1-6 players first")
			end
		end
	})

	ThirdProt:CreateSlider({
		Name = "TP Only If Farther Than",
		Default = 30,
		Min = 10,
		Max = 100,
		Callback = function(v)
			AntiGrabManager.default.max_teleport_distance = tonumber(v) or 30
		end
	})

	ThirdProt:CreateButton({
		Name = "Unhook All",
		Callback = function()
			stopAllAntiKick()
			AntiGrabManager.default.anti_grab = false
			g0.FluxyAntiLagActive = false
			for _, manager in pairs(AntiGrabManager.active_managers) do
				pcall(function() manager:UnHookPlayer() end)
			end
			print("[Fluxy] All protections off (list kept)")
		end
	})

end

local antiGrabExplosionConn, antiGrabHeldConn, antiGrabStruggleConn, antiGrabHumConn, antiGrabAnchorConn
local antiGrabRootCF, antiGrabRootPos, antiGrabHardFreeze = nil, nil, false
local function antiGrabUnfreeze(char)
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if hrp then
		hrp.Anchored = false
		if hrp:FindFirstChild("FreezeJoint") then
			hrp.FreezeJoint:Destroy()
		end
	end
	antiGrabHardFreeze = false
	if antiGrabAnchorConn then
		antiGrabAnchorConn:Disconnect()
		antiGrabAnchorConn = nil
	end
end
local function antiGrabFreezeInPlace(char)
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end
	antiGrabRootCF = hrp.CFrame
	antiGrabRootPos = hrp.Position
	antiGrabHardFreeze = true
	if not hrp:FindFirstChild("FreezeJoint") then
		local align = Instance.new("AlignPosition")
		align.Name = "FreezeJoint"
		align.Mode = Enum.PositionAlignmentMode.OneAttachment
		align.MaxForce = 1e6
		align.MaxVelocity = 0
		align.Responsiveness = 200
		local att = Instance.new("Attachment", hrp)
		align.Attachment0 = att
		align.Position = antiGrabRootPos
		align.Parent = hrp
	end
	antiGrabAnchorConn = R.Heartbeat:Connect(function()
		if antiGrabHardFreeze and hrp then
			hrp.AssemblyLinearVelocity = Vector3.zero
			hrp.AssemblyAngularVelocity = Vector3.zero
			hrp.CFrame = antiGrabRootCF
		end
	end)
end
local function antiGrabReconnect()
	local char = Player.Character or Player.CharacterAdded:Wait()
	local hum = char:WaitForChild("Humanoid")
	local hrp = char:WaitForChild("HumanoidRootPart")
	local fp = hrp:FindFirstChild("FirePlayerPart")
	if fp then
		fp:Destroy()
	end
	if antiGrabHumConn then
		antiGrabHumConn:Disconnect()
	end
	antiGrabHumConn = hum.Changed:Connect(function(p)
		if p == "Sit" and hum.Sit then
			if not (hum.SeatPart and tostring(hum.SeatPart.Parent) == "CreatureBlobman") then
				hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
				hum.Sit = false
			end
		end
	end)
end
do
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local ContextActionService = game:GetService("ContextActionService")
    local LocalPlayer = Players.LocalPlayer

    -- Localized state management (replaces getgenv and ACGE)
    local antiGrabActive = false
    local antiGrabConnection = nil
    local spawnTick = nil

    DefenseGroup:CreateToggle({
        Name = "Seatless Anti-Grab",
        Flag = "SeatlessGucciAntiGrab",
        Default = false,
        Callback = function(Value)
            if SetToggleState then SetToggleState("SeatlessGucciAntiGrab", Value) end
            antiGrabActive = Value

            if Value then
                if not antiGrabConnection then
                    antiGrabConnection = RunService.RenderStepped:Connect(function()
                        if not antiGrabActive then return end
                        
                        local char = LocalPlayer.Character
                        if not char then return end

                        local hum = char:FindFirstChild("Humanoid")
                        local root = char:FindFirstChild("HumanoidRootPart")
                        local myToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                        local ocarina = myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")
                        
                        if ocarina then
                            -- Check if we are currently being grabbed
                            for _, prt in ipairs(char:GetChildren()) do
                                local owner = prt:FindFirstChild("PartOwner")
                                if owner and owner.Value ~= "" then
                                    local holdPart = ocarina:FindFirstChild("HoldPart")
                                    local holdFunc = holdPart and holdPart:FindFirstChild("HoldItemRemoteFunction")
                                    
                                    if holdFunc then
                                        task.spawn(function()
                                            pcall(function() holdFunc:InvokeServer(ocarina, char) end)
                                        end)

                                        local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
                                        local destroyToy = menuToys and menuToys:FindFirstChild("DestroyToy")
                                        if destroyToy then
                                            pcall(function() destroyToy:FireServer(ocarina) end)
                                        end
                                        
                                        if hum then
                                            hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                                            hum.AutoRotate = true
                                            if hum.Sit then
                                                hum.Sit = false
                                            end
                                        end

                                        pcall(function()
                                            ContextActionService:UnbindAction("Escape")
                                            ContextActionService:UnbindAction("JumpRemover")
                                        end)
                                        
                                        owner.Value = ""
                                    end
                                end
                            end
                        else
                            -- Spawn logic if Ocarina doesn't exist
                            local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
                            if canSpawn and canSpawn.Value and not spawnTick then
                                spawnTick = tick()
                                task.spawn(function()
                                    local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
                                    local spawnFunc = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
                                    if spawnFunc then
                                        pcall(function()
                                            spawnFunc:InvokeServer(
                                                "InstrumentWoodwindOcarina",
                                                CFrame.new(1e5, 1e5, 1e5),
                                                Vector3.zero
                                            )
                                        end)
                                    end
                                end)
                            elseif spawnTick and tick() - spawnTick > 1 and not (myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")) then
                                spawnTick = nil
                            end

                            -- Grab escape fallback
                            local grabbed = false
                            for _, prt in ipairs(char:GetChildren()) do
                                local owner = prt:FindFirstChild("PartOwner")
                                if owner and owner.Value ~= "" then
                                    grabbed = true
                                    break
                                end
                            end

                            if grabbed then
                                local charEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
                                if charEvents then
                                    local struggle = charEvents:FindFirstChild("Struggle")
                                    local ragdollRemote = charEvents:FindFirstChild("RagdollRemote")
                                    
                                    if struggle then pcall(function() struggle:FireServer(LocalPlayer) end) end
                                    if ragdollRemote and root then pcall(function() ragdollRemote:FireServer(root, 0) end) end
                                end
                                
                                if hum and type(stopOcarinaAnim) == "function" then
                                    pcall(stopOcarinaAnim, hum)
                                end
                            end
                        end

                        if hum and type(stopOcarinaAnim) == "function" then
                            pcall(stopOcarinaAnim, hum)
                        end
                    end)
                end
            else
                if antiGrabConnection then
                    antiGrabConnection:Disconnect()
                    antiGrabConnection = nil
                end
            end
        end
    })
end
local autoStruggleConn = nil
local AntiGrabEnabled = false
local HeldConnection = nil

do
    local RunService = game:GetService("RunService")
    local AntiGrab = false
    local AntiGrabProc = false
    local AGWalk = false
    local Cons = {}
    
    local function DiscAll()
        for k, v in pairs(Cons) do
            if v then v:Disconnect() end
        end
        table.clear(Cons)
    end

    local function ApplyAntiGrab(char)
        if not char or not AntiGrab then return end
        
        local hrp = char:WaitForChild("HumanoidRootPart", 5)
        local hum = char:WaitForChild("Humanoid", 5)
        local head = char:WaitForChild("Head", 5)
        local torso = char:WaitForChild("Torso", 5) or char:WaitForChild("UpperTorso", 5)
        if not (hrp and hum and head and torso) then return end

        local beingHeld = char:FindFirstChild("BeingHeld")
        local wasRagdolled = false

        Cons["AGCFrameLimbing"] = RunService.Heartbeat:Connect(function()
            local ragdolled = hum:FindFirstChild("Ragdolled")
            
            if ragdolled and ragdolled.Value then
                wasRagdolled = true
                local leftArm = char:FindFirstChild("Left Arm")
                local rightArm = char:FindFirstChild("Right Arm")
                local leftLeg = char:FindFirstChild("Left Leg")
                local rightLeg = char:FindFirstChild("Right Leg")

                if leftArm then leftArm.CFrame = torso.CFrame * CFrame.new(-1.5, 0, 0); leftArm.CanCollide = false end
                if rightArm then rightArm.CFrame = torso.CFrame * CFrame.new(1.5, 0, 0); rightArm.CanCollide = false end
                if leftLeg then leftLeg.CFrame = torso.CFrame * CFrame.new(-0.5, -2, 0); leftLeg.CanCollide = false end
                if rightLeg then rightLeg.CFrame = torso.CFrame * CFrame.new(0.5, -2, 0); rightLeg.CanCollide = false end
            elseif wasRagdolled then
                wasRagdolled = false
                local limbs = {"Left Arm", "Right Arm", "Left Leg", "Right Leg"}
                for _, limbName in ipairs(limbs) do
                    local limb = char:FindFirstChild(limbName)
                    if limb then limb.CanCollide = true end
                end
            end
        end)

        Cons["AGHead"] = head.ChildAdded:Connect(function(PartOwner)
            if PartOwner.Name == "PartOwner" then
                if not AntiGrabProc then
                    AntiGrabProc = true
                    hum.Sit = false
                    
                    pcall(function() StruggleEvent:FireServer(Player) end)
                    
                    task.spawn(function() 
                        while (head and head:FindFirstChild("PartOwner")) or (beingHeld and beingHeld.Value) do
                            pcall(function() StruggleEvent:FireServer(Player) end)
                            pcall(function() ReplicatedStorage.CharacterEvents.RagdollRemote:FireServer(hrp, 0) end)
                            task.wait()
                        end
                    end)
                    
                    task.spawn(function()
                        hrp.Anchored = true
                        if not AGWalk then
                            AGWalk = true
                            pcall(function()
                                while (head and head:FindFirstChild("PartOwner")) or (beingHeld and beingHeld.Value) do
                                    hrp.CFrame = hrp.CFrame + hum.MoveDirection * 0.43
                                    task.wait()
                                end
                            end)
                        end
                        hrp.Anchored = false
                        AntiGrabProc = false
                        AGWalk = false
                    end)
                end
            end
        end)
        
        local weldHRP = hrp:WaitForChild("WeldHRP", 5)
        if weldHRP then
            Cons["AGWeld"] = weldHRP.Changed:Connect(function()
                if hrp.WeldHRP.Enabled then
                    task.spawn(function()
                        while hrp.WeldHRP.Enabled and task.wait() do
                            hum.Sit = false
                            hum.AutoRotate = true
                            hum.HipHeight = 0
                            pcall(function() head.CFrame = hrp.CFrame + Vector3.new(0, 1.35, 0) end)
                        end
                        hum.HipHeight = 0
                    end)
                end
            end)
        end
    end

    DefenseGroup:CreateToggle({
        Name = "Anti-Grab (Best)",
        Flag = "AntiGrab",
        Default = false,
        Callback = function(Value)
            AntiGrab = Value
            DiscAll()
            
            if AntiGrab then
                ApplyAntiGrab(Player.Character)
                Cons["AGChar"] = Player.CharacterAdded:Connect(ApplyAntiGrab)
            else
                local char = Player.Character
                if char then
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if hrp then hrp.Anchored = false end
                    
                    local limbs = {"Left Arm", "Right Arm", "Left Leg", "Right Leg"}
                    for _, limbName in ipairs(limbs) do
                        local limb = char:FindFirstChild(limbName)
                        if limb then limb.CanCollide = true end
                    end
                end
            end
        end
    })
end

RunService = game:GetService('RunService')
Players = game:GetService('Players')
ReplicatedStorage = game:GetService('ReplicatedStorage')
DestroyToy = ReplicatedStorage.MenuToys.DestroyToy
SpawnToyRemoteFunction = ReplicatedStorage.MenuToys.SpawnToyRemoteFunction
GrabEvents = ReplicatedStorage.GrabEvents
SetNetworkOwner = GrabEvents.SetNetworkOwner
CharacterEvents = ReplicatedStorage.CharacterEvents
RagdollRemote = CharacterEvents.RagdollRemote
GUE = false
GUTYPE = 'CreatureBlobman'
inexistance = {}

local itm
local sp
local sv
local humconnection
local LocalPlayer = game.Players.LocalPlayer

local gucciTypes = {
    ['Blobman'] = 'CreatureBlobman',
    ['Tractor'] = 'TractorGreen',
    ['Santa Sleigh'] = 'SantaSleigh'
}

local selectedGucciType = 'CreatureBlobman'

function getCharParts()
    local char = LocalPlayer.Character
    if not char then
        return nil, nil
    end
    return char:FindFirstChild('Humanoid'), char:FindFirstChild('HumanoidRootPart')
end

hum, hrp = getCharParts()

local characterAddedConnection
gucciRunning = false

function diddle()
    if itm then
        for _, prt in pairs(itm:GetChildren())do
            if prt:IsA('BasePart') then
                prt.CanCollide = false
            end
        end
    end
    hrp.CFrame = sp
    hrp.AssemblyLinearVelocity = sv
    hum:GetPropertyChangedSignal('SeatPart'):Once(diddle)
end

function checkgrab(part)
    pcall(function()
        SetNetworkOwner:FireServer(part, part.CFrame)
    end)
end

function gucciblob()
    if gucciRunning then
        return
    end
    gucciRunning = true

    local guccion = false
    local tickyticky = tick()

    while GUE do
        hum, hrp = getCharParts()

        if hum and hrp then
            local dt = tick() - tickyticky
            tickyticky = tick()

            if itm and itm:FindFirstChild('VehicleSeat') then
                local occupant = itm.VehicleSeat.Occupant
                if occupant and occupant ~= hum then
                    task.spawn(function()
                        DestroyToy:FireServer(itm)
                    end)
                    itm = nil
                    guccion = false
                    inexistance = {}
                    task.wait(0.1)
                    if LocalPlayer.CanSpawnToy.Value then
                        task.spawn(function()
                            SpawnToyRemoteFunction:InvokeServer(selectedGucciType, hrp.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0))
                        end)
                    end
                    task.wait()
                    continue
                end
            end

            if itm and itm.Parent and not ((itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')) and itm:FindFirstChild('VehicleSeat') and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant ~= hum) or inexistance[itm] < 1) then
                task.spawn(function()
                    DestroyToy:FireServer(itm)
                end)
            else
                local toyFolder = workspace:FindFirstChild(LocalPlayer.Name .. 'SpawnedInToys')
                itm = toyFolder and toyFolder:FindFirstChild(selectedGucciType)
            end

            if not sp or not hum.SeatPart then
                sp = hrp.CFrame
                sv = hrp.AssemblyLinearVelocity
            end

            if humconnection ~= hum then
                humconnection = hum
                hum:GetPropertyChangedSignal('SeatPart'):Once(diddle)
            end

            local wait = true

            if itm then
                inexistance[itm] = (inexistance[itm] or 0) + dt

                if (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')) and itm:FindFirstChild('VehicleSeat') and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == hum) then
                    if not guccion then
                        (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')).AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    end

                    local diddy = itm.VehicleSeat
                    diddy.Parent = nil
                    diddy.Parent = itm

                    if not checkgrab(itm) and (hrp.CFrame.Position - (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')).CFrame.Position).Magnitude < 28 then
                        for _, prt in pairs(itm:GetChildren())do
                            if prt:IsA('BasePart') and prt.CanQuery then
                                SetNetworkOwner:FireServer(prt, CFrame.lookAt(hrp.CFrame.Position, prt.CFrame.Position))
                            end
                        end
                    end

                    if not hum.SeatPart then
                        hum.Sit = false
                    else
                        wait = false
                        task.wait()
                    end

                    if hrp and hum and (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')) and itm:FindFirstChild('VehicleSeat') and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == hum) then
                        local ragdolled = hum:FindFirstChild('Ragdolled')
                        if ragdolled and ragdolled.Value then
                            guccion = false
                        end

                        if itm.VehicleSeat.Occupant == hum then
                            guccion = true
                        elseif not guccion then
                            task.wait()
                            wait = false
                            if (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')) and itm:FindFirstChild('VehicleSeat') and (not itm.VehicleSeat.Occupant or itm.VehicleSeat.Occupant == hum) then
                                local ragdolled2 = hum:FindFirstChild('Ragdolled')
                                if not ragdolled2 or not ragdolled2.Value then
                                    itm.VehicleSeat:Sit(hum)
                                    RagdollRemote:FireServer(hrp, 0.016)
                                end
                            end
                        end

                        if guccion then
                            (itm:FindFirstChild('HumanoidRootPart') or itm:FindFirstChild('SoundPart')).AssemblyLinearVelocity = Vector3.new(0, 1e15, 0)
                        else
                            if inexistance[itm] >= game.Stats.Network.ServerStatsItem['Data Ping']:GetValue() / 250 then
                                task.spawn(function()
                                    DestroyToy:FireServer(itm)
                                end)
                                hum.Sit = true
                            end
                        end
                    end
                else
                    if guccion then
                        hum.Sit = true
                    end
                    guccion = false
                    if inexistance[itm] >= 1 then
                        task.spawn(function()
                            DestroyToy:FireServer(itm)
                        end)
                        if LocalPlayer.CanSpawnToy.Value then
                            task.spawn(function()
                                SpawnToyRemoteFunction:InvokeServer(selectedGucciType, hrp.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0))
                            end)
                        end
                    end
                end
            else
                if guccion then
                    guccion = false
                    hum.Sit = true
                end
                if LocalPlayer.CanSpawnToy.Value then
                    task.spawn(function()
                        SpawnToyRemoteFunction:InvokeServer(selectedGucciType, hrp.CFrame * CFrame.new(0, 100000000, 10), Vector3.new(0, 0, 0))
                    end)
                end
            end

            if wait then
                task.wait()
                hum.Sit = false
            end
        else
            task.wait()
        end
    end
    gucciRunning = false
end

function onCharacterAdded(char)
    if not GUE then
        return
    end
    if itm and itm.Parent then
        task.spawn(function()
            DestroyToy:FireServer(itm)
        end)
    end
    itm = nil
    inexistance = {}
    humconnection = nil
    sp = nil
    sv = nil
    gucciRunning = false

    char:WaitForChild('Humanoid', 10)
    char:WaitForChild('HumanoidRootPart', 10)

    hum, hrp = getCharParts()
    task.wait(0.5)
    task.spawn(gucciblob)
end

if characterAddedConnection then
    characterAddedConnection:Disconnect()
end

characterAddedConnection = LocalPlayer.CharacterAdded:Connect(onCharacterAdded)

DefenseGroup:CreateDropdown({
    Name = "Anti-Grab Type",
    Items = {"Blobman", "Tractor", "Santa Sleigh"},
    Default = "Blobman",
    Callback = function(Value)
        selectedGucciType = gucciTypes[Value] or 'CreatureBlobman'
    end
})

DefenseGroup:CreateToggle({
    Name = "Gucci Anti-Grab",
    Tooltip = 'Makes you unable to be touched by anyone or anything.',
    Default = false,
    Callback = function(Value)
        GUE = Value
        if Value then
            task.spawn(gucciblob)
        else
            if itm and itm.Parent then
                task.spawn(function()
                    DestroyToy:FireServer(itm)
                end)
            end
            itm = nil
        end
    end
})

local autoGucciActiveTrain =  false
DefenseGroup:CreateToggle({
	Name = "Anti Gucci Train",
        Flag = "Anti Gucci (Train)",
	Default = false,
	Callback = function(Value)
        SetToggleState("Anti Gucci (Train)", Value)
		autoGucciActiveTrain = Value
		if Value then
			startAntiGucciTrain()
			notify("system", "Gucci active (monitoring)", 3)
			task.spawn(function()
				while autoGucciActiveTrain do
					local trainFolder = workspace.Map.AlwaysHereTweenedObjects
					local trainExists = trainFolder and trainFolder:FindFirstChild("Train")
					if not trainExists then
						stopAntiGucciTrain()
						notify("System", "Train lost", 3)
						local retries = 0
						repeat
							task.wait(0.2)
							retries = retries + 1
							trainFolder = workspace.Map.AlwaysHereTweenedObjects
						until (trainFolder and trainFolder:FindFirstChild("Train")) or retries > 25 or not autoGucciActiveTrain
						if autoGucciActiveTrain and trainFolder and trainFolder:FindFirstChild("Train") then
							startAntiGucciTrain()
							notify("System", "Train restored.", 3)
						end
					end
					task.wait(0.5)
				end
			end)
		else
			autoGucciActiveTrain = false
			stopAntiGucciTrain()
			notify("System", "Gucci disabled.", 3)
		end
	end
})

-- Anti Ragdoll (On Blob)
do
    local AntiRagBlob = false
    local RagdolledSit = false
    local Cons = {}

    local function ApplyAntiRagdoll(char)
        if not char or not AntiRagBlob then return end
        
        local hum = char:WaitForChild("Humanoid", 5)
        local HRP = char:WaitForChild("HumanoidRootPart", 5)
        if not (hum and HRP) then return end
        
        if Cons["ARSeat"] then Cons["ARSeat"]:Disconnect() end
        Cons["ARSeat"] = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
            if hum.SeatPart and hum.SeatPart.Parent and hum.SeatPart.Parent.Name == "CreatureBlobman" and not RagdolledSit then
                RagdolledSit = true
                local Seat = hum.SeatPart
                while not hum.Sit do task.wait() end
                
                ReplicatedStorage.CharacterEvents.RagdollRemote:FireServer(HRP, 3)
                
                local ragdolledVal = hum:FindFirstChild("Ragdolled")
                while ragdolledVal and not ragdolledVal.Value and not hum.Sit do task.wait() end
                
                task.wait(0.4)
                hum.Sit = false
                Seat:Sit(hum)
                
                task.delay(0.25, function()
                    while hum and hum.SeatPart do
                        ReplicatedStorage.CharacterEvents.RagdollRemote:FireServer(HRP, 1)
                        task.wait(0.05)
                    end
                    RagdolledSit = false
                end)
            end
        end)
    end

    DefenseGroup:CreateToggle({
        Name = "Anti Ragdoll",
        Flag = "AntiRagdoll",
        Default = false,
        Callback = function(Value)
            AntiRagBlob = Value
            RagdolledSit = false
            
            if Cons["ARChar"] then Cons["ARChar"]:Disconnect() end
            if Cons["ARSeat"] then Cons["ARSeat"]:Disconnect() end
            
            if AntiRagBlob then
                ApplyAntiRagdoll(Player.Character)
                Cons["ARChar"] = Player.CharacterAdded:Connect(ApplyAntiRagdoll)
            end
        end
    })
end


