	Name = "Anti Burn",
        Flag = "Anti Burn",
	Default = false,
	Callback = function(on)
        SetToggleState("Anti Burn", on)
		if on then
			hookBurn(Player.Character)
		elseif hookBurnConn then
			hookBurnConn:Disconnect()
		end
	end
})

