local currentKickTargetChar = nil

-- // Helper Functions \\ --

-- Formats the list as "Display Name (@Username)"
local function getPlayerList()
    local list = {}
    for _, plr in ipairs(PS:GetPlayers()) do
        if plr ~= Player then
            table.insert(list, plr.DisplayName .. " (@" .. plr.Name .. ")")
        end
    end
    return list
end

-- Extracts the username from the "Display Name (@Username)" string
local function getPlayerFromSelection(selection)
    if not selection or selection == "" then return nil end
    local g = (getgenv and getgenv()) or _G
    if g.FluxyResolvePlayer then
        local p = g.FluxyResolvePlayer(selection)
        if p then return p end
    end
    local username = selection:match("@%s*(.-)%)") or selection:match("@(.-)%)")
    if username then
        username = username:gsub("^%s+", ""):gsub("%s+$", "")
        return PS:FindFirstChild(username)
    end
    return PS:FindFirstChild(tostring(selection))
end

