GrabGroup:CreateToggle({
	Name = "Grab Kick",
	Default = false,
	Callback = function(state)
		-- Real kick (not float): own them, break grab line, yeet horizontally / void
		if not state then
			getgenv().KickGrabActive = false
			if getgenv().FKeyInputConnection then
				pcall(function() getgenv().FKeyInputConnection:Disconnect() end)
				getgenv().FKeyInputConnection = nil
			end
			if getgenv().KickGrabConn then
				pcall(function() getgenv().KickGrabConn:Disconnect() end)
				getgenv().KickGrabConn = nil
			end
			getgenv()._KickGrabLastTarget = nil
			return
		end
		if getgenv().KickGrabActive then return end
		getgenv().KickGrabActive = true
		getgenv()._KickGrabLastTarget = nil
		getgenv()._KickGrabLastTime = 0

		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local UserInputService = game:GetService("UserInputService")
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local Debris = game:GetService("Debris")
		local LocalPlayer = Players.LocalPlayer

		local GrabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
		local SetNetworkOwner = GrabEvents and GrabEvents:FindFirstChild("SetNetworkOwner")
		local DestroyGrabLine = GrabEvents and GrabEvents:FindFirstChild("DestroyGrabLine")
		local CreateGrabLine = GrabEvents and GrabEvents:FindFirstChild("CreateGrabLine")

		local function getGrabbedPlayer()
			local grabParts = workspace:FindFirstChild("GrabParts")
			if not grabParts then return nil end
			local gp = grabParts:FindFirstChild("GrabPart")
			local weld = gp and gp:FindFirstChildOfClass("WeldConstraint")
			local part1 = weld and weld.Part1
			if not part1 then return nil end
			for _, pl in ipairs(Players:GetPlayers()) do
				if pl ~= LocalPlayer and pl.Character and part1:IsDescendantOf(pl.Character) then
					return pl
				end
			end
			return nil
		end

		local function doKick(plr)
			if not plr or not plr.Character then return end
			local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
			local head = plr.Character:FindFirstChild("Head")
			local myChar = LocalPlayer.Character
			local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if not hrp or not myHrp then return end

			local cam = workspace.CurrentCamera
			-- horizontal kick direction (camera look, flatten Y)
			local look = cam and cam.CFrame.LookVector or myHrp.CFrame.LookVector
			local dir = Vector3.new(look.X, 0, look.Z)
			if dir.Magnitude < 0.05 then
				dir = Vector3.new(myHrp.CFrame.LookVector.X, 0, myHrp.CFrame.LookVector.Z)
			end
			if dir.Magnitude < 0.05 then
				dir = Vector3.new(1, 0, 0)
			else
				dir = dir.Unit
			end

			-- 1) Take ownership of whole character roots
			for _, name in ipairs({"HumanoidRootPart", "Torso", "Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
				local part = plr.Character:FindFirstChild(name)
				if part and SetNetworkOwner then
					pcall(function()
						SetNetworkOwner:FireServer(part, part.CFrame)
					end)
				end
			end

			-- 2) Break grab lines so they aren't stuck to you
			if DestroyGrabLine then
				pcall(function() DestroyGrabLine:FireServer(hrp) end)
				if head then pcall(function() DestroyGrabLine:FireServer(head) end) end
			end

			-- 3) Hard horizontal yeet (almost no upward — stops "just floats")
			local speed = 320
			local vel = dir * speed + Vector3.new(0, 40, 0)

			pcall(function()
				-- clear old kick movers
				for _, c in ipairs(hrp:GetChildren()) do
					if c.Name == "FluxyGrabKick" or c.Name == "FluxyGrabKickBP" then
						c:Destroy()
					end
				end
				hrp.AssemblyLinearVelocity = vel
				hrp.AssemblyAngularVelocity = Vector3.new(20, 40, 10)

				local bv = Instance.new("BodyVelocity")
				bv.Name = "FluxyGrabKick"
				bv.MaxForce = Vector3.new(1e11, 1e11, 1e11)
				bv.Velocity = vel
				bv.P = 20000
				bv.Parent = hrp
				Debris:AddItem(bv, 0.45)

				-- push far away in look direction (actual kick out of range)
				hrp.CFrame = CFrame.new(hrp.Position + dir * 80 + Vector3.new(0, 5, 0))
			end)

			-- 4) Keep ownership a few frames so fling sticks
			task.spawn(function()
				for _ = 1, 8 do
					if not getgenv().KickGrabActive then break end
					if SetNetworkOwner and hrp and hrp.Parent then
						pcall(function()
							SetNetworkOwner:FireServer(hrp, hrp.CFrame)
						end)
					end
					if DestroyGrabLine and hrp and hrp.Parent then
						pcall(function() DestroyGrabLine:FireServer(hrp) end)
					end
					task.wait(0.03)
				end
			end)
		end

		-- When you grab someone, kick once (not every frame = no air hover)
		getgenv().KickGrabConn = RunService.Heartbeat:Connect(function()
			if not getgenv().KickGrabActive then return end
			local plr = getGrabbedPlayer()
			if not plr then
				getgenv()._KickGrabLastTarget = nil
				return
			end
			local now = tick()
			-- New grab target → kick immediately
			if getgenv()._KickGrabLastTarget ~= plr then
				getgenv()._KickGrabLastTarget = plr
				getgenv()._KickGrabLastTime = now
				doKick(plr)
				return
			end
			-- Same target still held → re-kick every 0.6s (not 0.12)
			if now - (getgenv()._KickGrabLastTime or 0) >= 0.6 then
				getgenv()._KickGrabLastTime = now
				doKick(plr)
			end
		end)

		-- F: kick player under crosshair (close range)
		local function tryCrosshairKick()
			local cam = workspace.CurrentCamera
			if not cam then return end
			local mid = cam.ViewportSize / 2
			local ray = cam:ViewportPointToRay(mid.X, mid.Y)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			if LocalPlayer.Character then
				params.FilterDescendantsInstances = { LocalPlayer.Character }
			end
			local hit = workspace:Raycast(ray.Origin, ray.Direction * 80, params)
			if not hit then return end
			for _, pl in ipairs(Players:GetPlayers()) do
				if pl ~= LocalPlayer and pl.Character and hit.Instance:IsDescendantOf(pl.Character) then
					doKick(pl)
					break
				end
			end
		end

		getgenv().FKeyInputConnection = UserInputService.InputBegan:Connect(function(input, gp)
			if gp or not getgenv().KickGrabActive then return end
			local isF = input.KeyCode == Enum.KeyCode.F
			local isTouch = input.UserInputType == Enum.UserInputType.Touch
			-- Mobile: double-tap style — second touch while grabbing kicks crosshair target
			if not isF and not (isTouch and UserInputService.TouchEnabled) then return end
			if isTouch then
				-- only fire on touch if already grabbing someone (prevents random kicks)
				if not getGrabbedPlayer() then return end
			end
			tryCrosshairKick()
		end)
	end
})

