    -- Player ESP
    do
        espEnabled = false
        espColor = Color3.fromRGB(0, 255, 255)
        rainbowEnabled = false
        espConnections = {}
        espObjects = {}
        
        function createESP(player)
            if not player or not player.Character then return end
            
            local char = player.Character
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            
            local highlight = Instance.new("Highlight")
            highlight.Name = "ESP_Highlight"
            highlight.Adornee = char
            highlight.FillColor = espColor
            highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
            highlight.FillTransparency = 0.4
            highlight.OutlineTransparency = 0
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = char
            
            local billboard = Instance.new("BillboardGui")
            billboard.Name = "ESP_Name"
            billboard.Adornee = hrp
            billboard.Size = UDim2.new(0, 200, 0, 30)
            billboard.StudsOffset = Vector3.new(0, 3, 0)
            billboard.AlwaysOnTop = true
            billboard.Parent = hrp
            
            local label = Instance.new("TextLabel")
            label.Size = UDim2.new(1, 0, 1, 0)
            label.BackgroundTransparency = 1
            label.Text = player.DisplayName .. " (" .. player.Name .. ")"
            label.TextColor3 = Color3.fromRGB(255, 255, 255)
            label.TextStrokeTransparency = 0
            label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            label.Font = Enum.Font.GothamBold
            label.TextScaled = true
            label.Parent = billboard
            
            local distBillboard = Instance.new("BillboardGui")
            distBillboard.Name = "ESP_Distance"
            distBillboard.Adornee = hrp
            distBillboard.Size = UDim2.new(0, 100, 0, 20)
            distBillboard.StudsOffset = Vector3.new(0, -2, 0)
            distBillboard.AlwaysOnTop = true
            distBillboard.Parent = hrp
            
            local distLabel = Instance.new("TextLabel")
            distLabel.Size = UDim2.new(1, 0, 1, 0)
            distLabel.BackgroundTransparency = 1
            distLabel.Text = "0 studs"
            distLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
            distLabel.TextStrokeTransparency = 0
            distLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            distLabel.Font = Enum.Font.GothamBold
            distLabel.TextScaled = true
            distLabel.Parent = distBillboard
            
            table.insert(espObjects, {
                player = player,
                highlight = highlight,
                billboard = billboard,
                distBillboard = distBillboard,
                label = label,
                distLabel = distLabel
            })
            
            local conn = RunService.RenderStepped:Connect(function()
                if not espEnabled or not player.Character then
                    conn:Disconnect()
                    return
                end
                
                local localChar = LocalPlayer.Character
                local localHrp = localChar and localChar:FindFirstChild("HumanoidRootPart")
                if localHrp and hrp and hrp.Parent then
                    local dist = math.floor((hrp.Position - localHrp.Position).Magnitude)
                    distLabel.Text = dist .. " studs"
                end
            end)
            table.insert(espConnections, conn)
        end
        
        function clearESP()
            for _, conn in ipairs(espConnections) do
                pcall(function() conn:Disconnect() end)
            end
            espConnections = {}
            
            for _, obj in ipairs(espObjects) do
                pcall(function()
                    if obj.highlight then obj.highlight:Destroy() end
                    if obj.billboard then obj.billboard:Destroy() end
                    if obj.distBillboard then obj.distBillboard:Destroy() end
                end)
            end
            espObjects = {}
        end
        
        function updateAllESP()
            clearESP()
            if not espEnabled then return end
            
            for _, plr in pairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer and plr.Character then
                    createESP(plr)
                end
            end
        end
        
        function updateColors()
            for _, obj in ipairs(espObjects) do
                pcall(function()
                    if obj.highlight then
                        obj.highlight.FillColor = espColor
                    end
                end)
            end
        end
        
        VisL:CreateToggle({
            Name = "ESP Rainbow",
            Default = false,
            Callback = function(Value)
                rainbowEnabled = Value
                if Value then
                    task.spawn(function()
                        while rainbowEnabled and espEnabled do
                            local hue = tick() % 1
                            espColor = Color3.fromHSV(hue, 1, 1)
                            updateColors()
                            task.wait(0.05)
                        end
                    end)
                else
                    espColor = Color3.fromRGB(0, 255, 255)
                    updateColors()
                end
            end
        })
        
        VisL:CreateToggle({
            Name = "ESP",
            Default = false,
            Callback = function(Value)
                espEnabled = Value
                if Value then
                    updateAllESP()
                    
                    local playerAddedConn = Players.PlayerAdded:Connect(function(plr)
                        task.wait(0.5)
                        if espEnabled and plr ~= LocalPlayer and plr.Character then
                            createESP(plr)
                        end
                    end)
                    table.insert(espConnections, playerAddedConn)
                    
                    local charAddedConn = Players.PlayerAdded:Connect(function(plr)
                        if espEnabled and plr ~= LocalPlayer then
                            local charConn = plr.CharacterAdded:Connect(function()
                                task.wait(0.5)
                                if espEnabled and plr.Character then
                                    local exists = false
                                    for _, obj in ipairs(espObjects) do
                                        if obj.player == plr then
                                            exists = true
                                            break
                                        end
                                    end
                                    if not exists then
                                        createESP(plr)
                                    end
                                end
                            end)
                            table.insert(espConnections, charConn)
                        end
                    end)
                    table.insert(espConnections, charAddedConn)
                else
                    clearESP()
                end
            end
        })
        
        Players.PlayerRemoving:Connect(function(plr)
            for i, obj in ipairs(espObjects) do
                if obj.player == plr then
                    pcall(function()
                        if obj.highlight then obj.highlight:Destroy() end
                        if obj.billboard then obj.billboard:Destroy() end
                        if obj.distBillboard then obj.distBillboard:Destroy() end
                    end)
                    table.remove(espObjects, i)
                    break
                end
            end
        end)
    end

    -- PCLD ESP (Box)
    do
        pcldEnabled = false
        pcldBoxes = {}
        pcldColor = Color3.fromRGB(0, 255, 255)
        pcldRainbow = false
        pcldConnections = {}

        local targetNames = {"partesp", "playercharacterlocationdetector"}

        function IsTarget(obj)
            if not obj:IsA("BasePart") then
                return false
            end
            for _, name in ipairs(targetNames) do
                if string.lower(obj.Name) == string.lower(name) then
                    return true
                end
            end
            return false
        end

        function AddBoxESP(obj)
            if pcldBoxes[obj] then
                return
            end
            local box = Instance.new("BoxHandleAdornment")
            box.Adornee = obj
            box.AlwaysOnTop = true
            box.ZIndex = 5
            box.Color3 = pcldColor
            box.Transparency = 0.3
            box.Size = obj.Size
            local okParent = pcall(function() box.Parent = game.CoreGui end)
            if not okParent or not box.Parent then
                box.Parent = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
            end
            pcldBoxes[obj] = box
            
            local conn = obj.AncestryChanged:Connect(function(_, parent)
                if not parent and pcldBoxes[obj] then
                    if pcldBoxes[obj] then
                        pcldBoxes[obj]:Destroy()
                    end
                    pcldBoxes[obj] = nil
                end
            end)
            table.insert(pcldConnections, conn)
        end

        function RemoveAllBoxes()
            for obj, box in pairs(pcldBoxes) do
                if box then
                    box:Destroy()
                end
            end
            pcldBoxes = {}
            for _, conn in ipairs(pcldConnections) do
                pcall(function() conn:Disconnect() end)
            end
            pcldConnections = {}
        end

        function Scan()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if pcldEnabled and IsTarget(obj) then
                    AddBoxESP(obj)
                end
            end
        end

        function UpdatePCLDColors()
            for _, box in pairs(pcldBoxes) do
                pcall(function()
                    box.Color3 = pcldColor
                end)
            end
        end

        VisL:CreateToggle({
            Name = "PCLD Rainbow",
            Default = false,
            Callback = function(v)
                pcldRainbow = v
                if v then
                    task.spawn(function()
                        while pcldRainbow do
                            local hue = tick() % 1
                            local color = Color3.fromHSV(hue, 1, 1)
                            for _, box in pairs(pcldBoxes) do
                                pcall(function()
                                    box.Color3 = color
                                end)
                            end
                            task.wait(0.05)
                        end
                    end)
                else
                    pcldColor = Color3.fromRGB(0, 255, 255)
                    UpdatePCLDColors()
                end
            end
        })

        VisL:CreateToggle({
            Name = "Enable PCLD",
            Default = false,
            Callback = function(v)
                pcldEnabled = v
                if pcldEnabled then
                    Scan()
                    local conn = workspace.DescendantAdded:Connect(function(obj)
                        if pcldEnabled and IsTarget(obj) then
                            AddBoxESP(obj)
                        end
                    end)
                    table.insert(pcldConnections, conn)
                else
                    RemoveAllBoxes()
                end
            end
        })
    end
end

local KB_THRESHOLD = 5
local BYTE_THRESHOLD = KB_THRESHOLD * 1024
local COOLDOWN = 30
local lastNotify = 0
local packetConnections = {}
-- Utility Functions using Script 6 UI's notification style
local function packetNotify(title, text)
    pcall(function()
        Library:Notify({
            Title = title or "Packet Detected",
            Content = text or "",
            Duration = 7
        })
    end)
end

ServerGroup = Tabs.Server:CreateBlock({Name = "Lag", Side = "Left"})
KickGroup = Tabs.Server:CreateBlock({Name = "Mass Actions", Side = "Right"})

do
	local function cornerNotify(title, content, duration)
		duration = duration or 5
		pcall(function()
			local Z = ((getgenv and getgenv()) or _G).Zyrix
			if Z and Z.Notify then
				Z:Notify(tostring(title), tostring(content), duration, "info")
				return
			end
		end)
		pcall(function()
			if Library and Library.Notify then
				Library:Notify({Title = tostring(title), Content = tostring(content), Duration = duration})
				return
			end
		end)
		pcall(function()
			game:GetService("StarterGui"):SetCore("SendNotification", {
				Title = tostring(title),
				Text = tostring(content),
				Duration = duration,
			})
		end)
	end

	local function fluxyCheckScripts()
		local hits = {}
		local g = (getgenv and getgenv()) or _G
		local Players = game:GetService("Players")
		local LP = Players.LocalPlayer

		local function add(msg)
			table.insert(hits, tostring(msg))
		end

		-- Blitz (BlizTBr) is Luraph-obfuscated FTAP loader
		-- github.com/BlizTBr/scripts/main/FTAP.lua
		pcall(function()
			for k, v in pairs(g) do
				local ks = string.lower(tostring(k))
				if ks:find("blitz", 1, true) or ks:find("blizt", 1, true)
					or ks:find("ftap", 1, true) or ks:find("endoris", 1, true)
					or ks:find("luraph", 1, true) then
					add("LOCAL genv." .. tostring(k))
				end
			end
			for _, k in ipairs({"Blitz", "BlizT", "BlizTBr", "FTAP", "Endoris", "EndorisFTAP", "BlitzLoaded", "FTAPLoaded"}) do
				if g[k] ~= nil then add("LOCAL genv." .. k) end
			end
		end)

		pcall(function()
			local parents = {}
			if LP:FindFirstChild("PlayerGui") then table.insert(parents, LP.PlayerGui) end
			pcall(function() table.insert(parents, game:GetService("CoreGui")) end)
			pcall(function() if gethui then table.insert(parents, gethui()) end end)
			for _, parent in ipairs(parents) do
				for _, d in ipairs(parent:GetDescendants()) do
					if d:IsA("ScreenGui") then
						local n = string.lower(d.Name)
						if n:find("blitz", 1, true) or n:find("blizt", 1, true)
							or n:find("ftap", 1, true) or n:find("endoris", 1, true) then
							add("LOCAL GUI " .. d.Name)
						end
					end
				end
			end
		end)

		for _, plr in ipairs(Players:GetPlayers()) do
			if plr == LP then continue end
			local char = plr.Character
			if not char then continue end
			local score = 0
			local reasons = {}
			pcall(function()
				for _, d in ipairs(char:GetDescendants()) do
					if d:IsA("BodyVelocity") or d:IsA("BodyPosition") or d:IsA("BodyGyro") or d:IsA("LinearVelocity") then
						local ln = string.lower(d.Name)
						if ln:find("ftap", 1, true) or ln:find("blitz", 1, true)
							or ln:find("endoris", 1, true) or ln:find("fluxy", 1, true)
							or ln:find("aura", 1, true) then
							score += 3
							table.insert(reasons, d.Name)
						end
					end
				end
				local toys = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
				if toys and #toys:GetChildren() >= 10 then
					score += 2
					table.insert(reasons, "toys x" .. #toys:GetChildren())
				end
			end)
			if score >= 3 then
				add(plr.DisplayName .. " (@" .. plr.Name .. ") score " .. score)
			end
		end)

		if #hits == 0 then
			cornerNotify("Check Scripts", "No Blitz/FTAP traces found", 4)
			print("[Fluxy] Check Scripts: clean")
		else
			cornerNotify("Check Scripts", #hits .. " hit(s) — see list", 5)
			for i, h in ipairs(hits) do
				task.delay(0.15 * i, function()
					cornerNotify("Hit " .. i .. "/" .. #hits, h, 4)
				end)
			end
			print("[Fluxy] Check Scripts hits:")
			for _, h in ipairs(hits) do print("  -", h) end
		end
		return hits
	end

	pcall(function()
		local grp = Tabs.Server:CreateBlock({Name = "Script Check", Side = "Left"})
		if not grp then return end
		grp:CreateButton({
			Name = "Check Scripts",
			Callback = function()
				task.spawn(fluxyCheckScripts)
			end,
		})
	end)
end


selectedHeight = "Spawn"

function getAllPlayers()
    local players = {}
    local g = (getgenv and getgenv()) or _G
    local protectOn = g.FluxyProtectFriends == true
    local antiLag = g.FluxyAntiLagNames or {}
    for _, plr in pairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then
            local skip = false
            if antiLag[plr.Name] then
                skip = true
            elseif protectOn then
                pcall(function()
                    if LocalPlayer:IsFriendsWith(plr.UserId) then skip = true end
                end)
            end
            if not skip then
                table.insert(players, plr)
            end
        end
    end
    return players
end

GrabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")

function spamOwnership(hrp)
    if not GrabEvents then
        GrabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
    end
    if not GrabEvents or not hrp then return end
    local setOwner = GrabEvents:FindFirstChild("SetNetworkOwner")
    if setOwner then
        pcall(function() setOwner:FireServer(hrp, hrp.CFrame) end)
    end
end

function teleportToPlayer(myHrp, targetHrp)
    if not myHrp or not targetHrp then return end
    pcall(function()
        myHrp.CFrame = targetHrp.CFrame * CFrame.new(0, 5, 5)
        myHrp.AssemblyLinearVelocity = Vector3.zero
    end)
end

function destroyLineOnPlayer(hrp)
    if not GrabEvents then
        GrabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
    end
    if not GrabEvents or not hrp then return end
    local createLine = GrabEvents:FindFirstChild("CreateGrabLine")
    local destroyLine = GrabEvents:FindFirstChild("DestroyGrabLine")
    if not createLine or not destroyLine then return end
    pcall(function()
        createLine:FireServer(hrp, CFrame.new(0, 1e9, 0))
        task.wait()
        destroyLine:FireServer(hrp)
    end)
end

lineLagThread = nil
lineLagEnabled = false

function startLineLag()
    if lineLagEnabled then return end
    lineLagEnabled = true
    if not GrabEvents then
        GrabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
    end
    -- task.spawn is more reliable than coroutine.resume + task.wait
    lineLagThread = task.spawn(function()
        local createLine = GrabEvents and GrabEvents:FindFirstChild("CreateGrabLine")
        if not createLine then
            lineLagEnabled = false
            return
        end
        while lineLagEnabled do
            local spawnLocation = Workspace:FindFirstChild("SpawnLocation")
                or Workspace:FindFirstChild("Spawn")
                or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart"))
            if spawnLocation then
                local randomX = math.random(-1e9, 1e9)
                local randomZ = math.random(-1e9, 1e9)
                local directions = {
                    CFrame.new(randomX, 0, randomZ),
                    CFrame.new(-randomX, 0, -randomZ),
                    CFrame.new(randomX, 0, -randomZ),
                    CFrame.new(-randomX, 0, randomZ),
                }
                for _, pos in pairs(directions) do
                    pcall(function() createLine:FireServer(spawnLocation, pos) end)
                end
            end
            task.wait()
        end
    end)
end

function stopLineLag()
    lineLagEnabled = false
    lineLagThread = nil
end

-- Anti Lag for selected players (they skip Destroy Server + continuous unlag on their body)
do
	local g = (getgenv and getgenv()) or _G
	g.FluxyAntiLagNames = g.FluxyAntiLagNames or {}
	g.FluxyAntiLagActive = g.FluxyAntiLagActive == true

	function isAntiLagPlayer(plr)
		local names = g.FluxyAntiLagNames or {}
		if type(plr) == "string" then return names[plr] == true end
		return plr and names[plr.Name] == true
	end

	local antiLagThread = nil
	function startAntiLagProtectLoop()
		if antiLagThread then return end
		antiLagThread = task.spawn(function()
			while true do
				local names = g.FluxyAntiLagNames or {}
				local hasAny = false
				for _, on in pairs(names) do
					if on then hasAny = true break end
				end
				if not hasAny or g.FluxyAntiLagActive == false then
					task.wait(0.25)
					continue
				end
				if g.FluxyAntiLagActive == nil then
					g.FluxyAntiLagActive = true
				end
				if not GrabEvents then
					GrabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
				end
				local destroyLine = GrabEvents and GrabEvents:FindFirstChild("DestroyGrabLine")
				local setOwner = GrabEvents and GrabEvents:FindFirstChild("SetNetworkOwner")
				local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				for name, on in pairs(names) do
					if not on then continue end
					local plr = Players:FindFirstChild(name)
					local char = plr and plr.Character
					if not char then continue end
					for _, partName in ipairs({"HumanoidRootPart", "Head", "Torso", "UpperTorso", "LowerTorso"}) do
						local part = char:FindFirstChild(partName)
						if part and part:IsA("BasePart") then
							if destroyLine then
								pcall(function() destroyLine:FireServer(part) end)
							end
							if setOwner and myRoot then
								pcall(function()
									setOwner:FireServer(part, CFrame.lookAt(myRoot.Position, part.Position))
								end)
							end
							pcall(function()
								part.AssemblyLinearVelocity = Vector3.zero
								part.AssemblyAngularVelocity = Vector3.zero
							end)
						end
					end
				end
				task.wait(0.08)
			end
		end)
	end
	startAntiLagProtectLoop()
end

