    local function getPacketSize()
        -- 1 MB = ~1,000,000 ตัวอักษร
        -- แต่ละ char = 1 byte, emoji = 4 bytes
        -- ใช้ string.rep("A", ขนาด) ได้ง่ายกว่า
        return packetLagSize * 1000000
    end

    ServerGroup:CreateSlider({
        Name = "Packet Size",
