local tpEnabled = true -- РјРѕР¶РЅРѕ СѓР±СЂР°С‚СЊ, РµСЃР»Рё РЅРµ РЅСѓР¶РµРЅ on/off

KeybindsGroup:CreateKeybind({
	Name = "Teleport to Mouse",
	Flag = "TPKeybind",
	Default = "X",
	Callback = function()
		if not tpEnabled then return end
		local character = Player.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		local targetPos = nil
		pcall(function()
			if Mouse and Mouse.Hit then targetPos = Mouse.Hit.Position end
		end)
		if not targetPos then
			local cam = workspace.CurrentCamera
			if cam then
				local ray = cam:ScreenPointToRay(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
				local params = RaycastParams.new()
				params.FilterDescendantsInstances = { character }
				params.FilterType = Enum.RaycastFilterType.Exclude
				local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000, params)
				if hit then targetPos = hit.Position end
			end
		end
		if targetPos then
			hrp.CFrame = CFrame.new(targetPos + Vector3.new(0, 3, 0))
			hrp.AssemblyLinearVelocity = Vector3.zero
		end
	end
})
