        Head = { pos = 'HeadPosition', rot = 'HeadRotation' },
        ['Left Arm'] = { pos = 'LeftArmPosition', rot = 'LeftArmRotation' },
        ['Right Arm'] = { pos = 'RightArmPosition', rot = 'RightArmRotation' },
