        Items = { 'Doggy', 'Crawl', 'Lay Down', 'Beg', 'Sit Pretty', 'Pose1', 'Pose2', 'Pose3', 'Pose4', 'Pose5', 'Pose6', 'Pose7', 'JojoStand' },
        Default = 'Doggy',
        Callback = function(v)
            if type(v) == "table" then v = v[1] or v end
            Options.FGM_PresetPose = v
        end
    })

    PosesBlock:CreateButton({
        Name = "Doggy (All Fours)",
        Callback = function()
            if FGM.ApplyPreset then
                FGM.ApplyPreset("Doggy")
                Options.FGM_PresetPose = "Doggy"
            end
        end
    })

    PosesBlock:CreateButton({
        Name = "Apply Pose (on target)",
        Callback = function()
            if FGM.ApplyPreset then
                local selected = Options.FGM_PresetPose or 'Doggy'
                if type(selected) == "table" then selected = selected[1] or selected end
                FGM.ApplyPreset(selected)
            end
        end
    })

    PosesBlock:CreateButton({
        Name = "Reset to Default Pose",
        Callback = function()
            if FGM.ResetPose then
                FGM.ResetPose()
            end
        end
