local Players = game:GetService("Players")
local Player = Players.LocalPlayer

function getNearestBlobman(maxDist)
	local char = Player.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then return nil end
	local nearest, dist = nil, maxDist or 200
	local function consider(model)
		if not model or not model:IsA("Model") or model.Name ~= "CreatureBlobman" then return end
		local root = model:FindFirstChild("VehicleSeat") or model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
		if not root then return end
		local pos = root:IsA("BasePart") and root.Position or model:GetPivot().Position
		local d = (pos - hrp.Position).Magnitude
		if d < dist then
			dist = d
			nearest = model
		end
	end
	local toys = workspace:FindFirstChild(Player.Name .. "SpawnedInToys")
	if toys then
		for _, model in ipairs(toys:GetChildren()) do consider(model) end
	end
	for _, model in ipairs(workspace:GetChildren()) do consider(model) end
	if not nearest then
		for _, model in ipairs(workspace:GetDescendants()) do
			if model:IsA("Model") and model.Name == "CreatureBlobman" then consider(model) end
		end
	end
	return nearest
end

function SitOnBlobman()
	local char = Player.Character
	if not char then return end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local hrp = char:FindFirstChild("HumanoidRootPart")
	if not hum or not hrp then return end
	if hum.SeatPart then
		pcall(function() hum.Sit = false end)
		task.wait(0.08)
	end
	local blob = getNearestBlobman(200)
	if not blob then
		local folder = workspace:FindFirstChild(Player.Name .. "SpawnedInToys")
		if folder then
			blob = folder:FindFirstChild("CreatureBlobman")
		end
	end
	if not blob then
		warn("Blobman not found nearby")
		return
	end
	local seat = blob:FindFirstChild("VehicleSeat")
		or blob:FindFirstChildWhichIsA("VehicleSeat", true)
		or blob:FindFirstChildWhichIsA("Seat", true)
	if not seat then
		warn("Blobman seat not found")
		return
	end
	if seat.Occupant and seat.Occupant ~= hum then
		pcall(function() seat.Occupant.Jump = true end)
		task.wait(0.08)
	end
	hrp.CFrame = seat.CFrame * CFrame.new(0, 2, 0)
	task.wait(0.05)
	pcall(function() seat:Sit(hum) end)
	task.delay(0.1, function()
		if hum and not hum.Sit and seat and seat.Parent then
			pcall(function()
				hrp.CFrame = seat.CFrame * CFrame.new(0, 2, 0)
				seat:Sit(hum)
			end)
		end
	end)
end


KeybindsGroup:CreateKeybind({
	Name = "Sit on nearest Blobman",
	Flag = "SitBlobmanKey",
	Default = "Z",
	Callback = function()
		SitOnBlobman()
	end
})


