-- DEFERRED LAUNCH: FTAP tabs register below. Launch runs at the very end so
-- Kicks/Loop/Aura/Telekinesis/Utility/Fun/Server are not empty.
genv.FluxyLaunchUI = function()
	-- Allow retry if previous attempt failed to build UI
	local ui = genv.ZyrixUI
	if genv._FluxyLaunched and ui and ui.IsBuilt and ui.IsBuilt() then
		pcall(function() ui:Open() end)
		pcall(function() if ui.Expand then ui:Expand() end end)
		return
	end
	genv._FluxyLaunched = false
	local Z = (Library and Library._Zyrix) or genv.Zyrix
	if not Z then
		warn("[fluxy] Zyrix missing — cannot show UI")
		return
	end
	genv.Zyrix = Z
	if Library then Library._Zyrix = Z end
	pcall(function()
		Z.Options = Z.Options or {}
		Z.Options.Keyless = true
		Z.Options.KeylessUI = false
	end)
	genv.SCRIPT_KEY = genv.SCRIPT_KEY or "KEYLESS"
	if genv.SCRIPT_KEY == "" then genv.SCRIPT_KEY = "KEYLESS" end
	local ok, err = pcall(function() Z:Launch() end)
	if not ok then
		warn("[fluxy] Launch error: " .. tostring(err))
	end
	task.spawn(function()
		for i = 1, 40 do
			ui = genv.ZyrixUI
			if ui then
				pcall(function() ui:Open() end)
				pcall(function() if ui.Expand then ui:Expand() end end)
				pcall(function()
					local parents = {}
					if gethui then table.insert(parents, gethui()) end
					local lp = game:GetService("Players").LocalPlayer
					if lp then table.insert(parents, lp:FindFirstChild("PlayerGui")) end
					pcall(function() table.insert(parents, game:GetService("CoreGui")) end)
					for _, parent in ipairs(parents) do
						if parent then
							local sg = parent:FindFirstChild("ZyrixMainUI")
							if sg then
								sg.Enabled = true
								sg.DisplayOrder = 2147483647
							end
						end
					end
				end)
				if ui.IsBuilt and ui.IsBuilt() then
					genv._FluxyLaunched = true
					warn("[fluxy] UI shown")
					return
				end
			end
			task.wait(0.15)
		end
		genv._FluxyLaunched = true
		warn("[fluxy] UI still not built — check Zyrix library")
	end)
end


