local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local RunService = game:GetService("RunService")
local Lighting = game:GetService("Lighting")
local Debris = game:GetService("Debris")
local TweenService = game:GetService("TweenService")
local HttpService = game:GetService("HttpService")
local TeleportService = game:GetService("TeleportService")
local Camera = Workspace.CurrentCamera

local LocalPlayer = Players.LocalPlayer
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

-- place/mobile/executor kicks removed so UI always loads

-- ======================================================
-- Zyrix UI Library — the REAL Zyrix (loaded exactly like the
-- Example LocalScript does), with the embedded copy kept
-- only as a fallback for environments without HttpGet
-- ======================================================
if getgenv then getgenv().ZyrixSkipDefaultHub = true end

local Zyrix = nil
local usingRealZyrix = false

-- Load the REAL Zyrix library first (same source as StarterGui.Example)
do
	local ok, result = pcall(function()
		-- Reuse the library fluxy already loaded at the top of this script.
		-- Loading the library file twice re-runs its initialization (and its
		-- demo/example hub on stale repo copies), which clobbers the main
		-- fluxy hub that was already launched.
		local g = (getgenv and getgenv()) or _G
		if g.Zyrix and g.ZyrixUI then
			return g.Zyrix
		end
		if loadstring and game.HttpGet then
			return loadstring(game:HttpGet("https://raw.githubusercontent.com/VYZ3N-scripts/Zyrix/main/Zyrix.lua"))()
		end
		return nil
	end)
	if ok and type(result) == "table" and type(result.CreateWindow) == "function" then
		Zyrix = result
		usingRealZyrix = true
	end
end

-- Fallback: embedded Zyrix implementation (Studio / no HttpGet)
if not Zyrix then
Zyrix = {
	Appearance = {Title = "ftap1", Subtitle = "v1"},
	Callbacks = {},
	Options = {},
	ScreenGui = nil,
	_toggleKey = Enum.KeyCode.RightControl,
	_notifications = {},
}

Zyrix.C = {
	Bg = Color3.fromRGB(16, 16, 22),
	Panel = Color3.fromRGB(22, 22, 30),
	Element = Color3.fromRGB(30, 30, 40),
	Active = Color3.fromRGB(38, 38, 52),
	Accent = Color3.fromRGB(124, 92, 255),
	Text = Color3.fromRGB(235, 235, 245),
	SubText = Color3.fromRGB(150, 150, 165),
}

function Zyrix.new(className, props, parent)
	local inst = Instance.new(className)
	if props then
		for k, v in pairs(props) do
			inst[k] = v
		end
	end
	inst.Parent = parent
	return inst
end

function Zyrix.corner(parent, radius)
	return Zyrix.new("UICorner", {CornerRadius = UDim.new(0, radius or 6)}, parent)
end

function Zyrix.drag(frame, handle)
	local dragging = false
	local dragInput, dragStart, startPos
	handle.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = frame.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)
	handle.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)
	UserInputService.InputChanged:Connect(function(input)
		if input == dragInput and dragging then
			local delta = input.Position - dragStart
			frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
end

function Zyrix:CreateWindow(config)
	local ZC, zNew, zCorner, zDrag = Zyrix.C, Zyrix.new, Zyrix.corner, Zyrix.drag
	config = config or {}
	if config.ToggleUIKeybind then
		local ok, key = pcall(function() return Enum.KeyCode[config.ToggleUIKeybind] end)
		if ok and key then
			Zyrix._toggleKey = key
		end
	end

	local gui = zNew("ScreenGui", {
		Name = "Zyrix",
		DisplayOrder = 999999,
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		Enabled = false,
	})
	do
		local parented = pcall(function() gui.Parent = CoreGui end)
		if not parented or not gui.Parent then
			gui.Parent = PlayerGui
		end
	end
	Zyrix.ScreenGui = gui

	local main = zNew("Frame", {
		Name = "Main",
		Size = UDim2.fromOffset(620, 440),
		Position = UDim2.new(0.5, -310, 0.5, -220),
		BackgroundColor3 = ZC.Bg,
		Active = true,
	}, gui)
	zCorner(main, 10)
	zNew("UIStroke", {Color = Color3.fromRGB(70, 70, 95), Thickness = 1, Transparency = 0.35}, main)

	local titleBar = zNew("Frame", {
		Size = UDim2.new(1, 0, 0, 38),
		BackgroundColor3 = ZC.Panel,
	}, main)
	zCorner(titleBar, 10)
	zNew("TextLabel", {
		Position = UDim2.new(0, 14, 0, 0),
		Size = UDim2.new(1, -28, 1, 0),
		BackgroundTransparency = 1,
		Text = config.Name or Zyrix.Appearance.Title or "ftap1",
		TextColor3 = ZC.Text,
		Font = Enum.Font.GothamBold,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, titleBar)
	zDrag(main, titleBar)

	local tabBar = zNew("Frame", {
		Position = UDim2.new(0, 8, 0, 46),
		Size = UDim2.new(0, 136, 1, -54),
		BackgroundColor3 = ZC.Panel,
	}, main)
	zCorner(tabBar, 8)
	zNew("UIListLayout", {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder}, tabBar)
	zNew("UIPadding", {PaddingTop = UDim.new(0, 6), PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6)}, tabBar)

	local content = zNew("Frame", {
		Position = UDim2.new(0, 152, 0, 46),
		Size = UDim2.new(1, -160, 1, -54),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
	}, main)

	local window = {}
	window._tabData = {}

	function window:CreateTab(tabName)
		local btn = zNew("TextButton", {
			Size = UDim2.new(1, 0, 0, 28),
			BackgroundColor3 = ZC.Element,
			AutoButtonColor = false,
			Text = tabName or "Tab",
			TextColor3 = ZC.Text,
			Font = Enum.Font.GothamMedium,
			TextSize = 13,
		}, tabBar)
		zCorner(btn, 6)

		local page = zNew("ScrollingFrame", {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 4,
			ScrollBarImageColor3 = ZC.Accent,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			Visible = false,
		}, content)
		zNew("UIListLayout", {Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder}, page)
		zNew("UIPadding", {PaddingRight = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10)}, page)

		local tab = {}
		local layoutOrder = 0
		local function nextOrder()
			layoutOrder += 1
			return layoutOrder
		end

		local function selectTab()
			for _, data in ipairs(window._tabData) do
				data.page.Visible = false
				data.btn.BackgroundColor3 = ZC.Element
			end
			page.Visible = true
			btn.BackgroundColor3 = ZC.Active
		end
		btn.MouseButton1Click:Connect(selectTab)

		table.insert(window._tabData, {btn = btn, page = page})
		if #window._tabData == 1 then
			task.defer(selectTab)
		end

		local function newRow(height)
			local row = zNew("Frame", {
				Size = UDim2.new(1, 0, 0, height or 32),
				BackgroundColor3 = ZC.Element,
				LayoutOrder = nextOrder(),
			}, page)
			zCorner(row, 6)
			return row
		end

		function tab:CreateSection(sectionName)
			local holder = zNew("Frame", {
				Size = UDim2.new(1, 0, 0, 26),
				BackgroundTransparency = 1,
				LayoutOrder = nextOrder(),
			}, page)
			zNew("TextLabel", {
				Size = UDim2.new(1, 0, 0, 18),
				BackgroundTransparency = 1,
				Text = sectionName or "Section",
				TextColor3 = ZC.SubText,
				Font = Enum.Font.GothamBold,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, holder)
			zNew("Frame", {
				Position = UDim2.new(0, 0, 1, -2),
				Size = UDim2.new(1, 0, 0, 1),
				BackgroundColor3 = ZC.Accent,
				BackgroundTransparency = 0.4,
			}, holder)
			return holder
		end

		function tab:CreateToggle(cfg)
			cfg = cfg or {}
			local row = newRow()
			zNew("TextLabel", {
				Position = UDim2.new(0, 10, 0, 0),
				Size = UDim2.new(1, -70, 1, 0),
				BackgroundTransparency = 1,
				Text = cfg.Name or "Toggle",
				TextColor3 = ZC.Text,
				Font = Enum.Font.Gotham,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			local box = zNew("TextButton", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -8, 0.5, 0),
				Size = UDim2.fromOffset(42, 20),
				BackgroundColor3 = ZC.Bg,
				AutoButtonColor = false,
				Text = "",
			}, row)
			zCorner(box, 10)
			local knob = zNew("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 3, 0.5, 0),
				Size = UDim2.fromOffset(14, 14),
				BackgroundColor3 = ZC.SubText,
			}, box)
			zCorner(knob, 7)

			local state = cfg.CurrentValue and true or false
			local toggle = {}
			local function render()
				if state then
					box.BackgroundColor3 = ZC.Accent
					knob.BackgroundColor3 = Color3.new(1, 1, 1)
					knob.Position = UDim2.new(1, -17, 0.5, 0)
				else
					box.BackgroundColor3 = ZC.Bg
					knob.BackgroundColor3 = ZC.SubText
					knob.Position = UDim2.new(0, 3, 0.5, 0)
				end
			end
			local function set(value, skipCallback)
				state = value and true or false
				render()
				if not skipCallback and cfg.Callback then
					pcall(cfg.Callback, state)
				end
			end
			box.MouseButton1Click:Connect(function()
				set(not state)
			end)
			render()
			function toggle:Set(value)
				set(value, true)
			end
			return toggle
		end

		function tab:CreateSlider(cfg)
			cfg = cfg or {}
			local row = newRow(48)
			local min = cfg.Range and cfg.Range[1] or 0
			local max = cfg.Range and cfg.Range[2] or 100
			local value = math.clamp(tonumber(cfg.CurrentValue) or min, min, max)
			local slider = {}

			zNew("TextLabel", {
				Position = UDim2.new(0, 10, 0, 4),
				Size = UDim2.new(1, -70, 0, 16),
				BackgroundTransparency = 1,
				Text = cfg.Name or "Slider",
				TextColor3 = ZC.Text,
				Font = Enum.Font.Gotham,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			local valueLabel = zNew("TextLabel", {
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -10, 0, 4),
				Size = UDim2.new(0, 60, 0, 16),
				BackgroundTransparency = 1,
			Text = "",
				TextColor3 = ZC.SubText,
				Font = Enum.Font.GothamMedium,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Right,
			}, row)
			local track = zNew("Frame", {
				AnchorPoint = Vector2.new(0.5, 1),
				Position = UDim2.new(0.5, 0, 1, -8),
				Size = UDim2.new(1, -20, 0, 6),
				BackgroundColor3 = ZC.Bg,
			}, row)
			zCorner(track, 3)
			local fill = zNew("Frame", {
				Size = UDim2.new(0, 0, 1, 0),
				BackgroundColor3 = ZC.Accent,
			}, track)
			zCorner(fill, 3)

			local function render()
				local alpha = (max > min) and ((value - min) / (max - min)) or 0
				fill.Size = UDim2.new(math.clamp(alpha, 0, 1), 0, 1, 0)
				valueLabel.Text = tostring(value) .. (cfg.Suffix or "")
			end
			local function set(newValue, skipCallback)
				newValue = tonumber(newValue) or value
				if min == math.floor(min) and max == math.floor(max) then
					newValue = math.floor(newValue + 0.5)
				end
				value = math.clamp(newValue, min, max)
				render()
				if not skipCallback and cfg.Callback then
					pcall(cfg.Callback, value)
				end
			end

			local dragging = false
			local function updateFromX(x)
				local rel = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
				set(min + (max - min) * rel)
			end
			track.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragging = true
					updateFromX(input.Position.X)
				end
			end)
			UserInputService.InputEnded:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragging = false
				end
			end)
			UserInputService.InputChanged:Connect(function(input)
				if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
					updateFromX(input.Position.X)
				end
			end)

			render()
			function slider:Set(newValue)
				set(newValue, true)
			end
			return slider
		end

		function tab:CreateDropdown(cfg)
			cfg = cfg or {}
			local row = newRow()
			zNew("TextLabel", {
				Position = UDim2.new(0, 10, 0, 0),
				Size = UDim2.new(1, -130, 1, 0),
				BackgroundTransparency = 1,
				Text = cfg.Name or "Dropdown",
				TextColor3 = ZC.Text,
				Font = Enum.Font.Gotham,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			local btn = zNew("TextButton", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -8, 0.5, 0),
				Size = UDim2.fromOffset(110, 22),
				BackgroundColor3 = ZC.Bg,
				AutoButtonColor = false,
				Text = "...",
				TextColor3 = ZC.SubText,
				Font = Enum.Font.GothamMedium,
				TextSize = 12,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			zCorner(btn, 6)

			local options = cfg.Options or {}
			local current = nil
			if cfg.CurrentOption and cfg.CurrentOption[1] then
				current = cfg.CurrentOption[1]
			end

			local list = zNew("Frame", {
				Visible = false,
				BackgroundColor3 = ZC.Panel,
				ZIndex = 50,
			}, gui)
			zCorner(list, 6)
			zNew("UIStroke", {Color = Color3.fromRGB(70, 70, 95), Thickness = 1, Transparency = 0.4}, list)
			zNew("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder}, list)
			zNew("UIPadding", {PaddingTop = UDim.new(0, 4), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4)}, list)

			local dropdown = {}

			local function closeList()
				list.Visible = false
			end

			local function buildList()
				for _, child in ipairs(list:GetChildren()) do
					if child:IsA("TextButton") then
						child:Destroy()
					end
				end
				for i, option in ipairs(options) do
					local optionBtn = zNew("TextButton", {
						Size = UDim2.new(1, 0, 0, 24),
						BackgroundColor3 = ZC.Element,
						AutoButtonColor = false,
						Text = tostring(option),
						TextColor3 = ZC.Text,
						Font = Enum.Font.Gotham,
						TextSize = 12,
						TextTruncate = Enum.TextTruncate.AtEnd,
						LayoutOrder = i,
						ZIndex = 51,
					}, list)
					zCorner(optionBtn, 4)
					optionBtn.MouseButton1Click:Connect(function()
						current = option
						btn.Text = tostring(option)
						btn.TextColor3 = ZC.Text
						closeList()
						if cfg.Callback then
								pcall(cfg.Callback, option)
							end
					end)
				end
			end

			local function openList()
				buildList()
				list.Position = UDim2.fromOffset(
					btn.AbsolutePosition.X,
					btn.AbsolutePosition.Y + btn.AbsoluteSize.Y + 4
				)
				list.Size = UDim2.fromOffset(
					math.max(btn.AbsoluteSize.X, 150),
					math.min(#options, 6) * 28 + 8
				)
				list.Visible = true
			end

			btn.MouseButton1Click:Connect(function()
				if list.Visible then
					closeList()
				else
					openList()
				end
			end)

			if current ~= nil then
				btn.Text = tostring(current)
				btn.TextColor3 = ZC.Text
			end

			function dropdown:Set(value)
				current = value
				btn.Text = tostring(value or "...")
				btn.TextColor3 = ZC.Text
			end
			function dropdown:SetOptions(newOptions)
				local prev = current
				options = newOptions or {}
				-- keep previous selection if still in list
				local keep = nil
				if prev then
					for _, opt in ipairs(options) do
						if tostring(opt) == tostring(prev) or tostring(opt):find(tostring(prev), 1, true) then
							keep = opt
							break
						end
					end
				end
				if not keep then
					local g = (getgenv and getgenv()) or _G
					local last = g.FluxyStickyPlayers and g.FluxyStickyPlayers._last
					if last then
						for _, opt in ipairs(options) do
							if tostring(opt):find(last, 1, true) then
								keep = opt
								break
							end
						end
					end
				end
				current = keep or prev
				btn.Text = tostring(current or "...")
				btn.TextColor3 = current and ZC.Text or ZC.SubText
				closeList()
			end
			function dropdown:SetDisplay(text)
				btn.Text = tostring(text)
			end
			function dropdown:Refresh(newOptions)
				dropdown:SetOptions(newOptions)
			end
			return dropdown
		end

		function tab:CreateButton(cfg)
			cfg = cfg or {}
			local row = zNew("TextButton", {
				Size = UDim2.new(1, 0, 0, 32),
				BackgroundColor3 = ZC.Element,
				AutoButtonColor = false,
				Text = cfg.Name or "Button",
				TextColor3 = ZC.Text,
				Font = Enum.Font.GothamMedium,
				TextSize = 13,
				LayoutOrder = nextOrder(),
			}, page)
			zCorner(row, 6)
			row.MouseButton1Click:Connect(function()
				if cfg.Callback then
					pcall(cfg.Callback)
				end
			end)
			return row
		end

		function tab:CreateKeybind(cfg)
			cfg = cfg or {}
			local row = newRow()
			zNew("TextLabel", {
				Position = UDim2.new(0, 10, 0, 0),
				Size = UDim2.new(1, -100, 1, 0),
				BackgroundTransparency = 1,
				Text = cfg.Name or "Keybind",
				TextColor3 = ZC.Text,
				Font = Enum.Font.Gotham,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			local btn = zNew("TextButton", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -8, 0.5, 0),
				Size = UDim2.fromOffset(80, 22),
				BackgroundColor3 = ZC.Bg,
				AutoButtonColor = false,
				Text = tostring(cfg.CurrentKeybind or "None"),
				TextColor3 = ZC.SubText,
				Font = Enum.Font.GothamMedium,
				TextSize = 12,
			}, row)
			zCorner(btn, 6)

			local listening = false
			btn.MouseButton1Click:Connect(function()
				if listening then return end
				listening = true
				btn.Text = "..."
				if library then library.ChangingKeybind = true end
				local startedAt = tick()
				local conn
				conn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
					if tick() - startedAt < 0.15 then return end
					if input.UserInputType == Enum.UserInputType.Keyboard then
						conn:Disconnect()
						listening = false
						if library then library.ChangingKeybind = false end
						local keyName = input.KeyCode.Name
						btn.Text = keyName
						if cfg.Callback then
							pcall(cfg.Callback, input.KeyCode)
						end
					elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
						conn:Disconnect()
						listening = false
						if library then library.ChangingKeybind = false end
						btn.Text = input.UserInputType.Name
						if cfg.Callback then
							pcall(cfg.Callback, input.UserInputType)
						end
					end
				end)
			end)
			return btn
		end

		function tab:CreateLabel(text)
			local row = zNew("TextLabel", {
				Size = UDim2.new(1, 0, 0, 24),
				BackgroundColor3 = ZC.Element,
				Text = tostring(text or "Label"),
				TextColor3 = ZC.SubText,
				Font = Enum.Font.Gotham,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
				LayoutOrder = nextOrder(),
			}, page)
			zCorner(row, 6)
			zNew("UIPadding", {PaddingLeft = UDim.new(0, 10)}, row)
			return row
		end

		return tab
	end

	return window
end

function Zyrix:Notify(title, message, duration, iconType)
	local ZC, zNew, zCorner = Zyrix.C, Zyrix.new, Zyrix.corner
	task.spawn(function()
		local gui = Zyrix.ScreenGui
		if not gui then return end
		duration = tonumber(duration) or 4

		local count = #Zyrix._notifications
		local holder = zNew("Frame", {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, 300, 0, 16 + count * 62),
			Size = UDim2.fromOffset(260, 54),
			BackgroundColor3 = ZC.Panel,
			ZIndex = 100,
		}, gui)
		zCorner(holder, 8)
		zNew("UIStroke", {Color = ZC.Accent, Thickness = 1, Transparency = 0.3}, holder)
		zNew("TextLabel", {
			Position = UDim2.new(0, 10, 0, 6),
			Size = UDim2.new(1, -20, 0, 16),
			BackgroundTransparency = 1,
			Text = tostring(title or "Notice"),
			TextColor3 = ZC.Text,
			Font = Enum.Font.GothamBold,
			TextSize = 13,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 101,
		}, holder)
		zNew("TextLabel", {
			Position = UDim2.new(0, 10, 0, 24),
			Size = UDim2.new(1, -20, 0, 24),
			BackgroundTransparency = 1,
			Text = tostring(message or ""),
			TextColor3 = ZC.SubText,
			Font = Enum.Font.Gotham,
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextWrapped = true,
			ZIndex = 101,
		}, holder)

		table.insert(Zyrix._notifications, holder)
		TweenService:Create(holder, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			Position = UDim2.new(1, -16, 0, 16 + count * 62),
		}):Play()

		task.wait(duration)

		local index = table.find(Zyrix._notifications, holder)
		if index then
			table.remove(Zyrix._notifications, index)
		end
		local out = TweenService:Create(holder, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
			Position = UDim2.new(1, 300, 0, holder.Position.Y.Offset),
		})
		out:Play()
		out.Completed:Wait()
		holder:Destroy()
		for i, remaining in ipairs(Zyrix._notifications) do
			if remaining.Parent then
				TweenService:Create(remaining, TweenInfo.new(0.25), {
					Position = UDim2.new(1, -16, 0, 16 + (i - 1) * 62),
				}):Play()
			end
		end
	end)
end

function Zyrix:Launch()
	local gui = Zyrix.ScreenGui
	if gui then
		gui.Enabled = true
	end
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if input.KeyCode == Zyrix._toggleKey and not gameProcessed then
			local currentGui = Zyrix.ScreenGui
			if currentGui then
				currentGui.Enabled = not currentGui.Enabled
			end
		end
	end)
	if Zyrix.Callbacks.OnSuccess then
		pcall(Zyrix.Callbacks.OnSuccess)
	end
end
end -- end of embedded Zyrix fallback

-- MERGED: EndorisFTAP notifications are routed to the main fluxy hub.
-- The embedded Zyrix no longer creates its own window, so its Notify has
-- nothing to display on — forward to the main hub's Zyrix instead.
do
	local origNotify = Zyrix.Notify
	function Zyrix:Notify(title, message, duration, iconType)
		local mainZyrix = genv and genv.Zyrix
		if mainZyrix and mainZyrix ~= Zyrix and mainZyrix.Notify then
			pcall(function() mainZyrix:Notify(title, message, duration, iconType) end)
			return
		end
		pcall(function() origNotify(self, title, message, duration, iconType) end)
	end
end

-- ======================================================
-- Endoris → Zyrix Compatibility Shim
-- Provides the Endoris API on top of Zyrix
-- ======================================================

library = {
	Flags = {},
	_flagSetters = {},
	_dropdownTracker = {},
	_keybindCallbacks = {},
	_keybindModes = {},
	_keybindBypass = {},
	ChangingKeybind = false,
	ScreenGui = nil,
}

do
	local g = (getgenv and getgenv()) or _G
	g.FluxyFTAPLibrary = library
end

local function fixScreenGuiProps(gui)
	-- Ensure the UI appears on top of everything
	gui.DisplayOrder = 999999
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
end

local function findScreenGui()
	-- MERGED: prefer the main hub's own GUI ("ZyrixMainUI") over the key
	-- system / loading screen GUIs, which also have "Zyrix" in the name.
	local candidates = {}
	local function scan(parent)
		if not parent then return end
		for _, gui in ipairs(parent:GetChildren()) do
			if gui:IsA("ScreenGui") and (string.find(gui.Name, "Zyrix") or string.find(gui.Name, "zyrix")) then
				table.insert(candidates, gui)
			end
		end
	end
	scan(game:GetService("CoreGui"))
	local player = game:GetService("Players").LocalPlayer
	scan(player and player:FindFirstChild("PlayerGui"))
	for _, gui in ipairs(candidates) do
		if gui.Name == "ZyrixMainUI" then
			fixScreenGuiProps(gui)
			return gui
		end
	end
	for _, gui in ipairs(candidates) do
		fixScreenGuiProps(gui)
		return gui
	end
	return nil
end

function library:Window(config)
	-- MERGED: EndorisFTAP no longer creates its own window. Every tab it
	-- registers is added straight to the main fluxy hub window (the
	-- top-level `Window` upvalue created earlier in this script), so only
	-- one UI ever loads.
	local window = Window

	if not window or type(window.CreateTab) ~= "function" then
		warn("[fluxy] main hub window unavailable — EndorisFTAP UI skipped")
		local windowWrapper = {}
		local function mkEl()
			return { Set = function() end, SetOptions = function() end, SetDisplay = function() end, Refresh = function() end }
		end
		function windowWrapper:Tab()
			local tabWrapper = {}
			function tabWrapper:Section()
				local sectionWrapper = {}
				for _, m in ipairs({ "Toggle", "Slider", "Dropdown", "Button", "Keybind", "Label" }) do
					sectionWrapper[m] = function() return mkEl() end
				end
				return sectionWrapper
			end
			return tabWrapper
		end
		return windowWrapper
	end

	-- Find the main hub's ScreenGui so Menu Toggle / Menu Scale / keybind
	-- list keep working (the hub GUI is named ZyrixMainUI).
	task.spawn(function()
		for _ = 1, 50 do
			local gui = findScreenGui()
			if gui then
				library.ScreenGui = gui
				break
			end
			task.wait(0.1)
		end
	end)

	local windowWrapper = {}

	function windowWrapper:Tab(tabConfig)
		-- MERGED: every EndorisFTAP tab gets its own DEDICATED hub tab so
		-- the fluxy tabs stay clean and FTAP features are easy to find.
		-- These tab objects were created before Zyrix:Launch(), so their
		-- elements actually render — tabs registered after launch never
		-- appear, which is why the old "FTAP <name>" tabs came up empty.
		local requested = tabConfig and tabConfig.Text or "Tab"
		local routeMap = {
			Main = Tabs.Main,            -- Home
			Target = Tabs.Target,        -- Target tools
			Anti = Tabs.Defense,         -- Protections
			Misc = Tabs.Misc,
			Telekinesis = Tabs.Toy,      -- Toys
			Grab = Tabs.Combat,          -- Combat
			Loop = Tabs.Server,          -- Server loops
			Aura = Tabs.Aura,
			Player = Tabs.Player,        -- Player movement
			Fluxy = Tabs.Combat,         -- Combat extras
			Server = Tabs.Server,
		}
		local tab = routeMap[requested] or Tabs.Misc

		local tabWrapper = {}

		function tabWrapper:Section(sectionConfig)
			local sectionName = sectionConfig.Text or "Section"
			local sectionSide = sectionConfig and sectionConfig.Side
			-- Split the big FTAP Misc/Main tabs: fun & chaos features (Snowball,
			-- Effects, Fun, Explosion, Lag) go to the dedicated Fun tab so
			-- Utility stays focused on tools (Camera, HUD, Bring, Config...).
			local secTab = tab
			if requested == "Misc" or requested == "Main" then
				local funSections = { Effects = true, Fun = true, Explosion = true, Lag = true, Snowball = true }
				if funSections[sectionName] then secTab = Tabs.Fun end
			end
			do
				local sside = sectionSide
				if type(sside) == "string" then sside = string.lower(sside) end
				secTab:CreateSection(sectionName, sside)
			end

			local sectionWrapper = {}

			function sectionWrapper:Toggle(toggleConfig)
				local flag = toggleConfig.Flag
				local defaultVal = toggleConfig.Default or false
				local callback = toggleConfig.Callback or function() end

				if flag then
					library.Flags[flag] = {Value = defaultVal, Callback = callback}
				end

				local toggle = secTab:CreateToggle({
					Name = toggleConfig.Text or "Toggle",
					CurrentValue = defaultVal,
					Side = sectionSide,
					Callback = function(state)
						if flag then library.Flags[flag].Value = state end
						callback(state)
					end,
				})

				if flag then
					library._flagSetters[flag] = function(val)
						if type(val) == "table" then val = val.Value end
						if val == nil then return end
						library.Flags[flag].Value = val
						callback(val)
						if toggle then pcall(function() toggle:Set(val) end) end
					end
					do
						local g = (getgenv and getgenv()) or _G
						if g.FluxyRegisterSetter then
							g.FluxyRegisterSetter(flag, library._flagSetters[flag])
						end
					end
				end

				return toggle
			end

			function sectionWrapper:Slider(sliderConfig)
				local flag = sliderConfig.Flag
				local defaultVal = sliderConfig.Default or 0
				local minVal = sliderConfig.Minimum or 0
				local maxVal = sliderConfig.Maximum or 100
				local valueName = sliderConfig.ValueName or ""
				local callback = sliderConfig.Callback or function() end

				if flag then
					library.Flags[flag] = defaultVal
				end

				local slider = secTab:CreateSlider({
					Name = sliderConfig.Text or "Slider",
					Range = {minVal, maxVal},
					CurrentValue = defaultVal,
					Suffix = valueName,
					Side = sectionSide,
					Callback = function(value)
						if flag then library.Flags[flag] = value end
						do
							local g = (getgenv and getgenv()) or _G
							if flag and g.FluxyRememberValue then
								g.FluxyRememberValue(flag, tonumber(value) or value)
							end
						end
						callback(value)
					end,
				})

				if flag then
					library._flagSetters[flag] = function(val)
						if type(val) == "table" then val = val.Value or val[1] end
						if val == nil then return end
						library.Flags[flag] = val
						callback(val)
						if slider then pcall(function() slider:Set(val) end) end
					end
				end

				return slider
			end

			function sectionWrapper:Dropdown(dropdownConfig)
				local flag = dropdownConfig.Flag
				local options = dropdownConfig.List or {}
				local callback = dropdownConfig.Callback or function() end

				local dropdown = secTab:CreateDropdown({
					Name = dropdownConfig.Text or "Dropdown",
					Options = options,
					Side = sectionSide,
					CurrentOption = dropdownConfig.Default and {dropdownConfig.Default} or {},
					Callback = function(option)
						local val = type(option) == "table" and option[1] or option
						if flag then library.Flags[flag] = val end
						callback(val)
					end,
				})

				if dropdownConfig.Placeholder and dropdown and dropdown.SetDisplay then
					pcall(function() dropdown:SetDisplay(dropdownConfig.Placeholder) end)
				end
				local dropdownWrapper = dropdown or {}

				function dropdownWrapper:Refresh(refreshConfig)
					local newList = refreshConfig and refreshConfig.List or {}
					local g = (getgenv and getgenv()) or _G
					local want = g.FluxyStickyPlayers and (g.FluxyStickyPlayers[flag] or g.FluxyStickyPlayers._last)
					if dropdown and dropdown.SetOptions then
						pcall(function() dropdown:SetOptions(newList) end)
					elseif dropdown and dropdown.Refresh then
						pcall(function() dropdown:Refresh(newList) end)
					elseif dropdown and dropdown.Set then
						pcall(function() dropdown:Set(newList) end)
					end
					-- restore sticky selection after list refresh
					if want and type(newList) == "table" then
						local pick = nil
						for _, entry in ipairs(newList) do
							if tostring(entry):find(want, 1, true) then
								pick = entry
								break
							end
						end
						pick = pick or want
						if dropdown and dropdown.Set then
							pcall(function() dropdown:Set(pick) end)
						elseif dropdown and dropdown.SetDisplay then
							pcall(function() dropdown:SetDisplay(tostring(pick)) end)
						end
					elseif refreshConfig and refreshConfig.Text and dropdown and dropdown.SetDisplay then
						pcall(function() dropdown:SetDisplay(refreshConfig.Text) end)
					end
				end

				if flag then
					library._flagSetters[flag] = function(val)
						if type(val) == "table" then val = val.Value or val[1] end
						if val == nil then return end
						library.Flags[flag] = val
						callback(val)
					end
				end

				return dropdownWrapper
			end

			function sectionWrapper:Button(buttonConfig)
				local button = secTab:CreateButton({
					Name = buttonConfig.Text or "Button",
					Side = sectionSide,
					Callback = buttonConfig.Callback or function() end,
				})
				return button
			end

			function sectionWrapper:Keybind(keybindConfig)
				local flag = keybindConfig.Flag
				local mode = keybindConfig.Mode or "Toggle"
				local defaultKey = keybindConfig.Default or Enum.KeyCode.Unknown
				local callback = keybindConfig.Callback or function() end

				local keyStr = "None"
				if typeof(defaultKey) == "EnumItem" and defaultKey ~= Enum.KeyCode.Unknown then
					keyStr = defaultKey.Name
				elseif type(defaultKey) == "string" and defaultKey ~= "" then
					keyStr = defaultKey
				end

				if flag then
					library.Flags[flag] = {Key = keyStr, Mode = mode}
					library._keybindCallbacks[flag] = callback
					library._keybindModes[flag] = mode
					library._keybindBypass[flag] = keybindConfig.BypassGameProcessed or false
				end

				local keybind = secTab:CreateKeybind({
					Name = keybindConfig.Text or "Keybind",
					CurrentKeybind = keyStr,
					Callback = function(key)
						local keyName = typeof(key) == "EnumItem" and key.Name or tostring(key)
						if flag then library.Flags[flag].Key = keyName end
					end,
				})

				if flag then
					library._flagSetters[flag] = function(val)
						if type(val) == "table" then
							if val.Key then library.Flags[flag].Key = val.Key end
							if val.Mode then library.Flags[flag].Mode = val.Mode end
						end
					end
				end

				return keybind
			end

			function sectionWrapper:Label(labelConfig)
				local labelText = labelConfig.Text or "Label"
				local label
				pcall(function()
					if secTab.CreateLabel then
						label = secTab:CreateLabel(labelText)
					end
				end)
				if not label then
					pcall(function()
						label = secTab:CreateButton({Name = labelText, Callback = function() end})
					end)
				end
				return label
			end

			return sectionWrapper
		end

		return tabWrapper
	end

	return windowWrapper
end

-- Input handling for keybinds (replicating Endoris keybind behavior)
UserInputService.InputBegan:Connect(function(input, gameProcessed)
	if library.ChangingKeybind then return end

	local keyCode = input.KeyCode
	local inputType = input.UserInputType

	for flag, callback in pairs(library._keybindCallbacks) do
		if not gameProcessed or library._keybindBypass[flag] then
			local data = library.Flags[flag]
			if data and data.Key and data.Key ~= "" and data.Key ~= "None" then
				local keyMatch = false
				local codeOk, code = pcall(function() return Enum.KeyCode[data.Key] end)
				if codeOk and code and code ~= Enum.KeyCode.Unknown and code == keyCode then
					keyMatch = true
				end
				if not keyMatch then
					local typeOk, itype = pcall(function() return Enum.UserInputType[data.Key] end)
					if typeOk and itype and itype == inputType then
						keyMatch = true
					end
				end

				if keyMatch then
					local mode = library._keybindModes[flag] or "Toggle"
					if mode == "Hold" then
						callback(true)
					else
						callback()
					end
				end
			end
		end
	end
end)

UserInputService.InputEnded:Connect(function(input)
	local keyCode = input.KeyCode
	local inputType = input.UserInputType

	for flag, callback in pairs(library._keybindCallbacks) do
		local data = library.Flags[flag]
		if data and data.Key and data.Key ~= "" and data.Key ~= "None" then
			local keyMatch = false
			local codeOk, code = pcall(function() return Enum.KeyCode[data.Key] end)
			if codeOk and code and code ~= Enum.KeyCode.Unknown and code == keyCode then
				keyMatch = true
			end
			if not keyMatch then
				local typeOk, itype = pcall(function() return Enum.UserInputType[data.Key] end)
				if typeOk and itype and itype == inputType then
					keyMatch = true
				end
			end

			if keyMatch then
				local mode = library._keybindModes[flag] or "Toggle"
				if mode == "Hold" then
					callback(false)
				end
			end
		end
	end
end)

local function fixSectionAfterRefresh()
	task.delay(0.2, function()
		pcall(function()
			if not library._dropdownTracker then return end
			for _, entry in ipairs(library._dropdownTracker) do
				if entry.sectionFrame and entry.section then
					local sectionFrame = entry.sectionFrame
					local section = entry.section
					local contentH = 0
					local childCount = 0
					for _, child in sectionFrame:GetChildren() do
						if child:IsA("Frame") then
							contentH = contentH + child.Size.Y.Offset
							childCount = childCount + 1
						end
					end
					local layout = sectionFrame:FindFirstChildOfClass("UIListLayout")
					local layoutPadding = layout and layout.Padding.Offset or 0
					local gapsH = math.max(0, childCount - 1) * layoutPadding
					local frameH = 23 + contentH + gapsH + 3
					section.Size = UDim2.new(1, 0, 0, frameH + 6)
					sectionFrame.Size = UDim2.new(1, 0, 0, frameH)
				end
			end
		end)
	end)
end

-- ===== SAFE GAME-OBJECT RESOLUTION =====
-- This script targets a specific game. In other places (e.g. Studio playtests)
-- these ReplicatedStorage objects don't exist, and infinite WaitForChild calls
-- would hang the whole thread before the UI ever loads. Resolve them safely:
-- real objects in the target game, inert no-op stubs everywhere else.
local IS_TARGET_GAME = false
do
	local deadline = os.clock() + 3
	repeat
		if ReplicatedStorage:FindFirstChild("CharacterEvents")
			or ReplicatedStorage:FindFirstChild("GrabEvents")
			or ReplicatedStorage:FindFirstChild("MenuToys") then
			IS_TARGET_GAME = true
			break
		end
		task.wait(0.1)
	until os.clock() >= deadline
end

local StubMT
StubMT = {
	__call = function() return setmetatable({}, StubMT) end,
	__index = function(t, k)
		if type(k) == "number" then return nil end -- ipairs/pairs safety
		if k == "Value" then return false end
		if k == "Name" then return "Stub" end
		local s = setmetatable({}, StubMT)
		rawset(t, k, s)
		return s
	end,
}
local function makeStub()
	return setmetatable({}, StubMT)
end

local function safeGet(parent, name)
	if typeof(parent) ~= "Instance" then return makeStub() end
	local child = parent:FindFirstChild(name)
	if child then return child end
	if IS_TARGET_GAME then
		local found = parent:WaitForChild(name, 10)
		if found then return found end
	end
	return makeStub()
end

