local AntiFeature = {}

function AntiFeature.setupAntiGrabV1()
	isHeldValue.Changed:Connect(function(isBeingHeld)
		if isBeingHeld and Settings.Anti.AntiGrab then
			local hrp = (LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()):WaitForChild("HumanoidRootPart")
			local lastFire = 0
			local conn
			conn = RunService.Heartbeat:Connect(function()
				if isHeldValue.Value then
					local now = tick()
					if now - lastFire < 0.1 then return end
					lastFire = now
					hrp.Velocity = Vector3.new()
					hrp.Anchored = true
					struggleEvent:FireServer(LocalPlayer)
					ragdollRemoteEvent:FireServer(hrp, 0)
				else
					hrp.Velocity = Vector3.new()
					hrp.Anchored = false
					conn:Disconnect()
				end
			end)
		end
	end)
end

function AntiFeature.startStruggleLoop()
	local char = LocalPlayer.Character
	if not char or State.struggleTasks[char] then return end
	State.struggleTasks[char] = true
	task.spawn(function()
		while State.struggleTasks[char] do
			local head = char:FindFirstChild("Head")
			if head and head:FindFirstChild("PartOwner") and isHeldValue.Value then
				pcall(function()
					struggleEvent:FireServer()
					local gce = ReplicatedStorage:FindFirstChild("GameCorrectionEvents")
					if gce then
						local sav = gce:FindFirstChild("StopAllVelocity")
						if sav then sav:FireServer() end
					end
				end)
			else
				State.struggleTasks[char] = nil
				break
			end
			task.wait(0.1)
		end
	end)
end

function AntiFeature.enableAntiGrabSolaris()
	if State.connections.antiGrab then State.connections.antiGrab:Disconnect() end
	local lastCheck = 0
	State.connections.antiGrab = RunService.Heartbeat:Connect(function()
		local now = tick()
		if now - lastCheck < 0.04 then return end
		lastCheck = now
		local char = LocalPlayer.Character
		if char and char:FindFirstChild("Head") then
			local head = char.Head
			if head:FindFirstChild("PartOwner") and isHeldValue.Value then
				AntiFeature.startStruggleLoop()
			end
		end
	end)
end

function AntiFeature.disableAntiGrabSolaris()
	if State.connections.antiGrab then
		State.connections.antiGrab:Disconnect()
		State.connections.antiGrab = nil
	end
	for k in pairs(State.struggleTasks) do
		State.struggleTasks[k] = nil
	end
end

function AntiFeature.breakBlobmanGrab()
	local now = tick()
	if State.antiBlobmanLastBreak and now - State.antiBlobmanLastBreak < 0.15 then return end
	State.antiBlobmanLastBreak = now

	local char = LocalPlayer.Character
	if not char then return end
	local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
	if not hrp then return end
	local myHum = char:FindFirstChildOfClass("Humanoid")

	-- Take network ownership of our root so the grabber loses physics control
	pcall(function() setNetworkOwnerEvent:FireServer(hrp, hrp.CFrame) end)

	-- Break every grab line attached to our parts
	local myParts = {}
	for _, p in ipairs(char:GetDescendants()) do
		if p:IsA("BasePart") then
			myParts[p] = true
			local po = p:FindFirstChild("PartOwner")
			if po and po:IsA("StringValue") and po.Value ~= "" and po.Value ~= LocalPlayer.Name then
				pcall(function() destroyGrabLineEvent:FireServer(p) end)
			end
		end
	end

	-- Force any foreign blobman currently holding us to drop
	for _, obj in ipairs(Workspace:GetDescendants()) do
		if obj:IsA("Model") and obj.Name == "CreatureBlobman" then
			local seat = obj:FindFirstChild("VehicleSeat")
			if seat and (not myHum or seat.Occupant ~= myHum) then
				local scriptObj = obj:FindFirstChild("BlobmanSeatAndOwnerScript", true)
				local dropRemote = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
				if dropRemote then
					for _, side in ipairs({"Left", "Right"}) do
						local detector = obj:FindFirstChild(side .. "Detector")
						if detector then
							for _, w in ipairs(detector:GetChildren()) do
									if w:IsA("Weld") or w:IsA("WeldConstraint") or w:IsA("Motor6D") then
										local other = (w.Part0 == detector) and w.Part1 or w.Part0
										if other and myParts[other] then
											pcall(function() dropRemote:FireServer(detector, other) end)
										end
									end
									end
								end
							end
						end
					end
				end
			end

	-- Struggle + un-ragdoll to shake off the grab
	pcall(function() struggleEvent:FireServer(LocalPlayer) end)
	pcall(function() ragdollRemoteEvent:FireServer(hrp, 0) end)
end

function AntiFeature.enableAntiBlobman()
	Settings.Anti.AntiBlobman = true
	if State.connections.antiBlobmanHeart then return end

	local function hookCharacter(char)
		if not char then return end
		if State.connections.antiBlobmanDesc then
			State.connections.antiBlobmanDesc:Disconnect()
			State.connections.antiBlobmanDesc = nil
		end
		State.connections.antiBlobmanDesc = char.DescendantAdded:Connect(function(child)
			if not Settings.Anti.AntiBlobman then return end
			if child:IsA("StringValue") and child.Name == "PartOwner" and child.Value ~= "" and child.Value ~= LocalPlayer.Name then
				local grabbedPart = child.Parent
				if grabbedPart and grabbedPart:IsA("BasePart") then
						AntiFeature.breakBlobmanGrab()
					end
				end
			end)
	end

	if LocalPlayer.Character then hookCharacter(LocalPlayer.Character) end
	State.connections.antiBlobmanCharAdded = LocalPlayer.CharacterAdded:Connect(hookCharacter)

	-- Backup sweep: catches grabs that started while protection was off
	State.connections.antiBlobmanHeart = RunService.Heartbeat:Connect(function()
		local now = tick()
		if now - (State.antiBlobmanLastSweep or 0) < 0.25 then return end
		State.antiBlobmanLastSweep = now
		if not Settings.Anti.AntiBlobman then return end
		local char = LocalPlayer.Character
		if not char then return end
		local held = isHeldValue and isHeldValue.Value
		if not held then
			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("StringValue") and d.Name == "PartOwner" and d.Value ~= "" and d.Value ~= LocalPlayer.Name then
					held = true
					break
				end
			end
		end
		if held then
			AntiFeature.breakBlobmanGrab()
		end
	end)
end

function AntiFeature.disableAntiBlobman()
	Settings.Anti.AntiBlobman = false
	for _, key in ipairs({"antiBlobmanDesc", "antiBlobmanCharAdded", "antiBlobmanHeart"}) do
		if State.connections[key] then
			State.connections[key]:Disconnect()
			State.connections[key] = nil
		end
	end
end

function AntiFeature.setupAntiExplosion(character)
	local humanoid = character:WaitForChild("Humanoid", 5)
	local hrp = character:WaitForChild("HumanoidRootPart", 5)
	if not humanoid or not hrp then return end
	if antiExplosionConnection then
		antiExplosionConnection:Disconnect()
	end
	antiExplosionConnection = Workspace.ChildAdded:Connect(function(model)
		if not Settings.Anti.AntiExplosion then return end
		local char = LocalPlayer.Character
		local h = char and char:FindFirstChild("Humanoid")
		local r = char and char:FindFirstChild("HumanoidRootPart")
		if not h or not r then return end
		if model:IsA("BasePart") and (model.Position - r.Position).Magnitude <= 20 then
			if h.SeatPart ~= nil then
				r.Anchored = true
				task.wait(0.03)
				r.AssemblyLinearVelocity = Vector3.zero
				r.AssemblyAngularVelocity = Vector3.zero
				r.Anchored = false
			else
				r.Anchored = true
				task.wait()
				h:ChangeState(Enum.HumanoidStateType.Running)
				r.Anchored = false
				h.AutoRotate = true
				for _, limb in ipairs(char:GetDescendants()) do
					if limb:IsA("BasePart") and limb.Name == "RagdollLimbPart" then
						limb.CanCollide = false
					end
				end
			end
		end
	end)
end

