						task.wait(0.05)
					end
					if hrp and hrp.Parent then
						pcall(function() hrp.Anchored = false end)
						if savedCFrame then pcall(function() hrp.CFrame = savedCFrame end) end
					end
				end)
			end
		end)
	else
