local cloneFlingConn = nil

local cloneFlingTargets = {
	["UFO 1"] = function()
		return workspace.Map.AlwaysHereTweenedObjects.InnerUFO.Object.ObjectModel:GetChildren()[16]
	end,
	["UFO 2"] = function()
