							local sp = toy:FindFirstChild("SoundPart")
							if sp then
								local along = (sp.Position - root.Position):Dot(look)
								if along > best then best = along end
							end
						end
					end
					if best > 1 then tipDist = best end
				end
			end)
			if tipDist < baseDist + 0.5 then
				tipDist = baseDist + math.max(1, amount * 0.9)
			end
			return baseDist, tipDist - baseDist, tipDist
		end
