	-- Aggressive network ownership (same style as grabs / auras that work)
	local function traxShip(part)
		if not part or not part.Parent then return false end
		local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
		local ge = ReplicatedStorage:FindFirstChild("GrabEvents")
		local sn = ge and ge:FindFirstChild("SetNetworkOwner")
		if not sn then return false end
		-- Fire multiple times so ownership sticks
		for _ = 1, 4 do
			pcall(function()
				local cf = root and CFrame.lookAt(root.Position, part.Position) or part.CFrame
				sn:FireServer(part, cf)
			end)
		end
		-- Also claim other character parts for stronger control
		local char = part.Parent
		if char then
			for _, name in ipairs({"HumanoidRootPart", "Torso", "UpperTorso", "LowerTorso", "Head"}) do
				local p = char:FindFirstChild(name)
				if p and p:IsA("BasePart") and p ~= part then
					pcall(function()
						sn:FireServer(p, p.CFrame)
					end)
				end
			end
		end
		return true
	end

	local function traxBringToMe(player, root)
		if not player or not player.Character or not root then return false end
		local char = player.Character
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart")
		local hrp = char:FindFirstChild("HumanoidRootPart") or torso
		local humanoid = char:FindFirstChildOfClass("Humanoid")
		if not torso or not humanoid then return false end

		-- Target stand in front of you (dick base / lower front)
		local look = root.CFrame.LookVector
		local bringPos = root.Position + (look * 2.2) + Vector3.new(0, -0.5, 0)

		-- Hard network own
		traxShip(torso)
		if hrp and hrp ~= torso then traxShip(hrp) end

		pcall(function()
			humanoid.PlatformStand = true
			humanoid.Sit = false
			humanoid.WalkSpeed = 0
			torso.AssemblyLinearVelocity = Vector3.zero
			if hrp then hrp.AssemblyLinearVelocity = Vector3.zero end
		end)

		-- Strong pull to you
		local bp = torso:FindFirstChild("TraxAuraBP") or Instance.new("BodyPosition")
		bp.Name = "TraxAuraBP"
		bp.MaxForce = Vector3.new(1e7, 1e7, 1e7)
		bp.P = 50000
		bp.D = 2000
		bp.Position = bringPos
		bp.Parent = torso

		local bv = torso:FindFirstChild("TraxAuraBV") or Instance.new("BodyVelocity")
		bv.Name = "TraxAuraBV"
		bv.MaxForce = Vector3.new(1e7, 1e7, 1e7)
		bv.P = 30000
		bv.Velocity = (bringPos - torso.Position) * 60
		bv.Parent = torso

		-- If we own, snap
		pcall(function()
			local po = torso:FindFirstChild("PartOwner")
			if po and po.Value == LocalPlayer.Name then
				torso.CFrame = CFrame.new(bringPos)
				if hrp then hrp.CFrame = CFrame.new(bringPos) end
			end
		end)

		local dist = (torso.Position - bringPos).Magnitude
		return dist < 6 -- close enough to start trax
	end

	local function traxApplyTo(player, root, oscillation)
		if not player or not player.Character or not root then return false end
		local char = player.Character
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart")
		local humanoid = char:FindFirstChildOfClass("Humanoid")
		local hrp = char:FindFirstChild("HumanoidRootPart") or torso
		if not torso or not humanoid or humanoid.Health <= 0 then return false end

		local user = player.Name

		-- STEP 1: Bring them to you first
		if not traxBrought[user] then
			local closeEnough = traxBringToMe(player, root)
			if closeEnough then
				traxBrought[user] = true
			else
				-- keep pulling until close
				return true
			end
		end

		-- STEP 2: Trax in/out (coco length)
		local baseDist, swing = traxGetDickRange()
		local lookVector = root.CFrame.LookVector
		local origin = root.Position + Vector3.new(0, -1, 0)
		local wave = math.sin(oscillation) * 0.5 + 0.5
		local currentDistance = baseDist + wave * swing
		local targetPosition = origin + (lookVector * currentDistance)
		local targetCF = CFrame.new(targetPosition)

		traxShip(torso)
		if hrp and hrp ~= torso then traxShip(hrp) end

		pcall(function()
			torso.AssemblyLinearVelocity = Vector3.zero
			torso.AssemblyAngularVelocity = Vector3.zero
			if hrp then
				hrp.AssemblyLinearVelocity = Vector3.zero
				hrp.AssemblyAngularVelocity = Vector3.zero
			end
		end)

		local bp = torso:FindFirstChild("TraxAuraBP")
		if not bp then
			bp = Instance.new("BodyPosition")
			bp.Name = "TraxAuraBP"
			bp.Parent = torso
		end
		bp.MaxForce = Vector3.new(1e6, 1e6, 1e6)
		bp.P = 30000
		bp.D = 1500
		bp.Position = targetPosition

		local bv = torso:FindFirstChild("TraxAuraBV")
		if not bv then
			bv = Instance.new("BodyVelocity")
			bv.Name = "TraxAuraBV"
			bv.Parent = torso
		end
		bv.MaxForce = Vector3.new(1e6, 1e6, 1e6)
		bv.P = 20000
		bv.Velocity = (targetPosition - torso.Position) * 40

		local bg = torso:FindFirstChild("TraxAuraBG")
		if not bg then
			bg = Instance.new("BodyGyro")
			bg.Name = "TraxAuraBG"
			bg.Parent = torso
		end
		bg.MaxTorque = Vector3.new(1e6, 1e6, 1e6)
		bg.P = 20000
		bg.D = 500
		bg.CFrame = CFrame.new(torso.Position, origin) * CFrame.Angles(math.rad(90), 0, 0)

		pcall(function()
			humanoid.PlatformStand = true
			humanoid.Sit = false
			humanoid.WalkSpeed = 0
			humanoid.JumpPower = 0
		end)

		pcall(function()
			local po = torso:FindFirstChild("PartOwner")
			if po and po.Value == LocalPlayer.Name then
				torso.CFrame = targetCF
				if hrp then hrp.CFrame = targetCF end
			end
		end)

		return true
	end

local function traxPlayerList()
		local g = (getgenv and getgenv()) or _G
		if g.FluxyBuildPlayerList then
			return g.FluxyBuildPlayerList("name")
		end
		local list = {}
		for _, pl in ipairs(Players:GetPlayers()) do
			if pl ~= LocalPlayer then table.insert(list, pl.Name) end
		end
		table.sort(list)
		if #list == 0 then list = {"None"} end
		return list
	end

	local function traxResolve(name)
		if not name or name == "" or name == "None" then return nil end
		local g = (getgenv and getgenv()) or _G
		if g.FluxyResolvePlayer then
			local p = g.FluxyResolvePlayer(name)
			if p then return p end
		end
		local user = tostring(name):match("%(@%s*(.-)%)") or tostring(name)
		user = user:gsub("^%s+", ""):gsub("%s+$", "")
		local p = Players:FindFirstChild(user)
		if p then return p end
		for _, pl in ipairs(Players:GetPlayers()) do
			if pl.Name == user or pl.DisplayName == user then return pl end
		end
		return nil
	end

