						local count = 0
						for _ in pairs(active) do count = count + 1 end
						for _, player in pairs(Players:GetPlayers()) do
							if count >= traxAuraMaxTargets then break end
							if player == LocalPlayer or active[player] then continue end
							if auraIsFriend and auraIsFriend(player) then continue end
							if isProtectedPlayer and isProtectedPlayer(player.Name) then continue end
							local char = player.Character
							local torso = char and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart"))
