local playerSpinSec = PlayerTab:Section({Text = "Spinbot", Side = "Right"})
local spinbotActive = false
local spinbotConn = nil
local spinbotOrigAutoRotate = nil
local spinbotAngle = 0
playerSpinSec:Toggle({Text = "Spinbot", Flag = "PlayerSpinbot", Default = false, Callback = function(v)
	spinbotActive = v
	if v then
		Settings.Player.spinbotSpeed = Settings.Player.spinbotSpeed or 10000
		spinbotAngle = 0
		local hum = playerGetHumanoid()
		if hum then
			spinbotOrigAutoRotate = hum.AutoRotate
			hum.AutoRotate = false
		end
		spinbotConn = RunService.RenderStepped:Connect(function(dt)
			if not spinbotActive then return end
			local root = playerGetRoot()
			local hum = playerGetHumanoid()
			if root and hum then
				hum.AutoRotate = false
				local velY = root.AssemblyLinearVelocity.Y
				spinbotAngle = spinbotAngle + math.rad(Settings.Player.spinbotSpeed) * dt
				if spinbotAngle > math.pi * 2 then spinbotAngle = spinbotAngle - math.pi * 2 end
				local pos = root.Position
				root.CFrame = CFrame.new(pos) * CFrame.Angles(0, spinbotAngle, 0)
				root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, velY, root.AssemblyLinearVelocity.Z)
			end
		end)
	else
		if spinbotConn then spinbotConn:Disconnect(); spinbotConn = nil end
		spinbotAngle = 0
		local hum = playerGetHumanoid()
		if hum and spinbotOrigAutoRotate ~= nil then
			hum.AutoRotate = spinbotOrigAutoRotate
			spinbotOrigAutoRotate = nil
		end
	end
end})
playerSpinSec:Slider({Text = "Spin Speed", Flag = "PlayerSpinSpeed", Minimum = 1, Maximum = 10000, Default = 10000, ValueName = "speed", Callback = function(v)
	Settings.Player.spinbotSpeed = v
end})




do
	local screenGui = Instance.new("ScreenGui")
	screenGui.Name = "ToolInventory"
	screenGui.Parent = PlayerGui
	screenGui.ResetOnSpawn = false

	local mainFrame = Instance.new("Frame")
	mainFrame.Name = "MainFrame"
	mainFrame.Size = UDim2.new(0, 0, 0, 44)
	mainFrame.Position = UDim2.new(0.5, 0, 1, -30)
	mainFrame.BackgroundColor3 = Color3.new(0, 0, 0)
	mainFrame.BackgroundTransparency = 0.7
	mainFrame.BorderSizePixel = 0
	mainFrame.ClipsDescendants = true
	mainFrame.Visible = false
	mainFrame.Parent = screenGui

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 8)
	corner.Parent = mainFrame

	local toolList = Instance.new("Frame")
	toolList.Name = "ToolList"
	toolList.Size = UDim2.new(1, -12, 1, -12)
	toolList.Position = UDim2.new(0, 6, 0, 6)
	toolList.BackgroundTransparency = 1
	toolList.Parent = mainFrame

	local gridLayout = Instance.new("UIGridLayout")
	gridLayout.Parent = toolList
	gridLayout.CellSize = UDim2.new(0, 28, 0, 28)
	gridLayout.CellPadding = UDim2.new(0, 8, 0, 8)
	gridLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	gridLayout.VerticalAlignment = Enum.VerticalAlignment.Center
	gridLayout.FillDirectionMaxCells = 10

	local scoToolSlots = {}
	local scoMAX_SLOTS = 10

	local function scoUpdateFrameSize(toolCount)
		if toolCount == 0 or not Settings.Misc.toyList then
			mainFrame.Visible = false
			return
		end
		mainFrame.Visible = true
		local iconSize = 28
		local padding = 8
		local margins = 12
		local displayCount = math.min(toolCount, scoMAX_SLOTS)
		local maxWidth = 400
		local itemsPerRow = math.floor((maxWidth - margins) / (iconSize + padding))
		if itemsPerRow < 1 then itemsPerRow = 1 end
		local rows = math.ceil(displayCount / itemsPerRow)
		local totalWidth
		if rows == 1 then
			totalWidth = (displayCount * iconSize) + ((displayCount - 1) * padding) + margins
		else
			totalWidth = (itemsPerRow * iconSize) + ((itemsPerRow - 1) * padding) + margins
			if totalWidth > maxWidth then totalWidth = maxWidth end
		end
		local totalHeight = (rows * iconSize) + ((rows - 1) * padding) + margins
		gridLayout.CellSize = UDim2.new(0, iconSize, 0, iconSize)
		gridLayout.CellPadding = UDim2.new(0, padding, 0, padding)
		local tweenInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TweenService:Create(mainFrame, tweenInfo, {
			Size = UDim2.new(0, totalWidth, 0, totalHeight),
			Position = UDim2.new(0.5, -totalWidth/2, 1, -(totalHeight + 6))
		}):Play()
	end

	local function scoIsToolEquipped(toolName)
		local character = LocalPlayer.Character
		if character then
			local equipped = character:FindFirstChild(toolName)
			if equipped and equipped:IsA("Tool") then return true end
		end
		return false
	end

	local function scoUpdateHighlight()
		for _, button in pairs(toolList:GetChildren()) do
			if button:IsA("ImageButton") then
				local isEquipped = scoIsToolEquipped(button.Name)
				if isEquipped then
					button.BackgroundColor3 = Color3.new(0.6, 0.6, 0.6)
					button.BackgroundTransparency = 0.2
					button.BorderSizePixel = 2
					button.BorderColor3 = Color3.new(1, 1, 1)
				else
					button.BackgroundColor3 = Color3.new(0.3, 0.3, 0.3)
					button.BackgroundTransparency = 0.5
					button.BorderSizePixel = 2
					button.BorderColor3 = Color3.new(0.2, 0.2, 0.2)
				end
			end
		end
	end

	local function scoToggleToolBySlot(slotNumber)
		if slotNumber < 1 or slotNumber > scoMAX_SLOTS then return end
		local tool = scoToolSlots[slotNumber]
		if not tool then return end
		local character = LocalPlayer.Character
		local backpack = LocalPlayer.Backpack
		if not character or not backpack then return end
		local equipped = character:FindFirstChild(tool.Name)
		if equipped then
			equipped.Parent = backpack
			scoUpdateHighlight()
			return
		end
		local target = backpack:FindFirstChild(tool.Name)
		if target then
			target.Parent = character
			scoUpdateHighlight()
		end
	end

	local function scoCreateToolButton(tool, slotNumber)
		local button = Instance.new("ImageButton")
		button.Name = tool.Name
		button.Size = UDim2.new(0, 28, 0, 28)
		button.BackgroundColor3 = Color3.new(0.3, 0.3, 0.3)
		button.BackgroundTransparency = 0.5
		button.BorderSizePixel = 2
		button.BorderColor3 = Color3.new(0.2, 0.2, 0.2)
		button.AutoButtonColor = false

		local btnCorner = Instance.new("UICorner")
		btnCorner.CornerRadius = UDim.new(0, 4)
		btnCorner.Parent = button

		local icon = Instance.new("ImageLabel")
		icon.Name = "Icon"
		icon.Size = UDim2.new(0, 20, 0, 20)
		icon.Position = UDim2.new(0.5, -10, 0.25, 0)
		icon.BackgroundTransparency = 1
		if tool:FindFirstChild("Handle") then
			local handle = tool.Handle
			if handle:IsA("BasePart") and handle:FindFirstChild("Texture") then
				icon.Image = handle.Texture or "rbxassetid://13115827754"
			else
				icon.Image = "rbxassetid://13115827754"
			end
		else
			icon.Image = "rbxassetid://13115827754"
		end
		icon.Parent = button

		local slotLabel = Instance.new("TextLabel")
		slotLabel.Name = "SlotLabel"
		slotLabel.Size = UDim2.new(0, 10, 0, 10)
		slotLabel.Position = UDim2.new(0, 2, 0, 2)
		slotLabel.BackgroundTransparency = 1
		slotLabel.Text = tostring(slotNumber)
		slotLabel.TextColor3 = Color3.new(1, 1, 1)
		slotLabel.TextScaled = true
		slotLabel.Font = Enum.Font.GothamBold
		slotLabel.TextXAlignment = Enum.TextXAlignment.Left
		slotLabel.TextYAlignment = Enum.TextYAlignment.Top
		slotLabel.Parent = button

		local label = Instance.new("TextLabel")
		label.Name = "Label"
		label.Size = UDim2.new(1, 0, 0, 10)
		label.Position = UDim2.new(0, 0, 0.65, 0)
		label.BackgroundTransparency = 1
		label.Text = tool.Name
		label.TextColor3 = Color3.new(1, 1, 1)
		label.TextScaled = true
		label.Font = Enum.Font.GothamBold
		label.Parent = button

		button.MouseEnter:Connect(function()
			local isEq = scoIsToolEquipped(button.Name)
			local ti = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			if isEq then
				TweenService:Create(button, ti, { Size = UDim2.new(0, 32, 0, 32), BackgroundTransparency = 0.1 }):Play()
			else
				TweenService:Create(button, ti, { Size = UDim2.new(0, 32, 0, 32), BackgroundTransparency = 0.2 }):Play()
			end
		end)

		button.MouseLeave:Connect(function()
			local isEq = scoIsToolEquipped(button.Name)
			local ti = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			if isEq then
				TweenService:Create(button, ti, { Size = UDim2.new(0, 28, 0, 28), BackgroundTransparency = 0.2 }):Play()
			else
				TweenService:Create(button, ti, { Size = UDim2.new(0, 28, 0, 28), BackgroundTransparency = 0.5 }):Play()
			end
		end)

		button.MouseButton1Down:Connect(function()
			local ti = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			TweenService:Create(button, ti, { Size = UDim2.new(0, 24, 0, 24), BackgroundTransparency = 0.3 }):Play()
		end)

		button.MouseButton1Up:Connect(function()
			local ti = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			TweenService:Create(button, ti, { Size = UDim2.new(0, 28, 0, 28), BackgroundTransparency = 0.2 }):Play()
		end)

		button.MouseButton1Click:Connect(function()
			scoToggleToolBySlot(slotNumber)
		end)

		return button
	end

	local function scoUpdateInventory()
		for _, child in pairs(toolList:GetChildren()) do
			if child:IsA("ImageButton") then child:Destroy() end
		end
		scoToolSlots = {}
		local tools = {}
		local character = LocalPlayer.Character
		local backpack = LocalPlayer.Backpack
		if backpack then
			for _, child in pairs(backpack:GetChildren()) do
				if child:IsA("Tool") then table.insert(tools, child) end
			end
		end
		if character then
			for _, child in pairs(character:GetChildren()) do
				if child:IsA("Tool") then
					local exists = false
					for _, tool in pairs(tools) do
						if tool.Name == child.Name then exists = true break end
					end
					if not exists then table.insert(tools, child) end
				end
			end
		end
		local slotNumber = 1
		for _, tool in pairs(tools) do
			if slotNumber <= scoMAX_SLOTS then
				scoToolSlots[slotNumber] = tool
				local button = scoCreateToolButton(tool, slotNumber)
				button.Parent = toolList
				slotNumber = slotNumber + 1
			end
		end
		scoUpdateFrameSize(#scoToolSlots)
		scoUpdateHighlight()
	end

	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then return end
		local gui = PlayerGui:FindFirstChild("ToolInventory")
		if not gui then return end
		local mf = gui:FindFirstChild("MainFrame")
		if not mf or not mf.Visible then return end
		local keyMap = {
			[Enum.KeyCode.One] = 1, [Enum.KeyCode.Two] = 2, [Enum.KeyCode.Three] = 3,
			[Enum.KeyCode.Four] = 4, [Enum.KeyCode.Five] = 5, [Enum.KeyCode.Six] = 6,
			[Enum.KeyCode.Seven] = 7, [Enum.KeyCode.Eight] = 8, [Enum.KeyCode.Nine] = 9,
			[Enum.KeyCode.Zero] = 10
		}
		local slotNumber = keyMap[input.KeyCode]
		if slotNumber then scoToggleToolBySlot(slotNumber) end
	end)

	local function scoSetupCharacter(char)
		if char then
			char.ChildAdded:Connect(scoUpdateInventory)
			char.ChildRemoved:Connect(scoUpdateInventory)
			scoUpdateInventory()
		end
	end

	LocalPlayer.CharacterAdded:Connect(scoSetupCharacter)
	LocalPlayer.Backpack.ChildAdded:Connect(scoUpdateInventory)
	LocalPlayer.Backpack.ChildRemoved:Connect(scoUpdateInventory)

	if LocalPlayer.Character then
		scoSetupCharacter(LocalPlayer.Character)
	else
		LocalPlayer.CharacterAdded:Connect(scoSetupCharacter)
	end
	scoUpdateInventory()
	Settings.Misc.refreshToolList = scoUpdateInventory

	RunService.Heartbeat:Connect(function()
		scoUpdateHighlight()
	end)
end




do
	local droActive = false
	local droConnections = {}

	local function droCreateTool()
		local t = Instance.new("Tool")
		t.Name = "Jerk Off"
		t.RequiresHandle = false
		t.Parent = LocalPlayer.Backpack
		return t
	end

	local function droPlayAnim(id, t1, t2, id2)
		local char = LocalPlayer.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not hum then return end

		local a = Instance.new("Animation")
		a.AnimationId = "rbxassetid://" .. id
		local tr = hum:LoadAnimation(a)

		droConnections[id2] = RunService.RenderStepped:Connect(function()
			if droActive then
				if tr.TimePosition >= t2 or tr.IsPlaying == false then
					tr:Play()
					tr.TimePosition = t1
				end
			else
				tr:Stop()
			end
		end)

		tr:Play()
		tr.TimePosition = t1
	end

	local function droStart()
		droActive = true
		droPlayAnim("72042024", 0.5, 0.9, 1)
		droPlayAnim("168268306", 1, 1.001, 2)
	end

	local function droStop()
		droActive = false
		for i, v in pairs(droConnections) do
			v:Disconnect()
		end
		droConnections = {}
	end

	LocalPlayer.CharacterAdded:Connect(function()
		local old = LocalPlayer.Backpack:FindFirstChild("Jerk Off")
		if old then old:Destroy() end
		local nt = droCreateTool()
		nt.Equipped:Connect(droStart)
		nt.Unequipped:Connect(droStop)
	end)

	local st = droCreateTool()
	st.Equipped:Connect(droStart)
	st.Unequipped:Connect(droStop)
end




do
	local TelekinesisFeature = {}
	TelekinesisFeature.activeItems = {}
	TelekinesisFeature.spawnConn = nil
	TelekinesisFeature.auraConn = nil
	-- the only objects the SetNetwork system works on (spawn menu object lists)
	-- NOTE: this MUST live on the TelekinesisFeature table created in this do-block.
	-- It was previously assigned in a different scope, so it was nil here and the
	-- grab-aura scan errored, killing the whole telekinesis movement loop.
	TelekinesisFeature.NETWORKABLE = {
		PalletLightBrown = true, AnvilGray = true, BombMissile = true, Chest = true,
		DiceBig = true, Hoop = true, PaperPlane = true, Airhorn = true,
		BookManyPages = true, BookNormal = true, BucketPaint = true, CouchDarkGray = true,
		FoodHotSauce = true, InstrumentBrassBugle = true, InstrumentGuitarAcoustic = true,
		InstrumentGuitarViolin = true, InstrumentWoodwindOcarina = true, LadderLightBrown = true,
		OvenMicrowaveWhite = true, TeapotUtah = true, Bear = true, Frog = true, Tiger = true,
	}
	-- missiles we recently fired - the grab aura must NOT recapture these
	-- mid-flight or the shots stall and drop behind the player
	TelekinesisFeature.firedCooldown = {}
	local GE = ReplicatedStorage:WaitForChild("GrabEvents")
	local SetNetworkOwner = GE:WaitForChild("SetNetworkOwner")
	local CreateGrabLine = GE:WaitForChild("CreateGrabLine")
	local DestroyGrabLine = GE:WaitForChild("DestroyGrabLine")

	function TelekinesisFeature.getDrivePart(model)
		local main = model:FindFirstChild("Main")
		if main then return main end
		local sp = model:FindFirstChild("SoundPart")
		if sp then return sp end
		return model:FindFirstChildWhichIsA("BasePart")
	end

	function TelekinesisFeature.isFloorThing(inst)
		-- the map floor is a ton of parts named "Grass" - never grab or network those
		if not inst then return true end
		local n = string.lower(inst.Name)
		if n == "grass" or n == "floor" or n == "ground" then return true end
		return false
	end

	function TelekinesisFeature.preparePart(model)
		local drivePart = TelekinesisFeature.getDrivePart(model)
		if not drivePart then return false end
		local myChar = LocalPlayer.Character
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
		if not myRoot then return false end

		-- no teleporting needed: pass the part's own CFrame so the server gives US ownership of the object
		-- (teleporting to every object is what caused the lag and the "it networks me" bug)
		local seen = {}
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") and part.Parent then
				local asmRoot = part.AssemblyRootPart or part
				if not seen[asmRoot] then
					seen[asmRoot] = true
					pcall(function() SetNetworkOwner:FireServer(part, part.CFrame) end)
				end
			end
		end
		task.wait(0.05)
		return true
	end

	function TelekinesisFeature.getNearbyGrabPart(model)
		local dp = TelekinesisFeature.getDrivePart(model)
		if not dp or not dp.Parent then return nil, nil end
		local halfSize = dp.Size / 2
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr ~= LocalPlayer then
				local plrFolder = Workspace:FindFirstChild(plr.Name)
				if plrFolder then
					local gpFolder = plrFolder:FindFirstChild("GrabParts")
					if gpFolder then
						for _, gp in ipairs(gpFolder:GetChildren()) do
							if gp:IsA("BasePart") and gp.Name == "GrabPart" and gp.Parent then
								local rel = dp.CFrame:PointToObjectSpace(gp.Position)
								if math.abs(rel.X) <= halfSize.X + 1
									and math.abs(rel.Y) <= halfSize.Y + 1
									and math.abs(rel.Z) <= halfSize.Z + 1 then
									return gp, plr
								end
							end
						end
					end
				end
			end
		end
		return nil, nil
	end

	function TelekinesisFeature.startOrbit(model, skipPrepare)
		if TelekinesisFeature.activeItems[model] then return end
		-- never re-capture a missile we just fired - let it fly away
		local firedAt = TelekinesisFeature.firedCooldown[model]
		if firedAt and tick() - firedAt < 3 then return end
		if TelekinesisFeature.isFloorThing(model) then return end
		local grabPart = TelekinesisFeature.getNearbyGrabPart(model)
		if grabPart then return end
		if not skipPrepare then
			local ok = TelekinesisFeature.preparePart(model)
			if not ok then return end
		end
		local drivePart = TelekinesisFeature.getDrivePart(model)
		if drivePart then
			if drivePart.Anchored then
				drivePart.Anchored = false
			end

			local bp = drivePart:FindFirstChildOfClass("BodyPosition")
			if not bp then
				bp = Instance.new("BodyPosition")
				bp.MaxForce = Vector3.new(5e18, 5e18, 5e18)
				bp.D = 1000
				bp.P = 50000
				bp.Parent = drivePart
			end

			local bg = drivePart:FindFirstChildOfClass("BodyGyro")
			if not bg then
				bg = Instance.new("BodyGyro")
				bg.MaxTorque = Vector3.new(5e18, 5e18, 5e18)
				bg.D = 1000
				bg.P = 50000
				bg.Parent = drivePart
			end

			TelekinesisFeature.activeItems[model] = {
				drivePart = drivePart,
				bp = bp,
				bg = bg,
			}
		else
			TelekinesisFeature.activeItems[model] = {drivePart = nil, bp = nil, bg = nil}
		end

		-- spawn the object right on the player's HumanoidRootPart so it comes to you
		-- instead of sitting far away where other people can grab it
		task.spawn(function()
			task.wait(0.25) -- wait for network ownership to replicate to us
			local data = TelekinesisFeature.activeItems[model]
			if not data then return end
			local dp = data.drivePart
			if not dp or not dp.Parent then return end
			local myChar = LocalPlayer.Character
			local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if not myRoot then return end
			if (dp.Position - myRoot.Position).Magnitude > 25 then
				local offset = Vector3.new(math.random(-6, 6), 4 + math.random(0, 5), math.random(-6, 6))
				pcall(function() model:PivotTo(CFrame.new(myRoot.Position + offset)) end)
			end
		end)
	end

	function TelekinesisFeature.stopOrbit(model)
		local data = TelekinesisFeature.activeItems[model]
		TelekinesisFeature.activeItems[model] = nil
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") then
				part.CanCollide = true
			end
		end
		local dp = data and data.drivePart
		if dp and dp.Parent then
			pcall(function()
				dp.Anchored = false
				dp.AssemblyLinearVelocity = Vector3.zero
				dp.AssemblyAngularVelocity = Vector3.zero
			end)
		end
		if data and data.bp then pcall(function() data.bp:Destroy() end) end
		if data and data.bg then pcall(function() data.bg:Destroy() end) end
	end

	function TelekinesisFeature.stopAll()
		for model, data in pairs(TelekinesisFeature.activeItems) do
			if model and model.Parent then
				for _, part in ipairs(model:GetDescendants()) do
					if part:IsA("BasePart") then
						part.CanCollide = true
					end
				end
				local dp = data and data.drivePart
				if dp and dp.Parent then
					pcall(function()
						dp.Anchored = false
						dp.AssemblyLinearVelocity = Vector3.zero
						dp.AssemblyAngularVelocity = Vector3.zero
					end)
				end
				if data.bp then pcall(function() data.bp:Destroy() end) end
				if data.bg then pcall(function() data.bg:Destroy() end) end
			end
		end
		TelekinesisFeature.activeItems = {}
		if TelekinesisFeature.spawnConn then TelekinesisFeature.spawnConn:Disconnect() TelekinesisFeature.spawnConn = nil end
		if TelekinesisFeature.auraConn then pcall(function() task.cancel(TelekinesisFeature.auraConn) end) TelekinesisFeature.auraConn = nil end
	end

	function TelekinesisFeature.spawnToy(toyName)
		local myChar = LocalPlayer.Character
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
		if not myRoot then return end
		local SpawnedInToys = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		if not SpawnedInToys then return end
		local connection
		connection = SpawnedInToys.ChildAdded:Connect(function(child)
			if child.Name == toyName then
				connection:Disconnect()
				task.wait(0.3)
				TelekinesisFeature.startOrbit(child)
			end
		end)
		local spawnCFrame = myRoot.CFrame * CFrame.new(0, 0, -5)
		pcall(function() SpawnToyRF:InvokeServer(toyName, spawnCFrame, Vector3.new(0, 0, 0)) end)
		task.delay(5, function() pcall(function() connection:Disconnect() end) end)
	end

	function TelekinesisFeature.networkAll()
		local myChar = LocalPlayer.Character
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
		if not myRoot then return 0 end
		local grabbed = 0
		local maxObjects = Settings.Telekinesis.networkMax or 25
		local function tryGrab(model)
			if grabbed >= maxObjects then return end
			if not model or not model.Parent then return end
			if TelekinesisFeature.isFloorThing(model) then return end
			if TelekinesisFeature.activeItems[model] then return end
			local dp = TelekinesisFeature.getDrivePart(model)
			if not dp or not dp.Parent then return end
			-- no teleport: pass the part's own CFrame so ownership transfers to us
			local seen = {}
			for _, part in ipairs(model:GetDescendants()) do
				if part:IsA("BasePart") and part.Parent then
					local asmRoot = part.AssemblyRootPart or part
					if not seen[asmRoot] then
						seen[asmRoot] = true
						pcall(function() SetNetworkOwner:FireServer(part, part.CFrame) end)
					end
				end
			end
			pcall(function() CreateGrabLine:FireServer(dp, Vector3.zero, dp.Position, false) end)
			pcall(function() DestroyGrabLine:FireServer(dp) end)
			TelekinesisFeature.startOrbit(model, true)
			grabbed = grabbed + 1
		end
		for _, plr in ipairs(Players:GetPlayers()) do
			local folder = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
			if folder then
				for _, child in ipairs(folder:GetChildren()) do
					tryGrab(child)
				end
			end
		end
		local plotItems = Workspace:FindFirstChild("PlotItems")
		if plotItems then
			for _, d in ipairs(plotItems:GetDescendants()) do
				if d:IsA("Model") then
					tryGrab(d)
				end
			end
		end
		return grabbed
	end

	function TelekinesisFeature.grabNetworked()
		local grabbed = 0
		local function tryGrab(model)
			if not model or not model.Parent then return end
			if TelekinesisFeature.isFloorThing(model) then return end
			if TelekinesisFeature.activeItems[model] then return end
			local dp = TelekinesisFeature.getDrivePart(model)
			if not dp or not dp.Parent then return end
			TelekinesisFeature.startOrbit(model, true)
			grabbed = grabbed + 1
		end
		for _, plr in ipairs(Players:GetPlayers()) do
			local folder = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
			if folder then
				for _, child in ipairs(folder:GetChildren()) do
					tryGrab(child)
				end
			end
		end
		local plotItems = Workspace:FindFirstChild("PlotItems")
		if plotItems then
			for _, d in ipairs(plotItems:GetDescendants()) do
				if d:IsA("Model") then
					tryGrab(d)
				end
			end
		end
		return grabbed
	end

	function TelekinesisFeature.shootOrbital()
		local myChar = LocalPlayer.Character
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
		if not myRoot then return end
		if TelekinesisFeature.orbitalFiring then return end
		local cam = Workspace.CurrentCamera
		local targetPos
		if cam then
			local rp = RaycastParams.new()
			rp.FilterType = Enum.RaycastFilterType.Exclude
			local filter = {}
			local ch = LocalPlayer.Character
			if ch then table.insert(filter, ch) end
			-- exclude our own orbiting objects so the ray can't hit our
			-- missile battery and make the shots fly backwards
			for model in pairs(TelekinesisFeature.activeItems) do
				if model and model.Parent then table.insert(filter, model) end
			end
			rp.FilterDescendantsInstances = filter
			-- AIM FROM THE PLAYER, NOT THE CAMERA. A zoomed-out camera floats
			-- behind your back, so casting from the camera made the missiles
			-- drop behind you. Casting from the player along the camera's look
			-- direction always fires where you are actually looking.
			local origin = myRoot.Position + Vector3.new(0, 3, 0)
			local lookDir = cam.CFrame.LookVector
			local result = Workspace:Raycast(origin, lookDir * 2000, rp)
			if result then
				targetPos = result.Position
			else
				targetPos = origin + lookDir * 1000
			end
		else
			targetPos = (myRoot.CFrame * CFrame.new(0, 0, -60)).Position
		end
		TelekinesisFeature.orbitalFiring = true
		task.spawn(function()
			-- gather every active object so we can fire them ONE at a time (barrage)
			local shots = {}
			for model, data in pairs(TelekinesisFeature.activeItems) do
				local dp = data.drivePart
				if not dp or not dp.Parent then
					dp = (model.Parent and TelekinesisFeature.getDrivePart(model)) or nil
				end
				if dp and dp.Parent then
					table.insert(shots, {model = model, data = data, dp = dp})
				end
			end
			-- the missile closest to the player fires first (front of the battery)
			table.sort(shots, function(a, b)
				return (a.dp.Position - myRoot.Position).Magnitude < (b.dp.Position - myRoot.Position).Magnitude
			end)
			-- prune stale fired-missile entries so the table doesn't grow forever
			for m, t in pairs(TelekinesisFeature.firedCooldown) do
				if not m or not m.Parent or tick() - t > 10 then
					TelekinesisFeature.firedCooldown[m] = nil
				end
			end
			-- take network ownership of every missile FIRST so the server obeys
			-- our velocity - otherwise the shots just drop into the void.
			-- network EVERY part of the model (same pattern as the object aura),
			-- not just the drive part, so the whole assembly obeys our launch
			for _, shot in ipairs(shots) do
				local seen = {}
				for _, part in ipairs(shot.model:GetDescendants()) do
					if part:IsA("BasePart") and part.Parent then
						local asmRoot = part.AssemblyRootPart or part
						if not seen[asmRoot] then
							seen[asmRoot] = true
							pcall(function() SetNetworkOwner:FireServer(part, part.CFrame) end)
						end
					end
				end
			end
			if #shots > 0 then task.wait(0.35) end -- let ownership replicate before firing
			for _, shot in ipairs(shots) do
				if not Settings.Telekinesis.orbitalStrike then break end
				local dp = shot.dp
				if dp and dp.Parent then
					local model = shot.model
					local data = shot.data
					-- re-assert ownership right before launch so it can't be stolen back
					pcall(function() SetNetworkOwner:FireServer(dp, dp.CFrame) end)
					TelekinesisFeature.activeItems[model] = nil
					-- blacklist the missile so the grab aura can't snatch it back
					-- mid-flight (that's what made the shots stall behind you)
					TelekinesisFeature.firedCooldown[model] = tick()
					if data.bp then pcall(function() data.bp:Destroy() end) end
					if data.bg then pcall(function() data.bg:Destroy() end) end
					-- kill ANY leftover hold movers on EVERY part of the missile
					-- (not just the drive part), unanchor everything, and collect
					-- every assembly root - stale movers on welded or loose parts
					-- are what made the objects hover and drop behind you
					local asmRoots = {}
					for _, part in ipairs(model:GetDescendants()) do
						if part:IsA("BasePart") and part.Parent then
							for _, c in ipairs(part:GetChildren()) do
								if c:IsA("BodyPosition") or c:IsA("BodyGyro") or c:IsA("BodyVelocity") then
									pcall(function() c:Destroy() end)
								end
							end
							part.Anchored = false
							asmRoots[part.AssemblyRootPart or part] = true
						end
					end
					if dp.Parent then asmRoots[dp.AssemblyRootPart or dp] = true end
					-- glowing fire trail so the barrage looks cool
					pcall(function()
						if not dp:FindFirstChild("OrbitalTrail") then
							local a0 = Instance.new("Attachment")
							a0.Name = "OrbitalA0"
							a0.Position = Vector3.new(0, dp.Size.Y * 0.5, 0)
							a0.Parent = dp
							local a1 = Instance.new("Attachment")
							a1.Name = "OrbitalA1"
							a1.Position = Vector3.new(0, -dp.Size.Y * 0.5, 0)
							a1.Parent = dp
							local trail = Instance.new("Trail")
							trail.Name = "OrbitalTrail"
							trail.Attachment0 = a0
							trail.Attachment1 = a1
							trail.Lifetime = 0.35
							trail.MinLength = 0.1
							trail.WidthScale = NumberSequence.new(1, 0.2)
							trail.Color = ColorSequence.new(Color3.fromRGB(255, 170, 0), Color3.fromRGB(255, 0, 0))
							trail.Transparency = NumberSequence.new(0.2, 1)
							trail.LightEmission = 1
							trail.FaceCamera = true
							trail.Parent = dp
						end
					end)
					-- tiny random spread so the barrage fans out naturally
					local spread = Vector3.new(
						(math.random() - 0.5) * 4,
						(math.random() - 0.5) * 4,
						(math.random() - 0.5) * 4
					)
					local dir = (targetPos + spread) - dp.Position
					if dir.Magnitude > 0.1 then
						dir = dir.Unit
					else
						dir = Vector3.new(0, -1, 0)
					end
					-- launch EVERY assembly in the missile (welded clusters and
					-- loose parts alike) - pushing only the drive part's assembly
					-- left the rest of the object behind to drop on you
					local spin = Vector3.new(math.random(-40, 40), math.random(-40, 40), math.random(-40, 40))
					for asmRoot in pairs(asmRoots) do
						asmRoot.AssemblyLinearVelocity = dir * 700
						asmRoot.AssemblyAngularVelocity = spin
						-- back the launch up with a BodyVelocity that keeps pushing
						-- every frame for a second (same trick the working flings
						-- use). A one-shot velocity can get eaten while ownership
						-- is still replicating; the BodyVelocity guarantees flight
						pcall(function()
							local bv = Instance.new("BodyVelocity")
							bv.Name = "OrbitalLaunchBV"
							bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
							bv.Velocity = dir * 700
							bv.Parent = asmRoot
							game:GetService("Debris"):AddItem(bv, 1)
							local bav = Instance.new("BodyAngularVelocity")
							bav.Name = "OrbitalLaunchBAV"
							bav.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
							bav.AngularVelocity = spin
							bav.Parent = asmRoot
							game:GetService("Debris"):AddItem(bav, 1)
						end)
					end
				end
				task.wait(0.12)
			end
			TelekinesisFeature.orbitalFiring = false
		end)
	end

	function TelekinesisFeature.runAura()
		if TelekinesisFeature.auraConn then
			-- if the old loop thread already died, clear it so we can restart
			pcall(function()
				if coroutine.status(TelekinesisFeature.auraConn) == "dead" then
					TelekinesisFeature.auraConn = nil
				end
			end)
		end
		if TelekinesisFeature.auraConn then return end
		TelekinesisFeature.auraConn = task.spawn(function()
			local angle = 0
			local lastTime = tick()
			local scanTick = 0
			local savedCF = nil
			local nukeMountainPos = nil
			local nukeMountainRef = nil
			local nukeMountainScan = 0
			local protectFlingCd = {}
			local grabAuraScan = 0
			local grabCheckScan = 0
			while Settings.Telekinesis.Enabled do
				task.wait(1e-10)
				local now = tick()
				local dt = math.max(now - lastTime, 0.001)
				lastTime = now

				if now - scanTick > 0.1 then
					scanTick = now
				end

				local myChar = LocalPlayer.Character
				local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
				if not myRoot then continue end

				local centerPart = Settings.Telekinesis.CustomMainPart
				if centerPart and centerPart.Parent then
					myRoot = centerPart
				end

				-- Grab Aura: automatically grab any object inside the aura radius,
				-- no manual grabbing needed - they get added to the orbit / tornado / orbital strike
				if Settings.Telekinesis.grabAura and now - grabAuraScan > 0.25 then
					grabAuraScan = now
					local auraR = Settings.Telekinesis.grabAuraRadius or 40
					local maxObj = Settings.Telekinesis.networkMax or 25
					local curCount = 0
					for _ in pairs(TelekinesisFeature.activeItems) do curCount = curCount + 1 end
					if curCount < maxObj then
						local newGrabs = 0
						local function tryAuraGrab(model)
							if newGrabs >= 5 then return end -- smooth the remote traffic, grab a few per scan
							if not model or not model.Parent then return end
							-- skip missiles we just fired so they can fly away
							local firedAt = TelekinesisFeature.firedCooldown[model]
							if firedAt and tick() - firedAt < 3 then return end
							if TelekinesisFeature.isFloorThing(model) then return end
							if TelekinesisFeature.activeItems[model] then return end
							local dp = TelekinesisFeature.getDrivePart(model)
							if not dp or not dp.Parent then return end
							-- ONLY the objects the SetNetwork system lists (Pallets / Other /
							-- NOT New / Large Animals spawn menu objects). Skip anything else.
							local netTable = TelekinesisFeature.NETWORKABLE
							if not netTable or not netTable[model.Name] then return end
							if (dp.Position - myRoot.Position).Magnitude > auraR then return end
							local po = dp:FindFirstChild("PartOwner")
							if not po or po.Value ~= LocalPlayer.Name then
								-- NETWORK the object to us first: pass the part's own CFrame so
								-- ownership transfers to us without any teleporting
								local seen = {}
								for _, part in ipairs(model:GetDescendants()) do
									if part:IsA("BasePart") and part.Parent then
										local asmRoot = part.AssemblyRootPart or part
										if not seen[asmRoot] then
											seen[asmRoot] = true
											pcall(function() SetNetworkOwner:FireServer(part, part.CFrame) end)
										end
									end
								end
								pcall(function() CreateGrabLine:FireServer(dp, Vector3.zero, dp.Position, false) end)
								pcall(function() DestroyGrabLine:FireServer(dp) end)
							end
							TelekinesisFeature.startOrbit(model, true)
							newGrabs = newGrabs + 1
						end
						for _, plr in ipairs(Players:GetPlayers()) do
							local folder = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
							if folder then
								-- scan descendants so models inside category folders
								-- (Pallets / Other / NOT New / Large Animals) are found too
								for _, d in ipairs(folder:GetDescendants()) do
									if d:IsA("Model") then
										tryAuraGrab(d)
									end
								end
							end
						end
						local plotItems = Workspace:FindFirstChild("PlotItems")
						if plotItems then
							for _, d in ipairs(plotItems:GetDescendants()) do
								if d:IsA("Model") then
									tryAuraGrab(d)
								end
							end
						end
					end
				end

				local radius = Settings.Telekinesis.Radius
				local height = Settings.Telekinesis.Height
				local speed = Settings.Telekinesis.Speed

				angle = angle + math.rad(speed * 20) * dt
				if angle > math.pi * 2 then angle = angle - math.pi * 2 end

				-- throttle the expensive "did someone else grab this" scan to 4x per second
				-- instead of every frame per object (this was the main lag source)
				local checkGrabs = now - grabCheckScan > 0.25
				if checkGrabs then grabCheckScan = now end
				local itemList = {}
				for model, data in pairs(TelekinesisFeature.activeItems) do
					if model and model.Parent then
						local grabPart = checkGrabs and TelekinesisFeature.getNearbyGrabPart(model) or nil
						if grabPart then
							TelekinesisFeature.stopOrbit(model)
						else
							if not data.stuckCount then data.stuckCount = 0 end
							table.insert(itemList, {model = model, drivePart = data.drivePart, bp = data.bp, bg = data.bg, stuckCount = data.stuckCount, lastFling = data.lastFling})
						end
					else
						TelekinesisFeature.activeItems[model] = nil
					end
				end

				local count = #itemList
				local step = (math.pi * 2) / math.max(count, 1)

				-- Attack mode: assign 3-7 orbiting objects to each nearby player so they spin around them and fling them
				local attackAssignments = {}
				if Settings.Telekinesis.attackMode then
					local perPlayer = Settings.Telekinesis.attackObjectsPerPlayer or 5
					local targets = {}
					for _, plr in ipairs(Players:GetPlayers()) do
						if plr ~= LocalPlayer and plr.Character then
							local thrp = plr.Character:FindFirstChild("HumanoidRootPart")
							local thum = plr.Character:FindFirstChildOfClass("Humanoid")
							if thrp and thum and thum.Health > 0 and not isProtectedPlayer(plr.Name) then
								-- only assign objects to players actually near us, otherwise they
								-- get sent across the map and never come back
								local atkRange = Settings.Telekinesis.attackRange or 150
								if (thrp.Position - myRoot.Position).Magnitude <= atkRange then
									table.insert(targets, {hrp = thrp, count = 0})
								end
							end
						end
					end
					if #targets > 0 then
						local ti = 1
						for _, item in ipairs(itemList) do
							local t = targets[ti]
							if not t then break end
							attackAssignments[item.model] = t
							t.count = t.count + 1
							if t.count >= perPlayer then
								t.count = 0
								ti = ti + 1
								if ti > #targets then ti = 1 end
							end
						end
					end
				end

				-- Protect Friends mode: spread the objects around other players (friends)
				-- so they spin around them like a shield. Attack mode wins if both are on.
				local protectAssignments = {}
				local protectNames = {}
				if Settings.Telekinesis.protectFriends and not Settings.Telekinesis.attackMode then
					local targets = {}
					for _, plr in ipairs(Players:GetPlayers()) do
						if plr ~= LocalPlayer and plr.Character then
							local frp = plr.Character:FindFirstChild("HumanoidRootPart")
							local fhum = plr.Character:FindFirstChildOfClass("Humanoid")
							if frp and fhum and fhum.Health > 0 then
								table.insert(targets, {hrp = frp, count = 0})
								protectNames[plr.Name] = true
							end
						end
					end
					if #targets > 0 then
						local perFriend = 4
						local ti = 1
						for _, item in ipairs(itemList) do
							local t = targets[ti]
							if not t then break end
							protectAssignments[item.model] = t
							t.count = t.count + 1
							if t.count >= perFriend then
								t.count = 0
								ti = ti + 1
								if ti > #targets then ti = 1 end
							end
						end
					end
				end

				local centerPos = myRoot.Position + Vector3.new(0, height, 0)

				-- Nuke style: form the nuke on top of the MountainSnowTop mountain instead of on the player
				if Settings.Telekinesis.Style == "Nuke" then
					-- if the cached mountain got destroyed or streamed out, forget it so we rescan
					if nukeMountainPos and (not nukeMountainRef or not nukeMountainRef.Parent) then
						nukeMountainPos = nil
						nukeMountainRef = nil
					end
					if not nukeMountainPos and now - nukeMountainScan > 3 then
						nukeMountainScan = now
						local mountain = Workspace:FindFirstChild("MountainSnowTop")
							or Workspace:FindFirstChild("MountainSnowTop", true)
						if not mountain then
							-- fallback: search by name patterns in case it is nested or named slightly differently
							local patterns = {"mountainsnowtop", "snowtop", "snowmountain", "snow mountain", "mountain snow", "snowtopmountain"}
							for _, d in ipairs(Workspace:GetDescendants()) do
								local dn = string.lower(d.Name)
								for _, pat in ipairs(patterns) do
									if dn:find(pat) then
										mountain = d
										break
									end
								end
								if mountain then break end
							end
						end
						if mountain then
							local mCenter, mTop
							if mountain:IsA("Model") then
								local ok, cf, sz = pcall(mountain.GetBoundingBox, mountain)
								if ok then
									mCenter = cf.Position
									mTop = cf.Position.Y + sz.Y * 0.5
								end
							elseif mountain:IsA("BasePart") then
								mCenter = mountain.Position
								mTop = mountain.Position.Y + mountain.Size.Y * 0.5
							elseif mountain:IsA("Folder") then
								-- folder of parts: compute the bounds from the BaseParts inside it
								local min, max
								for _, d in ipairs(mountain:GetDescendants()) do
									if d:IsA("BasePart") then
										local p = d.Position
										local half = d.Size * 0.5
										local pmin, pmax = p - half, p + half
										if not min then
											min, max = pmin, pmax
										else
											min = Vector3.new(math.min(min.X, pmin.X), math.min(min.Y, pmin.Y), math.min(min.Z, pmin.Z))
											max = Vector3.new(math.max(max.X, pmax.X), math.max(max.Y, pmax.Y), math.max(max.Z, pmax.Z))
										end
									end
								end
								if min and max then
									mCenter = (min + max) * 0.5
									mTop = max.Y
								end
							end
							if mCenter then
								nukeMountainRef = mountain
								nukeMountainPos = Vector3.new(mCenter.X, mTop, mCenter.Z)
							end
						end
					end
					if nukeMountainPos then
						-- nuke spans centerPos.Y +/- height, so lift the center so the fins rest on the mountain top
						centerPos = Vector3.new(nukeMountainPos.X, nukeMountainPos.Y + height, nukeMountainPos.Z)
					end
				end

				for i, item in ipairs(itemList) do
					local itemAngle = angle + (step * (i - 1))
					local style = Settings.Telekinesis.Style
					-- orbital strike always forms the spinning stack above the player, never on the mountain
					if Settings.Telekinesis.orbitalStrike then style = "Orbital Strike" end
					local targetPos
					local customTangent = nil

					local atkTarget = attackAssignments[item.model]
					if atkTarget and atkTarget.hrp and atkTarget.hrp.Parent then
						-- spin the object around the target player and fling them when it gets close
						local thrp = atkTarget.hrp
						local atkAngle = angle * 4 + step * (i - 1)
						local atkR = 6
						targetPos = thrp.Position + Vector3.new(
							math.cos(atkAngle) * atkR,
							4 + math.sin(atkAngle * 2) * 2,
							math.sin(atkAngle) * atkR
						)
						local dpAtk = item.drivePart
						if dpAtk and dpAtk.Parent and (not item.lastFling or now - item.lastFling > 1.5) then
							local distAtk = (dpAtk.Position - thrp.Position).Magnitude
							if distAtk < 12 then
								item.lastFling = now
								local dataAtk = TelekinesisFeature.activeItems[item.model]
								if dataAtk then dataAtk.lastFling = now end
								task.spawn(function()
									-- request ownership, then WAIT for replication before flinging
									-- (setting velocity instantly was why attack players never worked)
										pcall(function() SetNetworkOwner:FireServer(thrp, thrp.CFrame) end)
										task.wait(0.3)
										if not thrp.Parent then return end
										local tChar = thrp.Parent
										local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
										if tHum and tHum.Health <= 0 then return end
										pcall(function() SetNetworkOwner:FireServer(thrp, thrp.CFrame) end)
										local power = Settings.Telekinesis.flingPower or 100
										local flingDir = thrp.Position - dpAtk.Position
										if flingDir.Magnitude < 0.1 then
											flingDir = Vector3.new(0, 1, 0)
										else
											flingDir = flingDir.Unit
										end
										thrp.AssemblyLinearVelocity = flingDir * power + Vector3.new(0, power * 0.6, 0)
										thrp.AssemblyAngularVelocity = Vector3.new(math.random(-30, 30), math.random(-30, 30), math.random(-30, 30))
									end)
							end
						end
					elseif protectAssignments[item.model] then
						-- Protect Friends: spin around the friend sweeping up & down,
						-- side to side, and corner to corner like a spinning shield
						local prot = protectAssignments[item.model]
						local frp = prot.hrp
						if frp and frp.Parent then
							local pa = angle * 5 + step * (i - 1)
							local pr = 5
							local sideX = math.cos(pa) * pr -- side to side
							local upDown = 3 + math.sin(pa * 2) * 3 -- up and down
							local diag = math.sin(pa * 0.5 + i) * pr * 0.8 -- corner to corner
							targetPos = frp.Position + Vector3.new(
								sideX + diag,
								upDown,
								math.sin(pa) * pr + diag
							)
							-- fling anyone who gets too close to the friend (except friends and me)
							local dpProt = item.drivePart
							if dpProt and dpProt.Parent then
								for _, plr2 in ipairs(Players:GetPlayers()) do
									if plr2 ~= LocalPlayer and plr2.Character and not protectNames[plr2.Name] then
										local erp = plr2.Character:FindFirstChild("HumanoidRootPart")
										if erp and erp.Parent and (erp.Position - frp.Position).Magnitude < 9 then
											if not protectFlingCd[plr2] or now - protectFlingCd[plr2] > 2 then
												protectFlingCd[plr2] = now
												task.spawn(function()
													pcall(function() SetNetworkOwner:FireServer(erp, erp.CFrame) end)
													task.wait(0.3)
													if not erp.Parent or not frp.Parent then return end
													local eChar = erp.Parent
													local eHum = eChar and eChar:FindFirstChildOfClass("Humanoid")
													if eHum and eHum.Health <= 0 then return end
													pcall(function() SetNetworkOwner:FireServer(erp, erp.CFrame) end)
													local power = Settings.Telekinesis.flingPower or 100
													local flingDir = erp.Position - frp.Position
													if flingDir.Magnitude < 0.1 then
														flingDir = Vector3.new(0, 1, 0)
													else
														flingDir = flingDir.Unit
													end
													erp.AssemblyLinearVelocity = flingDir * power + Vector3.new(0, power * 0.6, 0)
													erp.AssemblyAngularVelocity = Vector3.new(math.random(-30, 30), math.random(-30, 30), math.random(-30, 30))
												end)
												end
										end
									end
								end
							end
						else
							targetPos = centerPos + Vector3.new(
								math.cos(itemAngle) * radius,
								0,
								math.sin(itemAngle) * radius
							)
						end
					elseif Settings.Telekinesis.shieldWall then
						-- Shield Wall: 5x5 grid of objects 13 studs in front of the player
						local lookVec = myRoot.CFrame.LookVector
						local flatLook = Vector3.new(lookVec.X, 0, lookVec.Z)
						if flatLook.Magnitude < 0.01 then
							flatLook = Vector3.new(0, 0, -1)
						else
							flatLook = flatLook.Unit
						end
						local rightVec = Vector3.new(-flatLook.Z, 0, flatLook.X)
						local wallDist = 13
						local cols = 5
						local rows = math.max(1, math.ceil(count / cols))
						local col = (i - 1) % cols
						local row = math.floor((i - 1) / cols)
						local spacing = 1.5
						local offsetX = (col - (cols - 1) / 2) * spacing
						local offsetY = (row - (rows - 1) / 2) * spacing + 3
						targetPos = myRoot.Position
							+ flatLook * wallDist
							+ rightVec * offsetX
							+ Vector3.new(0, offsetY, 0)
					elseif Settings.Telekinesis.crazyRadius then
						local s = i * 1337.1
						local a1 = now * (15 + i * 4.3) + s
						local a2 = now * (19 + i * 3.1) + s * 2.3
						local a3 = now * (23 + i * 5.7) + s * 0.7
						local mapR = 2400
						local cx = (math.sin(a1) * 0.6 + math.cos(a2) * 0.4) * mapR
						local cz = (math.cos(a3) * 0.5 + math.sin(a2) * 0.5) * mapR
						targetPos = centerPos + Vector3.new(cx, 0, cz)
					elseif style == "Circle" then
						targetPos = centerPos + Vector3.new(
							math.cos(itemAngle) * radius,
							0,
							math.sin(itemAngle) * radius
						)
					elseif style == "Circle Up Down" then
						targetPos = centerPos + Vector3.new(
							math.cos(itemAngle) * radius,
							math.sin(itemAngle * 2) * height,
							math.sin(itemAngle) * radius
						)
					elseif style == "Square" then
						local t = (itemAngle % (math.pi * 2)) / (math.pi * 2) * 4
						local sx, sz
						if t < 1 then sx, sz = -1 + t * 2, -1
						elseif t < 2 then sx, sz = 1, -1 + (t - 1) * 2
						elseif t < 3 then sx, sz = 1 - (t - 2) * 2, 1
						else sx, sz = -1, 1 - (t - 3) * 2
						end
						targetPos = centerPos + Vector3.new(sx * radius, 0, sz * radius)
					elseif style == "Heart" then
						local sx = radius / 14
						local sy = height / 8
						local ht = itemAngle
						local hx = 16 * math.sin(ht) ^ 3
						local hy = 13 * math.cos(ht) - 5 * math.cos(2 * ht) - 2 * math.cos(3 * ht) - math.cos(4 * ht)
						local heartRight = Vector3.new(1, 0, 0)
						local heartUp = Vector3.new(0, 1, 0)
						targetPos = centerPos + heartRight * hx * sx + heartUp * hy * sy
						local dxdt = 48 * math.sin(ht) ^ 2 * math.cos(ht)
						local dydt = -13 * math.sin(ht) + 10 * math.sin(2 * ht) + 6 * math.sin(3 * ht) + math.sin(4 * ht)
						local hmag = math.sqrt(dxdt * dxdt + dydt * dydt)
						if hmag > 0.001 then
							customTangent = ((heartRight * dxdt + heartUp * dydt) / hmag)
						else
							customTangent = Vector3.new(1, 0, 0)
						end
					elseif style == "Tornado" then
						local itemCount = math.max(count, 1)
						local itemFrac = (i - 1) / itemCount
						local tornadoR = radius * (0.3 + itemFrac * 0.7)
						local tornadoY = itemFrac * height * 2 - height
						local baseSpin = angle + itemFrac * math.pi * 4
						local seed = i * 1337.1
						local randAngle = math.noise(seed, 0, 0) * math.pi * 2
						local randR = (math.noise(0, seed, 0) * 0.5 + 0.5) * tornadoR * 0.4
						local tornadoSpin = baseSpin + randAngle
						local finalR = tornadoR + randR
						targetPos = centerPos + Vector3.new(
							math.cos(tornadoSpin) * finalR,
							tornadoY + math.noise(seed, seed, 0) * height * 0.15,
							math.sin(tornadoSpin) * finalR
						)
						local tangX = -math.sin(tornadoSpin) * finalR * speed
						local tangZ = math.cos(tornadoSpin) * finalR * speed
						local tangY = height * 2 * 0.15 * speed / (math.pi * 2)
						local tmag = math.sqrt(tangX * tangX + tangY * tangY + tangZ * tangZ)
						if tmag > 0.001 then
							customTangent = Vector3.new(tangX, tangY, tangZ) / tmag
						end
					elseif style == "Nuke" then
						local seed = i * 1337.1
						local itemFrac = (i - 1) / math.max(count, 1)
						local finEnd = 0.40
						local bodyEnd = 0.70
						if itemFrac < finEnd then
							local finIdx = (i - 1) % 4
							local finAngle = finIdx * (math.pi / 2) + math.pi / 4
							local posInFin = math.floor((i - 1) / 4)
							local itemsPerFin = math.max(1, math.ceil(count * finEnd / 4))
							local finCols = math.max(1, math.ceil(math.sqrt(itemsPerFin)))
							local col = posInFin % finCols
							local row = math.floor(posInFin / finCols)
							local hFrac = itemsPerFin > 1 and math.min(row / (itemsPerFin - 1), 1) or 0.5
							local wFrac = finCols > 1 and ((col / (finCols - 1)) - 0.5) or 0
							local finY = -height + hFrac * height * (2 / 3)
							local finR = radius * (0.15 + hFrac * 0.85)
							local finHalfW = radius * 0.15
							local tangOff = wFrac * finHalfW
							local randR = (math.noise(0, seed, 0) * 0.5 + 0.5) * finR * 0.06
							local finalR = finR + randR
							targetPos = centerPos + Vector3.new(
								math.cos(finAngle) * finalR - math.sin(finAngle) * tangOff,
								finY + math.noise(seed, seed, 0) * height * 0.02,
								math.sin(finAngle) * finalR + math.cos(finAngle) * tangOff
							)
						elseif itemFrac < bodyEnd then
							-- main body: stacked rings forming a solid cylinder wall
							local bodyStartIdx = math.floor(count * finEnd)
							local bodyIdx = (i - 1) - bodyStartIdx
							local bodyTotal = math.max(1, math.floor(count * bodyEnd) - bodyStartIdx)
							local bodyRings = math.max(2, math.floor(bodyTotal / 3))
							local ringIdx = bodyIdx % bodyRings
							local posInRing = math.floor(bodyIdx / bodyRings)
							local perRing = math.max(1, math.ceil(bodyTotal / bodyRings))
							local ringFrac = bodyRings > 1 and (ringIdx / (bodyRings - 1)) or 0.5
							local bodyY = -height / 3 + ringFrac * (height * 2 / 3)
							local bodyR = radius * 0.7
							local ringAngle = (posInRing / perRing) * math.pi * 2 + ringIdx * (math.pi / perRing)
							local randR = (math.noise(0, seed, 0) * 0.5 + 0.5) * bodyR * 0.04
							local finalR = bodyR + randR
							targetPos = centerPos + Vector3.new(
								math.cos(ringAngle) * finalR,
								bodyY + math.noise(seed, seed, 0) * height * 0.01,
								math.sin(ringAngle) * finalR
							)
						else
							-- nose cone: stacked rings tapering sharply from the body radius up to a single point at the top
							local coneStartIdx = math.floor(count * bodyEnd)
							local coneIdx = (i - 1) - coneStartIdx
							local coneTotal = math.max(1, count - coneStartIdx)
							local coneRings = math.max(2, math.floor(coneTotal / 3))
							local ringIdx = coneIdx % coneRings
							local posInRing = math.floor(coneIdx / coneRings)
							local perRing = math.max(1, math.ceil(coneTotal / coneRings))
							local ringFrac = coneRings > 1 and (ringIdx / (coneRings - 1)) or 1
							-- sharp linear taper: full body radius at the base, closing to a point at the tip
							local coneR = radius * 0.7 * (1 - ringFrac)
							local minTip = radius * 0.02
							if coneR < minTip then coneR = minTip end
							local coneY = height / 3 + ringFrac * (height * 2 / 3)
							local ringAngle = (posInRing / perRing) * math.pi * 2 + ringIdx * (math.pi / perRing)
							local randR = (math.noise(0, seed, 0) * 0.5 + 0.5) * coneR * 0.05
							local finalR = coneR + randR
							targetPos = centerPos + Vector3.new(
								math.cos(ringAngle) * finalR,
								coneY + math.noise(seed, seed, 0) * height * 0.01,
								math.sin(ringAngle) * finalR
							)
						end
					elseif style == "Galactic" then
						local arms = 4
						local armIdx = (i - 1) % arms
						local armPhase = armIdx * (math.pi * 2 / arms)
						local objectsPerArm = math.max(1, math.floor(count / arms))
						local posInArm = math.floor((i - 1) / arms)
						local armFrac = objectsPerArm > 1 and (posInArm / (objectsPerArm - 1)) or 0.5
						local galR = radius * (0.08 + armFrac * 0.92)
						local spiralTight = 2.5
						local galAngle = armPhase + armFrac * spiralTight + itemAngle * 0.3
						local galY = math.sin(armFrac * math.pi * 2 + itemAngle * 0.2) * height * 0.25
						targetPos = centerPos + Vector3.new(
							math.cos(galAngle) * galR,
							galY,
							math.sin(galAngle) * galR
						)
					elseif style == "Wave" then
						local waveX = ((i - 1) / math.max(1, count - 1) - 0.5) * radius * 2
						local waveY = math.sin(waveX / radius * math.pi * 2 + itemAngle * 2) * height
						local waveZ = math.cos(waveX / radius * math.pi * 2 + itemAngle * 2) * height * 0.5
						targetPos = centerPos + Vector3.new(waveX, waveY, waveZ)
					elseif style == "Infinity" then
						local ix = radius * math.sin(itemAngle)
						local iz = radius * math.sin(itemAngle) * math.cos(itemAngle)
						targetPos = centerPos + Vector3.new(ix, 0, iz)
					elseif style == "Christmas Tree" then
						local normPos = (i - 1) / math.max(count, 1)
						local treeH = Settings.Telekinesis.TreeHeight
						local layerRadius = radius * (1 - normPos)
						local layerHeight = treeH * normPos
						local layerAngle = math.rad((angle * 360 + i * 30) % 360)
						targetPos = centerPos + Vector3.new(
							math.cos(layerAngle) * layerRadius,
							layerHeight,
							math.sin(layerAngle) * layerRadius
						)
					elseif style == "Orbital Strike" then
						-- missile battery hovers BEHIND the player along the aim direction,
						-- stacked in columns so every shot flies straight over your shoulder
						local cam = Workspace.CurrentCamera
						local lookVec = (cam and cam.CFrame.LookVector) or myRoot.CFrame.LookVector
						local flatLook = Vector3.new(lookVec.X, 0, lookVec.Z)
						if flatLook.Magnitude < 0.01 then
							flatLook = Vector3.new(0, 0, -1)
						else
							flatLook = flatLook.Unit
						end
						local rightVec = Vector3.new(-flatLook.Z, 0, flatLook.X)
						local perCol = 3
						local col = math.floor((i - 1) / perCol)
						local row = (i - 1) % perCol
						local backDist = 34 + col * 7
						local bob = math.sin(now * 2.5 + i * 1.3) * 0.6
						local sway = math.sin(now * 1.5 + col * 0.8) * 1.2
						targetPos = myRoot.Position
							- flatLook * backDist
							+ rightVec * sway
							+ Vector3.new(0, 7 + row * 4.5 + bob, 0)
					elseif style == "Wings" then
						local half = math.ceil(count / 2)
						local isLeft = i <= half
						local side = isLeft and -1 or 1
						local wingIdx = isLeft and (half - i + 1) or (i - half)
						local lookVec = myRoot.CFrame.LookVector
						local rightVec = myRoot.CFrame.RightVector
						local backVec = -lookVec
						local normPos = wingIdx / math.max(half, 1)
						local minDist = 3
						local spread = math.max(minDist, radius * normPos + minDist)
						local yOffset = height * normPos * 0.5
						local backOffset = radius * 0.1 * (1 - normPos * 0.3)
						local flapY = math.sin(tick() * speed) * height * normPos
						targetPos = myRoot.Position
							+ rightVec * side * spread
							+ backVec * backOffset
							+ Vector3.new(0, yOffset + flapY, 0)
					elseif style == "Spiral" then
						local spiralAngle = angle + step * (i - 1)
						local baseY = math.sin(now * 40 + i * 2.3) * height * 3
						local sharpY = math.sin(now * 90 + i * 5.7) * height * 1.5
						local jitterY = baseY + sharpY
						targetPos = centerPos + Vector3.new(
							math.cos(spiralAngle) * radius,
							jitterY,
							math.sin(spiralAngle) * radius
						)
					else
						targetPos = centerPos + Vector3.new(
							math.cos(itemAngle) * radius,
							0,
							math.sin(itemAngle) * radius
						)
					end

					if not item.drivePart or not item.drivePart.Parent then
						item.drivePart = item.model:FindFirstChild("SoundPart")
							or item.model:FindFirstChildWhichIsA("BasePart")
					end
					local drivePart = item.drivePart
					if drivePart and drivePart.Parent then
						-- reuse the throttled scan instead of re-scanning every frame
						local nearbyGrabPart = checkGrabs and TelekinesisFeature.getNearbyGrabPart(item.model) or nil

						if nearbyGrabPart then
							if not item.regrabRunning then                                item.regrabRunning = true
								task.spawn(function()
									local dp = drivePart
									local mdl = item.model
									if not dp or not dp.Parent then item.regrabRunning = false return end
									-- no teleport, one remote per assembly using the part's own CFrame
									local seen = {}
									for _, part in ipairs(mdl:GetDescendants()) do
										if part:IsA("BasePart") and part.Parent then
											local asmRoot = part.AssemblyRootPart or part
											if not seen[asmRoot] then
												seen[asmRoot] = true
												pcall(function() SetNetworkOwner:FireServer(part, part.CFrame) end)
											end
										end
									end
									pcall(function() CreateGrabLine:FireServer(dp, Vector3.zero, dp.Position, false) end)
									pcall(function() DestroyGrabLine:FireServer(dp) end)
									task.wait(0.05)
									for _, part in ipairs(mdl:GetDescendants()) do
										if part:IsA("BasePart") then
											part.CanCollide = false
											part.Anchored = false
										end
									end
									local bp = dp:FindFirstChildOfClass("BodyPosition")
									if not bp then
										bp = Instance.new("BodyPosition")
										bp.MaxForce = Vector3.new(5e18, 5e18, 5e18)
										bp.D = 1000
										bp.P = 50000
										bp.Parent = dp
									end
									item.bp = bp
									local bg = dp:FindFirstChildOfClass("BodyGyro")
									if not bg then
										bg = Instance.new("BodyGyro")
										bg.MaxTorque = Vector3.new(5e18, 5e18, 5e18)
										bg.D = 1000
										bg.P = 50000
										bg.Parent = dp
									end
									item.bg = bg
									item.regrabRunning = false
								end)
							end
						else
							-- only sweep CanCollide when the throttled scan ran, not every frame
							if checkGrabs then
								for _, part in ipairs(item.model:GetDescendants()) do
									if part:IsA("BasePart") then
										part.CanCollide = false
									end
								end
							end
							if drivePart.Anchored then drivePart.Anchored = false end
							local bp = drivePart:FindFirstChildOfClass("BodyPosition")
							if not bp then
								bp = Instance.new("BodyPosition")
								bp.MaxForce = Vector3.new(5e18, 5e18, 5e18)
								bp.D = 1000
								bp.P = 50000
								bp.Parent = drivePart
							end
							item.bp = bp
							local bg = drivePart:FindFirstChildOfClass("BodyGyro")
							if not bg then
								bg = Instance.new("BodyGyro")
								bg.MaxTorque = Vector3.new(5e18, 5e18, 5e18)
								bg.D = 1000
								bg.P = 50000
								bg.Parent = drivePart
							end
							item.bg = bg
							pcall(function()
								bp.Position = targetPos
								if Settings.Telekinesis.lookAtMe then
									local dirXZ = (myRoot.Position - drivePart.Position) * Vector3.new(1, 0, 1)
									if dirXZ.Magnitude > 0.01 then
										bg.CFrame = CFrame.new(drivePart.Position, drivePart.Position + dirXZ.Unit)
									end
								else
									local targetRot = CFrame.Angles(
										math.rad(Settings.Telekinesis.RotX),
										math.rad(Settings.Telekinesis.RotY),
										math.rad(Settings.Telekinesis.RotZ)
									)
									bg.CFrame = CFrame.new(drivePart.Position) * targetRot
								end
							end)
						end
					end
				end
			end
			TelekinesisFeature.auraConn = nil
		end)
		-- watchdog: if the aura loop thread ever dies from a runtime error,
		-- restart it automatically so objects never freeze at spawn again
		task.spawn(function()
			local thread = TelekinesisFeature.auraConn
			while thread and TelekinesisFeature.auraConn == thread do
				task.wait(1)
				if TelekinesisFeature.auraConn ~= thread then break end
				if coroutine.status(thread) == "dead" then
					TelekinesisFeature.auraConn = nil
					if Settings.Telekinesis.Enabled then
						warn("[Telekinesis] aura loop crashed - restarting it")
						TelekinesisFeature.runAura()
					end
					break
				end
			end
		end)
	end

	function TelekinesisFeature.startSpawnedWatcher()
		if TelekinesisFeature.spawnConn then return end
		local SpawnedInToys = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		if not SpawnedInToys then return end
		TelekinesisFeature.spawnConn = SpawnedInToys.ChildAdded:Connect(function(child)
			if not Settings.Telekinesis.Enabled then return end
			if not Settings.Telekinesis.TargetSpawned then return end
			local myChar = LocalPlayer.Character
			local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
			if not myRoot then return end
			local dp = TelekinesisFeature.getDrivePart(child)
			if not dp then return end
			pcall(function() SetNetworkOwner:FireServer(dp, dp.CFrame) end)
			pcall(function() CreateGrabLine:FireServer(dp, Vector3.zero, dp.Position, false) end)
			pcall(function() DestroyGrabLine:FireServer(dp) end)
			task.wait(0.05)
			TelekinesisFeature.startOrbit(child, true)
		end)
	end

	function TelekinesisFeature.stopSpawnedWatcher()
		if TelekinesisFeature.spawnConn then TelekinesisFeature.spawnConn:Disconnect() TelekinesisFeature.spawnConn = nil end
	end

	function TelekinesisFeature.scanPlotItems()
		local plotItems = Workspace:FindFirstChild("PlotItems")
		if not plotItems then return end
		for i = 1, 5 do
			local plotFolder = plotItems:FindFirstChild("Plot" .. i)
			if plotFolder then
				for _, model in ipairs(plotFolder:GetDescendants()) do
					if model:IsA("Model") and not TelekinesisFeature.isFloorThing(model) and not TelekinesisFeature.activeItems[model] then
						local dp = TelekinesisFeature.getDrivePart(model)
						if dp then
							TelekinesisFeature.startOrbit(model, true)
						end
					end
				end
			end
		end
	end

	function TelekinesisFeature.scanSpawnedToys()
		local SpawnedInToys = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		if not SpawnedInToys then return end
		local myChar = LocalPlayer.Character
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
		if not myRoot then return end
		for _, child in ipairs(SpawnedInToys:GetChildren()) do
			if not TelekinesisFeature.activeItems[child] then
				local dp = TelekinesisFeature.getDrivePart(child)
				if dp then
					pcall(function() SetNetworkOwner:FireServer(dp, dp.CFrame) end)
					pcall(function() CreateGrabLine:FireServer(dp, Vector3.zero, dp.Position, false) end)
					pcall(function() DestroyGrabLine:FireServer(dp) end)
					TelekinesisFeature.startOrbit(child, true)
				end
			end
		end
	end

	TelekinesisFeature.palletExploreConn = nil

	function TelekinesisFeature.startPalletExplore()
		if TelekinesisFeature.palletExploreConn then return end
		local function getGrabbedPart()
			local grabParts = Workspace:FindFirstChild("GrabParts")
			if not grabParts then return nil end
			for _, gp in ipairs(grabParts:GetChildren()) do
				if gp.Name == "GrabPart" then
					local weld = gp:FindFirstChildOfClass("WeldConstraint")
						or gp:FindFirstChildOfClass("Weld")
						or gp:FindFirstChildOfClass("ManualWeld")
					if weld then
						local p0 = weld.Part0
						local p1 = weld.Part1
						if p1 and p1 ~= gp then return p1 end
						if p0 and p0 ~= gp then return p0 end
					end
				end
			end
			return nil
		end
		local dp = getGrabbedPart()
		if not dp then return end
		local targetModel = dp.Parent
		if not targetModel then return end

		local highlight = Instance.new("Highlight")
		highlight.FillColor = Color3.fromRGB(0, 170, 255)
		highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
		highlight.FillTransparency = 0.5
		highlight.OutlineTransparency = 0
		highlight.Parent = targetModel

		local rad = math.rad
		local function makeRot(rx, ry, rz)
			return CFrame.Angles(rad(rx), rad(ry), rad(rz))
		end

		local waypoints = {
			{pos = Vector3.new(-316.27703857421875, 56.2031364440918, -179.00755310058594), rot = makeRot(0.017999999225139618, 27.718000411987305, 0.019999999552965164), waitTime = 5},
			{pos = Vector3.new(-401.4556884765625, 28.313364028930664, -130.06117248535156), rot = makeRot(-179.7570037841797, -71.60399627685547, 179.79600524902344), waitTime = 3},
			{pos = Vector3.new(-452.55908203125, 24.746112823486328, 42.982810974121094), rot = makeRot(-0.2460000067949295, -70.1259994506836, -0.46000000834465027), waitTime = 3},
			{pos = Vector3.new(-299.23150634765625, 95.85819244384766, 217.03387451171875), rot = makeRot(0.003000000026077032, 13.48900032043457, 0.017999999225139618), waitTime = 5},
			{pos = Vector3.new(-213.0196990966797, 80.20887756347656, 396.256591796875), rot = makeRot(0.04600000008940697, -0.17499999701976776, 0.0020000000949949026), waitTime = 7},
			{pos = Vector3.new(-59.78620910644531, 156.22940063476562, 368.65545654296875), rot = makeRot(-179.89199829101562, 6.166999816894531, -179.98699951171875), waitTime = 3},
			{pos = Vector3.new(185.5255889892578, 16.997987747192383, 396.1617736816406), rot = makeRot(0.21199999749660492, 55.944000244140625, -0.12300000339746475), waitTime = 3},
			{pos = Vector3.new(223.5327911376953, 179.19735717773438, 174.54293823242188), rot = makeRot(-0.10100000351667404, 78.58100128173828, 0.17399999499320984), waitTime = 5},
			{pos = Vector3.new(-97.45641326904297, 86.93302154541016, -178.3148956298828), rot = makeRot(177.04600524902344, -32.340999603271484, 176.04100036621094), waitTime = 3},
			{pos = Vector3.new(-196.11106872558594, 82.6692123413086, -285.0792236328125), rot = makeRot(-179.74899291992188, -45.652000427246094, -179.89500427246094), waitTime = 3},
			{pos = Vector3.new(-102.37547302246094, 85.39105987548828, -210.48292541503906), rot = makeRot(-11.321999549865723, 89.36499786376953, 11.734999656677246), waitTime = 4},
			{pos = Vector3.new(451.05316162109375, 103.48825073242188, -260.166259765625), rot = makeRot(-179.8719940185547, 39.3489990234375, -179.68800354003906), waitTime = 3},
			{pos = Vector3.new(440.869140625, 153.43955993652344, -86.38394165039062), rot = makeRot(-179.30499267578125, 85.6520004272461, 179.7209930419922), waitTime = 3},
			{pos = Vector3.new(196.41908264160156, 32.962947845458984, 150.6081085205078), rot = makeRot(-0.0020000000949949026, -46.44499969482422, 0.00800000037997961), waitTime = 4},
			{pos = Vector3.new(-191.9010772705078, 26.14925765991211, -5.109410762786865), rot = makeRot(-168.9219970703125, 89.90899658203125, 168.8679962158203), waitTime = 6},
			{pos = Vector3.new(-503.68096923828125, 253.42152404785156, 382.37152099609375), rot = makeRot(179.99099731445312, -21.702999114990234, -179.93899536132812), waitTime = 4},
		}

		TelekinesisFeature.palletExploreConn = task.spawn(function()
			local maxSpeed = 80
			local arriveRadius = 1.5
			local accelDist = 5
			local decelDist = 10
			local holdSpringK = 20
			local waypointIdx = 1
			local segTotalDist = (waypoints[1].pos - dp.Position).Magnitude
			local segStartRot = dp.CFrame - dp.Position

			while Settings.Telekinesis.palletExplore do
				if not dp or not dp.Parent then break end

				local wp = waypoints[waypointIdx]
				if not wp then
					waypointIdx = 1
					wp = waypoints[waypointIdx]
					segTotalDist = (wp.pos - dp.Position).Magnitude
					segStartRot = dp.CFrame - dp.Position
				end

				local diff = wp.pos - dp.Position
				local dist = diff.Magnitude

				if dist < arriveRadius then
					if wp.waitTime <= 0 then
						waypointIdx = waypointIdx + 1
						segStartRot = dp.CFrame - dp.Position
						if waypointIdx <= #waypoints then
							segTotalDist = (waypoints[waypointIdx].pos - dp.Position).Magnitude
						end
						continue
					end

					local elapsed = 0
					local holdRotStart = dp.CFrame - dp.Position
					local holdRotTime = 0.3
					local prevVel = dp.AssemblyLinearVelocity
					while elapsed < wp.waitTime do
						if not Settings.Telekinesis.palletExplore then break end
						if not dp or not dp.Parent then break end

						local posErr = wp.pos - dp.Position
						local springVel = posErr * holdSpringK
						local blendIn = math.clamp(elapsed / 0.3, 0, 1)
						dp.AssemblyLinearVelocity = prevVel:Lerp(springVel, blendIn)
						prevVel = dp.AssemblyLinearVelocity

						local rotBlend = math.clamp(elapsed / holdRotTime, 0, 1)
						local smoothBlend = rotBlend * rotBlend * (3 - 2 * rotBlend)
						dp.CFrame = CFrame.new(dp.Position) * holdRotStart:Lerp(wp.rot, smoothBlend)
						dp.AssemblyAngularVelocity = Vector3.zero
						dp.RotVelocity = Vector3.zero

						local dt = RunService.Heartbeat:Wait()
						elapsed = elapsed + dt
					end

					waypointIdx = waypointIdx + 1
					segStartRot = wp.rot
					if waypointIdx <= #waypoints then
						segTotalDist = (waypoints[waypointIdx].pos - dp.Position).Magnitude
					end
				else
					local traveledDist = math.clamp(segTotalDist - dist, 0, segTotalDist)
					local accelPhase = math.clamp(traveledDist / accelDist, 0, 1)
					local decelPhase = math.clamp(dist / decelDist, 0, 1)
					local speedMult = math.min(accelPhase, decelPhase)
					speedMult = math.clamp(speedMult, 0.05, 1)
					speedMult = speedMult * speedMult * (3 - 2 * speedMult)

					local progress = math.clamp(traveledDist / math.max(segTotalDist, 1), 0, 1)
					local smoothProgress = progress * progress * (3 - 2 * progress)
					local interpRot = segStartRot:Lerp(wp.rot, smoothProgress)

					dp.AssemblyLinearVelocity = diff.Unit * maxSpeed * speedMult
					dp.CFrame = CFrame.new(dp.Position) * interpRot
					dp.AssemblyAngularVelocity = Vector3.zero
					dp.RotVelocity = Vector3.zero

					RunService.Heartbeat:Wait()
				end
			end

			if dp and dp.Parent then
				dp.AssemblyLinearVelocity = Vector3.zero
				dp.AssemblyAngularVelocity = Vector3.zero
				dp.RotVelocity = Vector3.zero
			end
			if highlight and highlight.Parent then highlight:Destroy() end
			TelekinesisFeature.palletExploreConn = nil
		end)
	end

