-- ---------------- KICKS (fluxy blobman) ----------------
local fluxyKickSec = ServerTab:Section({Text = "Mass Kick"})
fluxyKickSec:Toggle({Text = "Blobman Kick All", Flag = "FluxyKickAll", Default = false, Callback = function(enabled)
	Settings.Fluxy.kickAllActive = enabled
	if enabled then
		task.spawn(function()
			local side = "Left"
			local lastBlobSpawn = 0
			while Settings.Fluxy.kickAllActive do
				pcall(function()
					local toys = fluxyGetToysFolder()
					local blobman = toys and toys:FindFirstChild("CreatureBlobman")
					if not blobman then
						-- auto-spawn a blobman if we don't have one (5s cooldown)
						local root = fluxyGetRoot()
						local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
						local spawnRF = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
						if spawnRF and root and tick() - lastBlobSpawn > 5 then
							lastBlobSpawn = tick()
							pcall(function() spawnRF:InvokeServer("CreatureBlobman", root.CFrame * CFrame.new(0, 0, -6), Vector3.zero) end)
						end
						return
					end
					local detector = blobman:FindFirstChild(side .. "Detector")
					local weld = detector and detector:FindFirstChild(side .. "Weld")
					local grabScript = blobman:FindFirstChild("BlobmanSeatAndOwnerScript")
					local creatureGrab = grabScript and grabScript:FindFirstChild("CreatureGrab")
					if detector and weld and creatureGrab then
						for _, plr in ipairs(Players:GetPlayers()) do
							if plr ~= LocalPlayer and not isProtectedPlayer(plr.Name) and plr.Character then
								local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
								if hrp then
									pcall(function() creatureGrab:FireServer(detector, hrp, weld) end)
								end
							end
						end
					end
				end)
				side = (side == "Left") and "Right" or "Left"
				task.wait(0.15)
			end
		end)
	end
end})
fluxyKickSec:Toggle({Text = "Auto Fling Attackers", Flag = "FluxyFlingAttackers", Default = false, Callback = function(enabled)
	Settings.Fluxy.flingAttackersActive = enabled
	if enabled then
		task.spawn(function()
			while Settings.Fluxy.flingAttackersActive do
				pcall(function()
					local char = LocalPlayer.Character
					local head = char and char:FindFirstChild("Head")
					local partOwner = head and head:FindFirstChild("PartOwner")
					if partOwner then
						local attacker = Players:FindFirstChild(partOwner.Value)
						if attacker and attacker.Character then
							local aRoot = attacker.Character:FindFirstChild("HumanoidRootPart")
							local aHead = attacker.Character:FindFirstChild("Head")
							if aRoot and aHead then
								pcall(function() fluxySetOwner:FireServer(aHead, aRoot.CFrame) end)
								task.wait(0.1)
								local torso = attacker.Character:FindFirstChild("Torso") or aRoot
								local bv = torso:FindFirstChild("FluxyFlingBV") or Instance.new("BodyVelocity")
								bv.Name = "FluxyFlingBV"
								bv.Velocity = Vector3.new(math.random(-200, 200), 5000, math.random(-200, 200))
								bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
								bv.Parent = torso
								Debris:AddItem(bv, 3)
							end
						end
					end
				end)
				task.wait(0.05)
			end
		end)
	end
end})

-- ---------------- KILLS (fluxy) ----------------
local fluxyKillSec = FluxyTab:Section({Text = "Kills"})
local fluxyKillGrabConn = nil
fluxyKillSec:Toggle({Text = "Kill Grab (BreakJoints On Grabbed)", Flag = "FluxyKillGrab", Default = false, Callback = function(enabled)
	Settings.Fluxy.killGrabActive = enabled
	if enabled then
		local function onGrabPartsAdded(child)
			if not Settings.Fluxy.killGrabActive then return end
			if child.Name == "GrabParts" then
				task.wait(0.1)
				pcall(function()
					local grabPart = child:FindFirstChild("GrabPart")
					local weld = grabPart and grabPart:FindFirstChild("WeldConstraint")
					local part1 = weld and weld.Part1
					if part1 and part1.Parent then
						part1.Parent:BreakJoints()
					end
				end)
			end
		end
		fluxyKillGrabConn = Workspace.DescendantAdded:Connect(onGrabPartsAdded)
	else
		if fluxyKillGrabConn then fluxyKillGrabConn:Disconnect() fluxyKillGrabConn = nil end
	end
end})

end) -- close FTAP task.spawn

