-- ========== Shuriken Controller (hub UI only — Server tab) ==========
task.spawn(function()
	local Players = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local LocalPlayer = Players.LocalPlayer

	local function startShurikens()
		local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
		local HumanoidRootPart = char:WaitForChild("HumanoidRootPart")
		local SpawnedInToys = workspace:WaitForChild(LocalPlayer.Name .. "SpawnedInToys", 5)
		if not SpawnedInToys then warn("[Fluxy] No SpawnedInToys") return end
		local grassRoot = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("BaseGround")
		if not grassRoot then warn("[Fluxy] Map/BaseGround missing") return end
		local Grass = grassRoot:GetDescendants()
		local UsedShurks = {}
		local positions = {
			Vector3.new(107.5, -101.350403, 43.3749657),
			Vector3.new(-9.50007629, -101.350403, -76.625),
			Vector3.new(90.5, -101.350403, -76.625),
		}
		for i, pos in ipairs(positions) do
			local target, dist = nil, math.huge
			for _, obj in ipairs(Grass) do
				if obj:IsA("BasePart") and obj.Name == "Grass" and not UsedShurks[obj] then
					local d = (obj.Position - pos).Magnitude
					if d < dist then target, dist = obj, d end
				end
			end
			if not target then warn("[Fluxy] No grass for pos", i) continue end
			UsedShurks[target] = true
			local shuriken = nil
			local conn
			conn = SpawnedInToys.ChildAdded:Connect(function(child)
				if child.Name == "NinjaShuriken" or string.find(child.Name, "Shuriken") then
					shuriken = child
					conn:Disconnect()
				end
			end)
			local canSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
			if canSpawn and not canSpawn.Value then
				pcall(function() canSpawn.Changed:Wait() end)
			end
			task.spawn(function()
				pcall(function()
					ReplicatedStorage.MenuToys.SpawnToyRemoteFunction:InvokeServer(
						"NinjaShuriken",
						HumanoidRootPart.CFrame * CFrame.new(5, 10, 20),
						Vector3.new()
					)
				end)
			end)
			local timeout = 0
			while not shuriken and timeout < 50 do
				task.wait(0.1)
				timeout += 1
			end
			if not shuriken then
				if conn then conn:Disconnect() end
				continue
			end
			local sticky = shuriken:WaitForChild("StickyPart", 3)
			if not sticky then continue end
			for _ = 1, 40 do
				pcall(function()
					ReplicatedStorage.GrabEvents.SetNetworkOwner:FireServer(sticky, sticky.CFrame)
				end)
				if sticky:FindFirstChild("PartOwner") and sticky.PartOwner.Value == LocalPlayer.Name then break end
				task.wait(0.05)
			end
			pcall(function()
				ReplicatedStorage.PlayerEvents.StickyPartEvent:FireServer(
					sticky, target, CFrame.new(1e12, 1e12, 1e12)
				)
			end)
			task.wait(0.3)
		end
	end

	local function stopShurikens()
		local SpawnedInToys = workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
		if not SpawnedInToys then return end
		local MenuToys = ReplicatedStorage:FindFirstChild("MenuToys")
		local possibleRemotes = {
			"DespawnToyRemoteFunction", "RemoveToyRemoteFunction", "DeleteToyRemoteFunction",
			"DespawnToy", "RemoveToy", "DeleteToy", "DestroyToy", "ClearToy",
		}
		for _, child in ipairs(SpawnedInToys:GetChildren()) do
			if child.Name == "NinjaShuriken" or string.find(child.Name, "Shuriken") then
				if MenuToys then
					for _, remoteName in ipairs(possibleRemotes) do
						local remote = MenuToys:FindFirstChild(remoteName)
						if remote then
							pcall(function()
								if remote:IsA("RemoteFunction") then remote:InvokeServer(child)
								elseif remote:IsA("RemoteEvent") then remote:FireServer(child) end
							end)
						end
					end
				end
				local PlayerEvents = ReplicatedStorage:FindFirstChild("PlayerEvents")
				if PlayerEvents then
					for _, remoteName in ipairs({"DespawnToy", "RemoveToy", "DeleteToy", "ClearToys"}) do
						local remote = PlayerEvents:FindFirstChild(remoteName)
						if remote then
							pcall(function()
								if remote:IsA("RemoteFunction") then remote:InvokeServer(child)
								else remote:FireServer(child) end
							end)
						end
					end
				end
				local sticky = child:FindFirstChild("StickyPart")
				if sticky then
					pcall(function()
						local pe = ReplicatedStorage:FindFirstChild("PlayerEvents")
						if pe and pe:FindFirstChild("StickyPartEvent") then
							pe.StickyPartEvent:FireServer(sticky, nil, CFrame.new())
						end
					end)
				end
				pcall(function() child:Destroy() end)
			end
		end
	end

	-- Destroy leftover floating GUI if any
	pcall(function()
		local pg = LocalPlayer:FindFirstChild("PlayerGui")
		if pg and pg:FindFirstChild("ShurikenController") then
			pg.ShurikenController:Destroy()
		end
	end)

	-- Hub only: Server tab
	pcall(function()
		if not Tabs or not Tabs.Server then return end
		local grp = Tabs.Server:CreateBlock({Name = "Shuriken Map", Side = "Left"})
		if not grp then return end
		grp:CreateButton({
			Name = "Start Shurikens",
			Callback = function()
				task.spawn(startShurikens)
			end,
		})
		grp:CreateButton({
			Name = "Stop Shurikens",
			Callback = function()
				task.spawn(stopShurikens)
			end,
		})
	end)
end)


