-- Keep main content scroll position when dropdowns open (Zyrix used to reset to top)
task.spawn(function()
	local genv = (getgenv and getgenv()) or _G
	for _ = 1, 100 do
		local sg = nil
		pcall(function()
			local hui = gethui and gethui()
			if hui then sg = hui:FindFirstChild("ZyrixMainUI") end
		end)
		if not sg then
			pcall(function()
				local pg = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
				if pg then sg = pg:FindFirstChild("ZyrixMainUI") end
			end)
		end
		if sg then
			local elements = sg:FindFirstChild("Elements", true) or sg:FindFirstChildWhichIsA("ScrollingFrame", true)
			-- find the main content scrolling frame
			for _, d in ipairs(sg:GetDescendants()) do
				if d:IsA("ScrollingFrame") and d.Name == "Elements" then
					elements = d
					break
				end
			end
			if elements and not elements:GetAttribute("FluxyScrollFix") then
				elements:SetAttribute("FluxyScrollFix", true)
				local lastY = 0
				elements:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
					local y = elements.CanvasPosition.Y
					-- if something forced jump to 0 from a large value, restore
					if y < 1 and lastY > 40 then
						task.defer(function()
							if elements.CanvasPosition.Y < 1 then
								elements.CanvasPosition = Vector2.new(elements.CanvasPosition.X, lastY)
							end
						end)
					else
						lastY = y
					end
				end)
			end
			break
		end
		task.wait(0.15)
	end
end)
